/*
 * 歴史総合(必履修・高1)のテキスト本文。書式は lessons_1.js 冒頭のコメントと同じ。
 * 図解(flow:色ブロックの流れ図 / chain:因果の鎖)の書式は lessons_zukai.js を参照。
 */
window.WPS = window.WPS || {};
WPS.LESSONS = WPS.LESSONS || {};
(function (L) {
  // ===== 近代化と私たち =====
  L.hs_kindai = {
    goal: '18世紀後半の「二つの革命」(イギリスの産業革命と、アメリカ独立革命・フランス革命)がなぜ起き、世界をどう変えたかを、アジアや日本とのつながりも含めて説明できるようになる。',
    intro: 'いま私たちが着ている服の多くは工場の機械で大量につくられ、私たちは選挙で代表を選びます。どちらも当たり前に見えますが、始まりは18世紀後半のヨーロッパとアメリカです。機械で大量生産する【産業革命】と、国の主人は王ではなく国民だとする【市民革命】。この「二つの革命」が、のちに日本を開国させ、明治の近代化にもつながっていきます。',
    pre: '中学では、ヨーロッパの国々が大航海時代(15〜16世紀)にアジアやアメリカ大陸へ進出したことを学びました。\n17世紀のイギリスでは、議会が国王の勝手な政治をおさえる【名誉革命】(1688〜89年)が起き、【権利の章典】(1689年)で議会の権限が確認されました。\nこのころの日本は江戸時代で、幕府は長崎などの限られた窓口でだけ外国と交流していました(いわゆる鎖国)。\n【近代化】とは、ここでは主に、①機械による工業化、②身分によらず国民が政治に参加するしくみ、③国民がまとまる国家、の3つが進むことを指します。歴史総合では、この近代化が世界と日本にどう広がったかを学びます。',
    secs: [
      { h: '18世紀の世界:豊かなアジアとヨーロッパ', t: 'なぜ18世紀のアジアから見始めるのでしょうか。それは、産業革命の前、世界でもっとも豊かな地域の一つがアジアだったからです。\n東アジアの【清】(中国)は、乾隆帝の時代に人口も領土も大きくのび、茶・絹・陶磁器を世界に輸出していました。南アジアの【ムガル帝国】(インド)は綿布の一大産地で、西アジアには【オスマン帝国】がありました。\nヨーロッパの人々は、中国の茶や陶磁器、インドの綿布を強くほしがりました。しかしアジア側はヨーロッパの品物をあまり必要としなかったので、ヨーロッパは代金として大量の【銀】を支払いました。\n清は1757年以降、ヨーロッパとの貿易を【広州】1港に限り、特定の商人(公行)にだけ取り引きさせました。日本も、長崎・対馬・薩摩・松前の「四つの口」を通して、オランダ・中国・朝鮮・琉球・アイヌの人々と交流していました。\nつまりこの時代のアジアは、自分たちのルールで貿易を管理できる立場にありました。この力関係をひっくり返したのが、次に学ぶ産業革命です。',
        key: '産業革命の前、アジアは茶・絹・綿布の生産で豊かで、ヨーロッパは銀を払ってそれを買っていた。' },
      { h: 'なぜイギリスで産業革命が起きたのか', t: '【産業革命】とは、道具を使った手作業から、動力で動く機械による大量生産へと、ものづくりと社会のしくみが大きく変わったことです。18世紀後半のイギリスで始まりました。\nなぜイギリスだったのか。理由は、工業化に必要な条件がそろっていたからです。教科書では、主に次の4つが挙げられます。\n①【資本】:大西洋の【三角貿易】(ヨーロッパの武器や雑貨をアフリカへ、アフリカの奴隷をアメリカ大陸へ、アメリカ大陸の砂糖・綿花などをヨーロッパへ運ぶ貿易)などで、工場を建てるお金が蓄えられていた。\n②【労働力】:農業の改良と、地主が土地を囲いこんで大規模な農業を進めた【囲い込み】で、土地を失った農民が都市に流れこみ、工場で働く人になった。\n③【資源】:国内に石炭と鉄鉱石が豊富にあった。④【市場】:広い植民地と海外貿易の網があり、つくった製品を売る先があった。\nさらに、名誉革命のあと議会政治が安定し、商工業を自由に営みやすかったことも背景にあります。',
        key: '資本・労働力・資源・市場の4つの条件がそろったから、イギリスで最初に産業革命が起きた。',
        ex: [{ q: '産業革命がイギリスで最初に始まった理由を、「資本」「労働力」「市場」の3語を使って説明しよう。', hint: 'それぞれが「どこから生まれたか」を1つずつ挙げます。', steps: ['資本:三角貿易などの海外貿易で利益を蓄え、工場を建てるお金があった。', '労働力:囲い込みなどで土地を失った農民が都市に集まり、工場で働く人になった。', '市場:広い植民地と貿易網があり、大量につくった製品を売る先があった。', '3つをつなげ、「だから大量生産を始められた」と結論を書く。'], a: '海外貿易で蓄えた資本があり、囲い込みで土地を失った農民が工場の労働力となり、植民地などの広い市場で製品を売ることができたから。', check: '3語がすべて入り、それぞれに「なぜそうなったか」が書かれているか確かめます。石炭・鉄鉱石(資源)を加えるとさらに良い答えになります。' }] },
      { h: '綿工業から始まった機械化と交通革命', t: '産業革命は【綿工業】から始まりました。なぜ綿だったのでしょうか。インド産の綿布(キャラコ)はイギリスで大人気でしたが、輸入品でした。「国内で安く大量につくれば売れる」という強い需要があったのです。\nまず、布を織る道具を改良した【飛び杼】(ジョン=ケイ)で織る速さが上がると、今度は糸が足りなくなりました。そこで糸をつむぐ紡績機が次々に発明され、さらに力織機が生まれました。一つの改良が、次の改良を呼んだのです。\n機械を動かす力も変わりました。初めは水車でしたが、【ワット】が改良した【蒸気機関】(1769年に特許)によって、石炭を燃やした力で機械を動かせるようになり、工場は川のそば以外にも建てられるようになりました。\n蒸気機関は交通も変えました。【スティーヴンソン】が蒸気機関車を実用化し、1830年にはリヴァプールとマンチェスターの間で鉄道が開通しました。蒸気船も広まり、人やものを速く大量に運べるようになりました。これを【交通革命】といいます。\nこうして工業・燃料(石炭)・鉄・交通が一体となって発展し、イギリスは「【世界の工場】」とよばれるようになります。',
        key: '綿工業の機械化 → 蒸気機関で動力が変わる → 鉄道・蒸気船で交通革命。改良が次の改良を呼んだ。',
        ex: [{ q: '次のできごとを、起きた順に並べよう。ア 鉄道で原料や製品を大量に運ぶ イ 飛び杼で織る速さが上がる ウ 糸が足りなくなり、紡績機が発明される エ 蒸気機関が工場の動力になる', hint: '「布を織る → 糸が足りない → 動力 → 運ぶ」の順に考えます。', steps: ['最初は織る道具の改良(飛び杼)で、布を織る速さが上がった。→ イ', '織る速さに糸の生産が追いつかず、紡績機が発明された。→ ウ', '機械を動かす力として、ワットの蒸気機関が使われるようになった。→ エ', '蒸気機関を乗り物に使い、鉄道で原料や製品を運んだ(1830年の鉄道開通)。→ ア'], a: 'イ → ウ → エ → ア', check: '「ある改良で生まれた不足を、次の改良が解決する」というつながりになっているか確かめます。' }] },
      { h: '産業革命は社会をどう変えたか', t: '産業革命は、ものづくりだけでなく、人々の暮らし方も変えました。工場や機械をもつ【資本家】が、【労働者】を賃金でやとって製品をつくり、利益を求める社会を【資本主義】社会といいます。\n工業都市には人口が集まりましたが、住宅や上下水道が追いつかず、衛生状態が悪化しました。工場では子どもや女性も長時間働かされ、低い賃金や事故が問題になりました(【労働問題】・【都市問題】)。\nこうした問題に対し、労働者は【労働組合】をつくって待遇の改善を求め、イギリスでは工場法で子どもの労働時間が制限されていきました。また、生産手段をみんなで共有して平等な社会をめざす【社会主義】の考え方も生まれ、19世紀半ばにはマルクスらが資本主義を批判しました。\n世界との関係も変わりました。イギリスは機械でつくった安い綿布をインドなどに輸出し、インドの手織りの綿布業は大きな打撃を受けました。インドは、イギリスに綿花などの原料を送り、イギリス製品を買う立場に変えられていきます。\nこのように、工業化した国が原料と市場を求めてアジアやアフリカに進出する流れが、ここから始まりました。',
        key: '産業革命で資本主義社会が生まれ、労働問題・都市問題と社会主義が生まれた。インドは綿布の輸出国から、原料の供給地・製品の市場に変えられた。',
        ex: [{ q: '産業革命の前と後で、インドとイギリスの「綿」をめぐる立場はどう変わった?', hint: '「綿布を売る側」と「買う側」がどちらかに注目します。', steps: ['前:インドの綿布(キャラコ)がイギリスに輸出され、イギリスは買う側だった。', 'イギリスは綿工業を機械化し、安い綿布を大量につくれるようになった。', '後:イギリスの機械製綿布がインドに輸出され、インドの手織り綿布業はおとろえた。', 'インドは、綿花などの原料をイギリスに送り、製品を買う側に変わった。'], a: '前はインドが綿布を輸出しイギリスが買っていたが、後はイギリスが機械製の綿布をインドに売り、インドは原料の供給地・製品の市場になった。', check: '「売る側」と「買う側」が入れかわったことが、答えにはっきり書かれているか確かめます。' }] },
      { h: '市民革命:アメリカ独立とフランス革命', t: '経済の大変化と同じころ、政治でも大変化が起きました。身分の特権や国王の専制をたおし、人々の自由と権利を守る政治をめざした革命を【市民革命】といいます。\nその土台になったのが【啓蒙思想】です。【ロック】は、政府が人々の生命・自由・財産を守らないなら、人々は政府をかえる権利(抵抗権)をもつと説きました。【モンテスキュー】は『法の精神』で【三権分立】を、【ルソー】は『社会契約論』で【人民主権】を説きました。\n北アメリカのイギリス植民地では、本国が植民地の代表がいない議会で税を決めることに反発し(「代表なくして課税なし」)、1775年に独立戦争が始まりました。1776年に【独立宣言】を発表し、1783年のパリ条約で独立が認められました。1787年には三権分立を定めた【合衆国憲法】がつくられ、ワシントンが初代大統領になりました。\nフランスでは、国の財政難と、税をほとんど払わない聖職者・貴族の特権への不満から、1789年に【フランス革命】が始まりました。国民議会は【人権宣言】を出し、人間の自由と平等、国民主権、所有権の不可侵などを示しました。1792年に王政が廃止され、その後、軍人の【ナポレオン】が権力をにぎり、1804年に皇帝となって、法の前の平等などを定めた民法典(ナポレオン法典)をつくりました。\nナポレオンの軍がヨーロッパ各地を支配したことで、革命の考え方は各地に広がると同時に、支配された人々の「自分たちの国をつくろう」という意識も生みました。これが次の単元のナショナリズムにつながります。',
        key: '啓蒙思想(ロック・モンテスキュー・ルソー)の考えが、独立宣言(1776年)・人権宣言(1789年)に生かされた。',
        chain: { title: 'フランス革命の因果', items: [
          ['原因', '国家の財政難と、身分による特権への不満', '聖職者・貴族は税をほとんど払わず、平民(第三身分)に負担が集中'],
          ['できごと', '国民議会の成立 → バスティーユ牢獄襲撃(1789年7月)'],
          ['できごと', '人権宣言(1789年8月)', '自由・平等・国民主権・所有権の不可侵'],
          ['結果', '王政廃止(1792年) → ナポレオンが皇帝に(1804年)', '民法典で法の前の平等を定める'],
          ['その後', 'ナポレオン軍の支配を通じて、革命の理念とナショナリズムがヨーロッパに広がる']] },
        ex: [{ q: 'アメリカ独立宣言(1776年)とフランス人権宣言(1789年)に共通する考え方を、啓蒙思想と結びつけて説明しよう。', hint: 'ロックの考えを思い出しましょう。', steps: ['どちらも、人は生まれながらに自由で平等な権利をもつとしている。', 'どちらも、政治の権力のもとは国王ではなく人々(国民)にあるとしている。', 'これは、政府は人々の権利を守るためにあり、守らない政府はかえてよいとするロックの考えなどの影響を受けている。'], a: '人は生まれながらに自由・平等の権利をもち、政治の権力は国民にもとづくという考え方。ロックらの啓蒙思想の影響を受けている。', check: '「自由・平等」と「国民主権(人民主権)」の2点が入っているか確かめます。' }] },
      { h: '「二つの革命」とアジア・日本', t: '産業革命と市民革命は、ほぼ同じ時期に起き、たがいに影響し合いました。この二つをまとめて【二重革命】とよぶこともあります。工業化(経済)と国民主権(政治)は、近代社会の二本柱になりました。\nでは、アジアにはどう影響したのでしょうか。イギリスでは紅茶を飲む習慣が広まり、清から大量の【茶】を輸入していました。その代金として銀が清へ流れ続けたため、イギリスはこの赤字を取り返す方法を探しました。\nそこでイギリスは、植民地インドでつくらせた【アヘン】(麻薬)を清に密輸し、その代金として銀を回収しました。こうしてできたイギリス・インド・清を結ぶ貿易が、のちの【アヘン戦争】(1840〜42年)につながります。\n工業化した国々は、製品を売る市場と原料を求めて、アジアへの進出を強めていきました。19世紀半ばのペリー来航による日本の開国も、この大きな流れの中にあります。\nこのように、ヨーロッパで起きた「二つの革命」は、遠く離れた東アジアや日本の運命まで変えていきました。歴史総合では、このように地域どうしのつながりで歴史を見ることが大切です。',
        key: '工業化した欧米が、市場と原料を求めてアジアに進出した。イギリスの茶の輸入とアヘンの密輸が、アヘン戦争、そして日本の開国へとつながる。',
        ex: [{ q: 'イギリスが、清から茶を輸入する代金として銀を払い続けることを問題と考え、どのような行動に出たかを説明しよう。', hint: 'インドが関わります。', steps: ['イギリスは清から大量の茶を輸入し、代金として銀を支払っていた。', '清はイギリスの製品をあまり買わないため、銀が一方的に清へ流れ出ていた。', 'そこでイギリスは、植民地インドのアヘンを清に密輸し、その代金で銀を回収しようとした。', 'アヘンが清に広がって銀が逆に流出し、清がアヘンを取りしまったことが、アヘン戦争につながった。'], a: 'イギリスは銀の流出を取り返すため、植民地インドでつくったアヘンを清に密輸して銀を回収した。これがアヘン戦争の原因になった。', check: 'イギリス・インド・清の3か所と、茶・アヘン・銀の動きが矛盾なくつながっているか確かめます。' }] },
      { h: 'もっと深く:「綿」がつないだインド・アメリカ・イギリス', t: '産業革命を「イギリス一国のできごと」と見ると、大事なつながりを見落とします。綿工業は、原料・製品・市場のすべてで世界と結びついていました。\nまず【原料】です。イギリスには綿花が育ちません。機械で糸をつむぐ量が増えるほど、大量の綿花が必要になりました。その主な供給地になったのが【アメリカ合衆国の南部】です。1793年にホイットニーが綿繰り機(綿花から種を取り除く機械)を発明すると、南部の綿花栽培は急拡大し、それを支える【黒人奴隷】の労働もかえって増えました。イギリスの工業化と、アメリカ南部の奴隷制は、綿を通してつながっていたのです。これが、のちの南北戦争の背景になります。\n次に【製品と市場】です。かつて世界一の綿布産地だったインドには、機械でつくった安いイギリス製綿布が流れこみ、インドの手織りの綿布業は大きな打撃を受けました。インドは、綿布を輸出する地域から、綿花などの原料を輸出し、イギリス製品を買う地域へと立場を変えられていきます。\nさらに、工業で力をつけた【産業資本家】は、自由に商品を売り買いできる【自由貿易】を求めました。東インド会社の貿易独占は、インド貿易で1813年、中国貿易で1833年に廃止されます。民間の商人が自由に中国へ進出できるようになり、アヘンの密輸も増えました。これが1840年のアヘン戦争へとつながります。\nこのように、産業革命は「イギリスが豊かになった話」であると同時に、アジア・アフリカ・アメリカ大陸の人々の立場を大きく変えた、世界規模のできごとでした。',
        key: '綿花はアメリカ南部の奴隷労働から、綿布の市場はインドへ。産業資本家の自由貿易の要求が、東インド会社の独占廃止とアヘン戦争につながった。' },
      { h: '入試ではこう出る:文書の取りちがえと「4要素チェック」', t: 'この単元は、共通テストでも個別試験でも、【17〜18世紀の三つの文書】と【産業革命の技術・人物】の取りちがえをねらう問題がよく出ます。\n文書は、国・年・内容をセットで押さえます。【権利の章典】はイギリス・1689年で、議会の権限を確認したもの。【独立宣言】はアメリカ・1776年で、自然権と革命権(抵抗権)を述べ、イギリスからの独立を宣言したもの。【人権宣言】はフランス・1789年で、自由・平等・国民主権・所有権の不可侵を示したものです。資料文に「国王」「議会」とあれば権利の章典、「イギリス国王の圧政」とあれば独立宣言、と手がかりを探しましょう。\n正誤問題では、文を【だれが・いつ・どこで・何をした】の4要素に分けて、1つずつ確かめるのが型です。ひっかけは、たいてい1要素だけがすり替えてあります。たとえば「ワットが蒸気機関を発明した」は、「発明」の部分が誤り(正しくは改良)。「スティーヴンソンが蒸気機関を改良した」も、人物と業績の組み合わせが誤りです。\n年代整序は、全部の年を覚えていなくても解けることが多いです。「原因は結果より前」「国内の改革が先、対外的な影響が後」など、因果関係で並べてから、覚えている年で確かめます。\n時間配分の目安は、知識問題は1問1分以内。迷ったら印をつけて先に進み、資料の読み取りに時間を残しましょう。',
        key: '文書は「国・年・内容」のセットで覚える。正誤問題は「だれが・いつ・どこで・何を」の4要素に分け、すり替えられた1要素を探す。',
        ex: [
          { q: '次の文の正誤を判定し、誤っているものは誤りの部分を正しく直そう。\nア 1689年、フランスで権利の章典が出され、議会の権限が確認された。\nイ ワットは蒸気機関を改良し、工場の動力として広く使えるようにした。\nウ アメリカ独立宣言は、ロックの思想の影響を受け、人の生まれながらの権利を述べている。\nエ 囲い込みによって土地を失った農民の多くが、農村にとどまって自作農になった。', hint: 'それぞれの文を「だれが・いつ・どこで・何を」に分けて確かめます。', steps: ['ア:権利の章典は1689年のイギリスの文書。「フランス」が誤り。', 'イ:ワットは蒸気機関を「改良」した人物。正しい。', 'ウ:独立宣言はロックの自然権・抵抗権の考えを受けている。正しい。', 'エ:囲い込みで土地を失った農民は、都市に流れて工場労働者になった。「農村にとどまって自作農に」が誤り。'], a: 'ア 誤り(フランス→イギリス)、イ 正しい、ウ 正しい、エ 誤り(都市に流れて工場の労働者になった)', check: '誤りの文は、4要素のうち1か所だけを直せば正しい文になっているか確かめます。' },
          { q: '次のできごとを古い順に並べよう。ア フランス人権宣言 イ リヴァプール・マンチェスター間の鉄道開通 ウ アメリカ独立宣言 エ 権利の章典', hint: '17世紀・18世紀後半・19世紀前半の3つの時期に分けてから並べます。', steps: ['17世紀のできごとは、エ 権利の章典(1689年)。', '18世紀後半のできごとは、ウ 独立宣言(1776年)とア 人権宣言(1789年)。アメリカの独立がフランス革命に影響したので、ウが先。', '19世紀前半のできごとは、イ 鉄道開通(1830年)。', '時期の順につなげる。'], a: 'エ → ウ → ア → イ', check: '「アメリカ独立革命がフランス革命に影響した」という因果の順番と合っているか確かめます。' }
        ] }
    ],
    drill: [
      { lv: 1, q: 'イギリスで、地主が共同の耕地や牧草地を垣根などで囲い、大規模な農業を進めたことを何という?', a: '囲い込み(エンクロージャー)', exp: '囲い込みによって農業の生産性は上がりましたが、土地を失った農民が多く生まれました。\nこの人々が都市に流れて工場で働いたことが、産業革命の「労働力」の条件になりました。資本・労働力・資源・市場の4条件と結びつけて覚えましょう。' },
      { lv: 1, q: '産業革命の結果、19世紀のイギリスは工業製品を世界中に輸出するようになった。このころのイギリスを何とよぶ?', a: '世界の工場', exp: '綿製品・鉄・機械などを大量に生産・輸出したことから、こうよばれました。\nのちに第2次産業革命の時代になると、アメリカやドイツが工業生産でイギリスを追いこしていきます。「世界の工場」はイギリスが先頭に立っていた19世紀中ごろの姿だと押さえましょう。' },
      { lv: 1, q: '『社会契約論』を書き、人民主権を説いたフランスの思想家はだれ?', a: 'ルソー', exp: 'ルソーは、国の主権は人民にあると説き、フランス革命に大きな影響を与えました。\n三権分立のモンテスキュー(『法の精神』)、自然権と抵抗権のロック(『統治二論』)と区別しましょう。「人物・著作・主張」の3点セットで覚えるのがコツです。' },
      { lv: 2, q: '1846年、イギリスで穀物法(外国産の穀物に高い関税をかける法律)が廃止された。廃止を強く求めたのはどのような人々で、なぜ求めたのか説明しよう。', a: '工場を経営する産業資本家たち。安い外国産の穀物が入るとパンの値段が下がり、労働者の生活費が下がるので賃金をおさえられ、また自由貿易で工業製品の輸出も伸ばせると考えたから。', exp: '穀物法は、国内の穀物価格を高く保ち、地主の利益を守る法律でした。\n産業資本家にとっては、穀物が高いと労働者の生活費が上がり、賃金を上げなければならなくなります。そこで穀物法の廃止と自由貿易を求めました。\n採点のポイントは、①求めた人々=産業資本家、②理由=安い穀物→賃金をおさえられる、の2点です。「地主と産業資本家の利害の対立」に触れるとさらに良い答えになります。' },
      { lv: 2, q: '綿花の供給地として、アメリカ合衆国の南部がイギリスの産業革命と深く結びついたのはなぜか。「綿繰り機」「奴隷」の2語を使って説明しよう。', a: 'イギリスで機械による綿糸・綿布の生産が増えて綿花の需要が高まり、綿繰り機の発明で綿花の処理も速くなったため、アメリカ南部で黒人奴隷を使った綿花栽培が拡大し、イギリスへの主な供給地になったから。', exp: 'イギリスには綿花が育たないので、原料は輸入にたよる必要がありました。\n1793年の綿繰り機の発明で、綿花から種を取り除く作業が速くなり、南部では奴隷労働による綿花のプランテーションが広がりました。\n採点のポイントは、①イギリスの綿花需要の増加、②綿繰り機による生産拡大、③奴隷労働、の3点がつながっているかです。南北戦争の背景にもなることを覚えておきましょう。' },
      { lv: 3, q: 'フランス革命で生まれた「国民」という意識は、軍事の面でどのような強みになったか。ナポレオンの戦争と結びつけて説明しよう。', a: '革命を守るために徴兵制が導入され、「自分たちの祖国を守る」という意識をもった国民が大量に兵士となった。この国民軍は、雇われた兵士(傭兵)などが中心の他国の軍より士気が高く数も多かったため、ナポレオンはヨーロッパの大部分を支配できた。', exp: '革命前の軍隊は、貴族の将校と雇われた兵士が中心で、兵士にとって戦争は「王の戦争」でした。\n革命で身分制が否定され、国民が国の主人になると、兵士は「自分たちの国のために戦う」国民となりました。革命政府は徴兵制を取り入れ、大規模な国民軍をつくりました。\n採点のポイントは、①国民意識・徴兵制、②士気と規模で他国にまさった、③ナポレオンの勝利につながった、の3点です。さらに「支配された地域でも、反発からナショナリズムが生まれた」と書けると、次の単元とのつながりも示せます。' },
      { lv: 3, q: 'アメリカ独立革命が、フランス革命の原因の一つになったといわれる理由を2つ説明しよう。', a: '①フランスはイギリスと対立していたためアメリカの独立戦争を支援したが、その戦費で財政難がいっそう深刻になり、国王が課税のために三部会を開く原因になった。②独立宣言の理念や、民衆が独立と共和政を実現した成功例が、フランスの人々に影響を与えた。', exp: 'フランスはイギリスへの対抗から独立戦争でアメリカ側につき、勝利に貢献しましたが、大きな借金をかかえました。財政を立て直すための課税をめぐって1789年に三部会が開かれ、これが革命の始まりになります。\nまた、ラ=ファイエットのように独立戦争に参加したフランス人もいて、自然権や革命権の考えが実際に国をつくったという事実は、フランスの人々を勇気づけました。\n採点のポイントは、「財政面(戦費→財政難→三部会)」と「思想面(理念と成功例)」の2つを分けて書けているかです。' }
    ],
    faq: [
      ['産業革命は「革命」とよぶほど急な変化だったの?', '数年で起きたわけではなく、18世紀後半から19世紀前半にかけて何十年もかけて進みました。\nそれでも、人類が数千年続けてきた「手と道具でつくる」生活を、「機械と動力で大量につくる」生活に変えたという意味で、革命とよばれます。'],
      ['市民革命の「市民」とは、だれのこと?', 'ここでの市民は、主に商工業者など、身分の特権をもたないが経済力をつけた人々を指します。\nただし、革命後もすぐにすべての人が政治に参加できたわけではありません。財産による選挙権の制限があり、女性には選挙権がなく、アメリカでは奴隷制が残りました。権利の拡大は、その後の長い課題になります。'],
      ['日本は二つの革命と同じ時代に何をしていたの?', '18世紀後半の日本は江戸時代の中ごろで、田沼意次の政治や松平定信の寛政の改革が行われていました。\n「四つの口」で対外関係を管理していましたが、19世紀に入ると工業化した欧米の船が日本の近海に現れるようになり、対応をせまられていきます。'],
      ['産業革命で、人々の暮らしは良くなったの?悪くなったの?', 'これは歴史学でも長く議論されてきた問題で、見る時期と立場によって答えが変わります。\n産業革命の初めのころは、長時間労働・児童労働・不衛生な住宅など、労働者の生活はきびしいものでした。一方、長い目で見ると、工業製品は安くなり、19世紀後半には賃金も上がって、多くの人の生活水準は向上していきます。\nつまり「短期的には多くの人に苦しみをもたらし、長期的には豊かさの土台をつくった」と整理できます。論述では、どちらか一方だけでなく、両面と時期のちがいを書くと説得力が増します。']
    ],
    terms: [['産業革命', '動力で動く機械による大量生産へと、ものづくりと社会が大きく変わったこと。18世紀後半のイギリスから始まった'], ['三角貿易', '大西洋をはさみ、ヨーロッパ・アフリカ・アメリカ大陸の間で武器・奴隷・砂糖などを運んだ貿易'], ['資本主義', '資本家が労働者を賃金でやとい、利益を求めて生産する経済のしくみ'], ['啓蒙思想', '理性によって古い慣習や特権を批判し、人間の自由と平等を説いた18世紀の思想'], ['人権宣言', '1789年、フランス国民議会が出した宣言。自由・平等・国民主権などを示した'], ['二重革命', '産業革命と市民革命が同じ時期に進み、近代社会をつくったことを表すことば']],
    miss: ['独立宣言(アメリカ・1776年)と人権宣言(フランス・1789年)、権利の章典(イギリス・1689年)を取りちがえる。国名・年・内容を表にして覚えると防げます。', 'ワットを「蒸気機関を発明した人」と覚える。ワット以前にも蒸気機関はあり、ワットはそれを大きく改良して工場の動力に使えるようにした人です。', '産業革命は重工業(鉄鋼など)から始まったと考える。最初は綿工業(軽工業)です。インド綿布への需要が出発点だったと理由とセットで覚えましょう。', '18世紀のアジアを「遅れた地域」と思いこむ。当時の清やインドはむしろ豊かで、ヨーロッパは銀を払って品物を買っていました。立場が逆転したのは産業革命の後です。'],
    sum: ['18世紀、アジアは茶・絹・綿布の生産で豊かで、ヨーロッパは銀でそれを買っていた。', '資本・労働力・資源・市場がそろったイギリスで、綿工業から産業革命が始まった。', '産業革命で資本主義社会が生まれ、労働問題・都市問題、社会主義の考えも生まれた。', '啓蒙思想を土台に、アメリカ独立革命(1776年独立宣言)とフランス革命(1789年人権宣言)が起きた。', '工業化した欧米は市場と原料を求めてアジアに進出し、アヘン戦争や日本の開国につながっていく。'],
    next: '次は「国民国家とナショナリズム(hs_kokumin)」です。フランス革命が広げた「国民がまとまって国をつくる」という考えが、19世紀の欧米をどう変えたかを学びます。'
  };

  L.hs_kokumin = {
    goal: '国民国家とナショナリズムの意味を説明でき、19世紀の欧米(ウィーン体制、イタリア・ドイツの統一、南北戦争など)の流れと、明治日本の国づくりへの影響をつなげて説明できるようになる。',
    intro: 'オリンピックで自分の国の選手を応援するとき、私たちは会ったこともない何千万人もの人を「同じ国民」と感じています。でも、この感覚は昔からあったわけではありません。19世紀の欧米で、学校・軍隊・国語・国旗などを通して「国民」がつくられていったのです。この単元では、その「国民国家づくり」の競争を見ていきます。',
    pre: '前の単元で学んだように、フランス革命は「国の主人は国王ではなく国民である」という【国民主権】の考えを示しました。\nナポレオンはヨーロッパの多くの地域を支配しましたが、1812年のロシア遠征に失敗し、1815年のワーテルローの戦いで最終的に敗れました。\nナポレオンに支配された地域の人々は、外国の支配に反発するなかで、「自分たちは同じ言葉や歴史をもつ一つの民族だ」という意識を強めました。\n19世紀前半のドイツやイタリアは、まだ一つの国ではなく、多くの国や地域に分かれていました。この点を頭に入れておくと、「統一」の意味が分かりやすくなります。',
    secs: [
      { h: '国民国家とナショナリズムとは', t: '【国民国家】とは、一定の領域(国境で囲まれた範囲)に住む人々を「国民」としてまとめ、その国民が主権をもつ(主人公である)とされる国家のことです。\nなぜこの形が広がったのでしょうか。フランス革命の戦争で、国民が「自分たちの国を守る」意識で戦う軍隊は、お金でやとわれた兵士の軍隊より強いことが示されたからです。国民のまとまりは、国の力そのものになりました。\n【ナショナリズム】とは、同じ国民・民族としてまとまり、自分たちの国家をつくったり、その発展を優先したりしようとする考えや運動です。分かれた地域をまとめる「統一」の力にも、外国の支配から抜け出す「独立」の力にもなりました。\nただし、ナショナリズムには別の面もあります。国民としてのまとまりを強めるほど、少数の民族や言葉のちがう人々が「国民らしくない」とされ、同化をおしつけられたり排除されたりすることがありました。\nこの単元では、国民国家が「どうやってつくられたか」と「その光と影」の両方を見ていきます。',
        key: '国民国家=国民が主権をもつとされる国家。ナショナリズムは「統一」と「独立」の力になったが、少数者の排除も生んだ。' },
      { h: 'ウィーン体制と1848年の革命', t: 'ナポレオンの敗北後、1814〜15年に【ウィーン会議】が開かれました。中心になったオーストリアの【メッテルニヒ】は、ヨーロッパを革命前の王朝の秩序にもどそうとしました。この保守的な国際秩序を【ウィーン体制】といいます。\nなぜ王たちは古い秩序にもどそうとしたのでしょうか。国民主権や自由主義(憲法・議会・言論の自由などを求める考え)が広がると、王や貴族の権力が失われるからです。\nしかし、自由主義とナショナリズムの動きは止まりませんでした。1830年、フランスの【七月革命】で国王が追われ、同じ年にベルギーがオランダから独立しました。\n1848年には、フランスの【二月革命】で王政がたおれて共和政となり、その影響でウィーンやベルリンでも【三月革命】が起きて、メッテルニヒは失脚しました。各地で民族の自立や統一を求める動きが同時に起きたので、この年の革命は「【諸国民の春】」ともよばれます。\nこれによってウィーン体制は崩れました。革命の多くはすぐにおさえられましたが、19世紀後半には、各国の政府自身がナショナリズムを利用して国民国家づくりを進めていきます。',
        key: 'ウィーン体制(保守)vs 自由主義・ナショナリズム(変革)。1848年の革命でウィーン体制は崩れた。',
        ex: [{ q: 'ウィーン体制が「自由主義」や「ナショナリズム」をおさえようとしたのはなぜか、説明しよう。', hint: 'その考えが広がると、だれが困るかを考えます。', steps: ['ウィーン体制は、革命前の王朝の秩序を守るための国際的なしくみだった。', '自由主義が広がると、憲法や議会で王の権力が制限される。', 'ナショナリズムが広がると、多くの民族をかかえたオーストリアのような国は、民族の独立運動で分裂するおそれがある。', 'つまり、どちらも王や貴族の支配をゆるがすものだった。'], a: '自由主義は王の権力を憲法や議会で制限し、ナショナリズムは多民族の国家を分裂させるおそれがあり、どちらも王朝の支配をゆるがすものだったから。', check: 'メッテルニヒのオーストリアが多民族国家だったことと結びつけて説明できているか確かめます。' }] },
      { h: 'イタリアとドイツの統一', t: '19世紀後半、ナショナリズムは「分かれていた地域を一つの国にまとめる」力として働きました。その代表がイタリアとドイツです。\n【イタリア】では、北部の【サルデーニャ王国】が首相カヴールのもとで統一を進めました。南部では【ガリバルディ】が義勇軍を率いて両シチリア王国を占領し、それをサルデーニャ王に献上しました。こうして1861年に【イタリア王国】が成立しました。その後もヴェネツィア(1866年)、ローマ教皇領(1870年)を併合していきます。\n【ドイツ】では、【プロイセン】が中心になりました。プロイセンはまず関税同盟(1834年)で経済的な結びつきをつくりました。1862年に首相となった【ビスマルク】は、議会の反対をおさえて軍備を拡張する【鉄血政策】を進め、オーストリアとの戦争(1866年)に勝ちました。\nさらに【プロイセン=フランス戦争】(普仏戦争、1870〜71年)でフランスに勝ち、1871年、プロイセン王ヴィルヘルム1世がヴェルサイユ宮殿でドイツ皇帝となって【ドイツ帝国】が成立しました。\nどちらの統一も、民衆の運動だけでなく、王国の政府が戦争と外交を使って「上から」進めた点が特徴です。',
        key: 'イタリア王国(1861年)はサルデーニャ中心、ドイツ帝国(1871年)はプロイセン中心。どちらも戦争と外交で「上から」統一した。',
        chain: { title: 'ドイツ統一への因果', items: [
          ['背景', 'ドイツは多くの国に分かれていた', 'ナポレオン支配への反発で、民族としての意識が高まる'],
          ['できごと', 'ドイツ関税同盟(1834年)', 'プロイセン中心の経済的なまとまりができる'],
          ['できごと', 'ビスマルクが首相に(1862年) → 鉄血政策で軍備拡張'],
          ['できごと', 'プロイセン=オーストリア戦争(1866年)に勝つ → プロイセン=フランス戦争(1870〜71年)に勝つ'],
          ['結果', 'ドイツ帝国の成立(1871年)', 'プロイセン王が皇帝となる。日本の岩倉使節団は統一直後のドイツを訪れた']] },
        ex: [{ q: 'ビスマルクの「鉄血政策」とは何か。また、それがドイツ統一にどう結びついたか説明しよう。', hint: '「鉄」と「血」は何のたとえかを考えます。', steps: ['「鉄」は武器(軍備)、「血」は兵士(戦争)のたとえ。', '鉄血政策は、議会の反対をおさえて軍備を強化する政策だった。', '強くなった軍隊で、オーストリア(1866年)・フランス(1870〜71年)との戦争に勝った。', '勝利によってドイツの諸国をプロイセンのもとにまとめ、1871年にドイツ帝国が成立した。'], a: '鉄(武器)と血(兵士)で、つまり軍事力によって統一を進める政策。軍備を強化してオーストリアとフランスとの戦争に勝ち、1871年のドイツ帝国成立につなげた。', check: '2つの戦争の相手と順番(オーストリアが先、フランスがあと)が合っているか確かめます。' }] },
      { h: 'イギリス・フランス・ロシア・オスマン帝国の動き', t: 'すでに国としてまとまっていた国々も、19世紀に大きく変わりました。国民の支持を得て国力を強めることが、どの国でも課題になったからです。\n【イギリス】では、1832年の選挙法改正で産業資本家などに選挙権が広がり、労働者も選挙権を求める【チャーティスト運動】を起こしました。穀物法の廃止(1846年)など自由貿易も進み、1851年にはロンドンで世界最初の万国博覧会が開かれました。イギリスは「世界の工場」として繁栄し、この時代は【ヴィクトリア女王】の名をとってヴィクトリア時代とよばれます。\n【フランス】では、二月革命の後、ナポレオンの甥のルイ=ナポレオンが大統領に選ばれ、1852年に皇帝【ナポレオン3世】となりました(第二帝政)。国民の人気を得るため、パリの都市改造や対外戦争を進めましたが、1870年の普仏戦争で捕虜となり、帝政は終わりました。\n【ロシア】は、南下政策を進めて【クリミア戦争】(1853〜56年)を起こしましたが、イギリス・フランスなどに敗れました。近代化の遅れを痛感した皇帝【アレクサンドル2世】は、1861年に【農奴解放令】を出しました。\n【オスマン帝国】も、ヨーロッパの圧力の中で、1839年から【タンジマート】とよばれる西洋式の改革を進め、1876年にはアジアで最初の憲法(ミドハト憲法)を定めました。しかしこの憲法は、ロシアとの戦争を理由にまもなく停止されました。',
        key: 'イギリスは選挙権の拡大と自由貿易、ロシアはクリミア戦争の敗北から農奴解放(1861年)、オスマン帝国はタンジマートと憲法(1876年)。',
        ex: [{ q: 'ロシアのアレクサンドル2世が1861年に農奴解放令を出したのはなぜか。直前の戦争と結びつけて説明しよう。', hint: 'クリミア戦争の結果を思い出しましょう。', steps: ['ロシアは南下政策を進め、クリミア戦争(1853〜56年)を起こした。', 'しかし、産業革命を進めたイギリス・フランスなどに敗れた。', '敗北で、農奴制にもとづく古い社会のままでは近代的な国に勝てないと痛感した。', 'そこで、近代化の第一歩として農奴を解放した。'], a: 'クリミア戦争でイギリス・フランスなどに敗れ、農奴制による社会の遅れを痛感し、近代化を進める必要があったから。', check: '「戦争の敗北 → 遅れの自覚 → 改革」という因果の順になっているか確かめます。' }] },
      { h: 'アメリカ合衆国の発展と南北戦争', t: 'アメリカ合衆国は、独立後、西へ西へと領土を広げました。1848年にはメキシコとの戦争でカリフォルニアなどを得て、太平洋岸に達しました。その過程で、先住民は土地を追われていきました。\n国が大きくなるにつれて、北部と南部の対立が深まりました。工業化が進んだ北部は、国内の工業を守る保護貿易と、奴隷制の拡大反対を主張しました。綿花のプランテーション(大農園)で黒人奴隷を使っていた南部は、綿花をイギリスに輸出するための自由貿易と、奴隷制の維持を求めました。\n1860年、奴隷制の拡大に反対する【リンカン】が大統領に当選すると、南部の州は連邦から離れ、1861年に【南北戦争】が始まりました。リンカンは1863年に【奴隷解放宣言】を出して国内外の支持を集め、1865年に北部が勝利しました。\n戦後、国としての統一は保たれ、1869年には【大陸横断鉄道】が開通しました。ヨーロッパやアジアから多くの移民が来て工業が急成長し、19世紀末にはアメリカは世界一の工業国になります。\nただし、奴隷制が廃止されたあとも、南部では黒人への差別が法律や慣習の形で長く続きました。国民国家の「国民」にだれが入るのかという問題は、ここにも表れています。',
        key: '南北戦争(1861〜65年):工業の北部(保護貿易・奴隷制拡大反対)vs 綿花の南部(自由貿易・奴隷制維持)。北部が勝ち、統一が保たれた。',
        ex: [{ q: '南北戦争前の北部と南部の主張のちがいを、「貿易」と「奴隷制」の2点で整理しよう。', hint: 'それぞれの経済の中心(工業か、綿花か)から考えます。', steps: ['北部は工業が中心。イギリスの安い工業製品に負けないよう、保護貿易を求めた。', '北部は、奴隷制が西部に広がることに反対した。', '南部は綿花の輸出が中心。イギリスに綿花を売るため、自由貿易を求めた。', '南部は、綿花の農園を支える奴隷制の維持を求めた。'], a: '北部:保護貿易・奴隷制の拡大に反対。南部:自由貿易・奴隷制の維持。', check: '経済の中心が「工業か綿花か」から、貿易政策の主張が説明できているか確かめます。' }] },
      { h: '国民をつくるしくみと、明治日本', t: '国民国家は、自然に生まれたわけではありません。政府は、さまざまなしくみを使って、人々を「国民」にしていきました。\n①【義務教育】:学校で共通の「国語」や自国の歴史を教え、地方ごとにちがう言葉や習慣をこえた一体感をつくった。②【徴兵制】:国民が兵士として国を守るしくみをつくった。③【国旗・国歌・祝日】:国のシンボルを定め、記念の行事で人々の気持ちをまとめた。④鉄道・郵便・新聞:国のすみずみまで、人・もの・情報を結びつけた。\nこの欧米の国づくりを間近で見たのが、明治政府の【岩倉使節団】(1871〜73年)です。岩倉具視を大使に、大久保利通・木戸孝允・伊藤博文らが欧米を回りました。不平等条約の改正交渉はうまくいきませんでしたが、統一直後のドイツなどを視察し、まず国内の制度や産業を整えることが大切だと考えました。\n明治政府は、学制(1872年)、徴兵令(1873年)などを通して、日本でも「国民」をつくろうとしました。のちに伊藤博文は、君主の権限が強いドイツ(プロイセン)の憲法を参考に、大日本帝国憲法(1889年)を準備しました。\n一方で、国民国家づくりは、アイヌの人々や琉球(沖縄)の人々への同化政策という形でも進みました。国民国家の光と影は、日本の近代にも見られます。',
        key: '国民国家は義務教育・徴兵制・国旗国歌などで「国民」をつくった。明治日本も岩倉使節団で欧米を学び、同じ道を進んだ。',
        ex: [{ q: '明治政府の学制(1872年)と徴兵令(1873年)は、国民国家づくりの中でどんな役割をもっていたか説明しよう。', hint: '欧米の国民国家が「国民」をつくったしくみと比べます。', steps: ['欧米の国民国家は、義務教育で共通の国語や歴史を教え、国民の一体感をつくった。', '学制は、身分や地域に関係なく子どもを学校に通わせるしくみで、同じ役割をもつ。', '欧米の国民国家は、徴兵制で国民が国を守るしくみをつくった。', '徴兵令は、武士だけでなく国民の男子に兵役を課すもので、同じ役割をもつ。'], a: '学制は学校教育を通して共通の知識や国民意識を育て、徴兵令は身分によらず国民が兵士となって国を守るしくみをつくった。どちらも、身分や地域をこえた「国民」をつくる役割をもった。', check: '欧米のしくみと日本の制度が、1対1で対応しているか確かめます。' }] },
      { h: 'もっと深く:国民は「つくられる」──言語・学校・歴史', t: '国民国家の時代、「私たちは同じ国民だ」という意識は、最初から自然にあったわけではありません。19世紀の国々は、さまざまな方法で国民を【つくって】いきました。\nイタリアが統一されたとき、「イタリアはできた。これからはイタリア人をつくらねばならない」と語られたとされます。当時のイタリア半島では地方ごとにことばが大きくちがい、標準的なイタリア語を日常的に話す人はわずかでした。\nそこで国家は、①学校教育で【標準語】と【国の歴史】を教え、②【徴兵制】で各地の若者を同じ軍隊に集め、③【国旗・国歌・記念日】で一体感を演出しました。鉄道や新聞の普及も、国内の人々を結びつけました。\nしかし、国民をまとめる力は、そこに入らない人々を【排除】する力にもなります。ドイツ帝国ではポーランド系住民にドイツ語が強制され、各地でユダヤ人への差別も強まりました。ナショナリズムは「解放」と「抑圧」の両面をもつのです。\n多くの民族をかかえる帝国は、とくに苦しみました。オーストリアは1867年にハンガリーの自治を認めて【オーストリア=ハンガリー帝国】となり、オスマン帝国は【タンジマート】(1839年から)の改革や1876年の【ミドハト憲法】で、宗教や民族のちがいをこえた「オスマン人」としてまとめようとしました。\n明治日本の学制・徴兵令・「国語」の整備も、この世界的な流れの中にあります。北海道のアイヌの人々や琉球の人々に対する同化政策も、国民づくりの「影」の面として押さえておきましょう。',
        key: '国民は、学校・徴兵・標準語・国旗国歌などで「つくられた」。その力は少数派の排除や同化にも向かい、多民族の帝国をゆさぶった。' },
      { h: '入試ではこう出る:統一の人物と年代整序', t: 'この単元は、【人物と業績の組み合わせ】と【年代整序】がねらわれます。とくにイタリア統一の3人は定番のひっかけです。\n【マッツィーニ】は「青年イタリア」を組織し、共和政による統一をめざした革命家。【カヴール】は【サルデーニャ王国】の首相で、外交と近代化で統一を進めた政治家。【ガリバルディ】は「千人隊」(赤シャツ隊)を率いて【両シチリア王国】を占領し、それをサルデーニャ王に献上しました。1861年、【イタリア王国】が成立します。\nドイツは「戦争の順番」で覚えます。プロイセンの【ビスマルク】は、デンマーク戦争(1864年)、【プロイセン=オーストリア戦争】(1866年)、【プロイセン=フランス戦争】(1870〜71年)に勝ち、1871年、ヴェルサイユ宮殿でプロイセン王が皇帝に即位して【ドイツ帝国】が成立しました。\n年代整序のコツは、【1848年】を「ものさし」にすることです。1848年の二月革命・三月革命でウィーン体制がくずれ、その後のクリミア戦争(1853〜56年)で列強の協調が弱まったことが、1860年前後のイタリア統一や、アメリカ・ロシアの改革の時期とつながります。\n論述では「なぜ統一が保守派の手で実現したか」がよく問われます。1848年の革命で自由主義者による統一が失敗したあと、カヴールやビスマルクのような王国の政治家が、外交と戦争で「上から」統一を進めた、という流れで書きましょう。',
        key: 'マッツィーニ=青年イタリア、カヴール=サルデーニャ首相、ガリバルディ=両シチリア占領。ドイツは1864→1866→1870〜71年の3つの戦争。年代は1848年を基準に。',
        ex: [
          { q: '次の人物と説明の組み合わせのうち、正しいものをすべて選ぼう。\nア カヴール ― 千人隊を率いて両シチリア王国を占領した\nイ ビスマルク ― プロイセンの首相として軍備を強化し、統一を進めた\nウ マッツィーニ ― 青年イタリアを組織し、共和政による統一をめざした\nエ ガリバルディ ― サルデーニャ王国の首相として外交で統一を進めた', hint: 'カヴールとガリバルディの説明が入れかえられていないか確かめます。', steps: ['ア:千人隊で両シチリア王国を占領したのはガリバルディ。誤り。', 'イ:ビスマルクはプロイセン首相で、鉄血政策を進めた。正しい。', 'ウ:マッツィーニは青年イタリアの指導者。正しい。', 'エ:サルデーニャ王国の首相はカヴール。誤り。'], a: 'イ・ウ', check: 'アとエの説明を入れかえると正しくなることを確かめます。入れかえ型は定番のひっかけです。' },
          { q: '次のできごとを古い順に並べよう。ア ドイツ帝国の成立 イ フランスの二月革命 ウ クリミア戦争の開始 エ イタリア王国の成立', hint: '1848年を基準にして、その前か後かを考えます。', steps: ['イ 二月革命は1848年で、ウィーン体制がくずれるきっかけ。', 'ウ クリミア戦争は1853年に始まった(〜1856年)。', 'エ イタリア王国の成立は1861年。', 'ア ドイツ帝国の成立は、プロイセン=フランス戦争中の1871年。'], a: 'イ → ウ → エ → ア', check: '「ウィーン体制の崩壊→列強の協調の弱まり→各国の統一」という流れと合っているか確かめます。' }
        ] }
    ],
    drill: [
      { lv: 1, q: '1834年に、プロイセンを中心とするドイツの多くの国々が結んだ、経済の統一を進めるしくみを何という?', a: 'ドイツ関税同盟', exp: '加盟した国の間では関税がなくなり、商品が自由に行き来できるようになりました。\nオーストリアは加わらず、プロイセン中心の経済圏ができたことが、のちにプロイセン主導のドイツ統一(オーストリアを除く小ドイツ主義)につながります。「経済の統一が政治の統一に先行した」と押さえましょう。' },
      { lv: 1, q: 'ガリバルディが千人隊を率いて占領し、サルデーニャ王に献上した南イタリアの国はどこ?', a: '両シチリア王国', exp: 'ガリバルディは共和主義者でしたが、統一を優先して占領地をサルデーニャ王に献上しました。\nこれで北と南がまとまり、1861年にイタリア王国が成立します。カヴールの業績と混同しないように注意しましょう。' },
      { lv: 1, q: '南北戦争中の1862年、西部の公有地を一定期間開拓した人に無償で与えることを定めたアメリカの法律は何?', a: 'ホームステッド法', exp: 'この法律で西部の開拓が進み、西部の農民を北部(リンカン側)の支持者に引きつける効果もありました。\n翌1863年の奴隷解放宣言と並んで、リンカンが戦争を有利に進めた政策として出題されます。' },
      { lv: 2, q: '1848年の革命が「諸国民の春」とよばれるのはなぜか説明しよう。', a: 'フランスの二月革命をきっかけに、ウィーンやベルリンの三月革命など、ヨーロッパ各地で自由主義や民族の自立・統一を求める運動が一斉に起こり、ウィーン体制がくずれたから。', exp: '二月革命でフランスは王政から共和政(第二共和政)にかわり、その影響がオーストリアやプロイセンにも広がりました。ウィーンではメッテルニヒが失脚して亡命しています。\nハンガリーやベーメン(ボヘミア)など、多くの民族が自立を求めて立ち上がったことから「諸国民の春」とよばれます。\n採点のポイントは、①各地に一斉に広がった、②自由主義とナショナリズムの運動、③ウィーン体制の崩壊、の3点です。多くの運動は最終的に鎮圧されたことも書けると正確です。' },
      { lv: 2, q: 'プロイセン=フランス戦争(1870〜71年)は、フランスとドイツにそれぞれどのような結果をもたらしたか説明しよう。', a: 'ドイツでは、戦争中の1871年にヴェルサイユ宮殿でドイツ帝国の成立が宣言され、統一が完成した。フランスでは皇帝ナポレオン3世が捕虜となって第二帝政がたおれ、第三共和政となったうえ、アルザス・ロレーヌをドイツにうばわれた。', exp: 'この戦争で、ドイツは統一を完成させ、ヨーロッパの大国になりました。\nフランスは領土を失い、敗戦の屈辱からドイツへの強い反発(復讐の感情)が生まれます。この独仏の対立は、第一次世界大戦の背景の一つになります。\n採点のポイントは、ドイツ側(帝国の成立)とフランス側(帝政の崩壊・領土喪失)の両方を書けているかです。' },
      { lv: 3, q: 'ナショナリズムは、ドイツやイタリアでは国をまとめる力になったが、オーストリアやオスマン帝国では国をゆさぶる力になった。このちがいが生まれた理由を説明しよう。', a: 'ドイツやイタリアは、同じことばや文化をもつ人々が多くの国に分かれていたので、ナショナリズムは分かれた国々を一つにまとめる統一の力になった。一方、オーストリアやオスマン帝国は多くの民族をかかえる帝国だったので、それぞれの民族が自分たちの国をつくろうとすると、帝国から離れていく分裂の力になった。', exp: 'ナショナリズムは「一つの民族(国民)が一つの国家をもつべきだ」という考えにつながります。\nこれを「分かれている国々」にあてはめれば統一の理由になり、「多民族の帝国」にあてはめれば独立の理由になります。同じ考え方が、置かれた状況によって正反対の働きをしたのです。\n採点のポイントは、①ドイツ・イタリア=分立していた、②オーストリア・オスマン=多民族帝国、③それぞれ統一と分裂に働いた、の3点です。オーストリア=ハンガリー帝国の成立(1867年)やタンジマートなど、帝国側の対応を添えるとさらに良い答えです。' },
      { lv: 3, q: '明治日本の国民国家づくりは、欧米と比べて「上から」の性格が強かったといわれる。その理由を、具体的な政策を2つ以上挙げて説明しよう。', a: '学制・徴兵令・地租改正などの改革は、国民の運動から生まれたのではなく、明治政府が欧米に対抗するために主導して短期間に進めたものだったから。大日本帝国憲法も、天皇が国民に与える欽定憲法の形をとった。', exp: 'フランスなどでは、市民革命によって国民が自ら政治の主人になる道を開きました。\nこれに対して明治日本では、列強に対抗できる国をつくるため、政府が改革の順番と中身を決め、上から国民をつくっていきました。\n採点のポイントは、①政府主導であること、②具体的な政策(学制・徴兵令・地租改正・欽定憲法など)を2つ以上、③欧米(とくに市民革命)との対比、です。一方で、自由民権運動のように国民の側から政治参加を求める「下から」の動きもあったことに触れると、バランスの良い答えになります。' }
    ],
    faq: [
      ['「国民」と「民族」はどうちがうの?', '民族は、言葉・宗教・習慣・歴史などを共有していると感じる人々の集まりです。国民は、ある国家に属する人々のことです。\n一つの国家に複数の民族がいることも、一つの民族が複数の国家に分かれていることもあります。この「ずれ」が、民族問題や独立運動の原因になります。'],
      ['イタリアやドイツは、統一前はどうなっていたの?', 'イタリア半島は、サルデーニャ王国・両シチリア王国・ローマ教皇領などに分かれ、北部の一部はオーストリアの支配下にありました。\nドイツは、プロイセンやオーストリアなど30以上の国や自由都市がゆるやかな連合(ドイツ連邦)をつくっていました。'],
      ['なぜ日本はドイツの憲法を手本にしたの?', 'ドイツ(プロイセン)の憲法は君主の権限が強く、天皇中心の国家をめざした明治政府に合っていたからです。\nまた、ドイツが「上から」急速に統一と近代化を進めた点も、明治政府の目標と重なっていました。'],
      ['自由主義とナショナリズムは、いつも手を組んでいたの?', '19世紀前半には、どちらもウィーン体制という同じ「敵」と戦っていたので、手を組むことが多くありました。1848年の革命では、自由と統一が同時に求められています。\nしかし1848年の革命の多くが失敗したあと、統一はカヴールやビスマルクのような王国の政治家が「上から」進めました。とくにビスマルクは、議会の反対をおさえて軍備を拡大し、戦争で統一を実現しています。\nつまり、19世紀後半には「統一(ナショナリズム)は実現したが、自由主義は後回し」という形も生まれました。二つは別の考え方だと区別しておきましょう。']
    ],
    terms: [['国民国家', '一定の領域の人々を「国民」としてまとめ、国民が主権をもつとされる国家'], ['ナショナリズム', '国民・民族としてまとまり、自分たちの国家をつくったり発展させたりしようとする考えや運動'], ['ウィーン体制', 'ウィーン会議(1814〜15年)で決まった、革命前の秩序を守ろうとする国際体制'], ['鉄血政策', 'ビスマルクが進めた、軍備の強化によってドイツ統一をはかる政策'], ['南北戦争', '1861〜65年、奴隷制や貿易政策をめぐるアメリカ北部と南部の戦争'], ['農奴解放令', '1861年、ロシアのアレクサンドル2世が出した、農奴を解放する法令'], ['岩倉使節団', '1871〜73年、岩倉具視を大使として欧米に派遣された明治政府の使節団']],
    miss: ['イタリア統一(1861年)とドイツ統一(1871年)の年や中心国を混同する。「イタリアはサルデーニャ・61年、ドイツはプロイセン・71年」と、10年差のセットで覚えます。', 'メッテルニヒとビスマルクを取りちがえる。メッテルニヒは古い秩序を守る側(オーストリア)、ビスマルクは統一を進める側(プロイセン)です。', '南北戦争で、南部が保護貿易を主張したと逆に覚える。綿花をイギリスに輸出したい南部は自由貿易、工業を守りたい北部は保護貿易です。', 'ナショナリズムを「良いもの」か「悪いもの」のどちらかだけで考える。統一・独立の力にもなり、少数者の排除や対外戦争の原因にもなった、と両面で考えます。'],
    sum: ['国民国家は国民が主権をもつとされる国家で、ナショナリズムは統一と独立の力になった。', 'ウィーン体制は1848年の革命(諸国民の春)で崩れた。', 'イタリア王国(1861年)とドイツ帝国(1871年)は、戦争と外交で「上から」統一された。', 'ロシアはクリミア戦争の敗北後に農奴解放令(1861年)、アメリカは南北戦争(1861〜65年)を経て工業国へ。', '国民国家は教育・徴兵・国旗国歌で「国民」をつくり、明治日本も岩倉使節団を通じてそれを学んだ。'],
    next: '次は「アジアの開港と明治維新(hs_kaikoku)」です。工業化した欧米がアジアに来たとき、清と日本がどう開港させられ、どう対応したのかを比べながら学びます。'
  };

  L.hs_kaikoku = {
    goal: 'アヘン戦争による清の開港と、ペリー来航による日本の開国を比べて説明でき、明治維新と、東アジアの国際関係が「朝貢・冊封」から「条約」へ変わった流れをつかむ。',
    intro: '同じ東アジアにあって、同じように欧米に開港をせまられた清と日本。どちらも不平等な条約を結ばされましたが、その後の歩みは大きくちがいました。さらに日本は、自分が欧米から受けた不平等を、今度は朝鮮におしつける側にも回ります。この単元では、19世紀の東アジアを「比べる」「つなげる」の2つの目で見ていきます。',
    pre: '前の単元で学んだように、イギリスは清から茶を大量に輸入し、その代金の銀を取り返すため、植民地インドのアヘンを清に密輸していました。\n中学で学んだ日本の開国の流れ(ペリー来航 → 日米和親条約 → 日米修好通商条約 → 大政奉還)を思い出しておきましょう。\n【不平等条約】の中身は、①【領事裁判権】(外国人が罪をおかしても、その国の領事が自国の法で裁く。治外法権ともいう)を認めること、②【関税自主権】(輸入品にかける税を自国で決める権利)がないこと、の2つが中心です。\n【条約】は国どうしが対等な立場で結ぶ約束が原則ですが、19世紀には、軍事力の強い国が弱い国に不利な内容をおしつけることが多くありました。',
    secs: [
      { h: '東アジアの伝統的な国際秩序', t: 'まず、欧米が来る前の東アジアの国際関係を知っておきましょう。そうしないと、何が「変わった」のかが分かりません。\n東アジアでは長い間、中国の皇帝を中心とする秩序がありました。周りの国の王が皇帝に使いを送ってみつぎ物をささげ(【朝貢】)、皇帝はその王を国王として認める(【冊封】)という関係です。朝鮮や琉球、ベトナムなどがこの関係を結んでいました。\nこの関係は、国どうしが対等ではなく、中国を中心とした上下の関係でした。ただし、実際の政治には中国はあまり口を出さず、貿易や儀礼の形を整えるという意味が大きかったのです。\n日本の江戸幕府は、清と正式な国交を結ばず、長崎で中国の商人と貿易していました。朝鮮とは対馬藩を通して国交があり、琉球は薩摩藩の支配を受けながら清にも朝貢を続けていました。\nこれに対して欧米の国々は、国どうしが(建前上は)対等な主権国家として条約を結ぶ、という別のルールをもっていました。19世紀の東アジアでは、この2つのルールがぶつかることになります。',
        key: '伝統の東アジア=中国皇帝中心の朝貢・冊封の秩序(上下関係)。欧米=主権国家が条約を結ぶ秩序。19世紀に2つがぶつかった。' },
      { h: 'アヘン戦争と清の開港', t: 'アヘンが広まると、清では中毒者がふえ、代金の銀が国外に流れ出して財政も苦しくなりました。そこで清は【林則徐】を広州に派遣し、1839年に外国商人のアヘンを没収して処分させました。\nイギリスはこれに反発し、1840年に【アヘン戦争】を起こしました。蒸気船などの近代的な軍事力をもつイギリスが勝ち、1842年に【南京条約】が結ばれました。清は【香港島】を割譲し、【上海】など5港を開き、特定の商人だけに貿易させるしくみ(公行)も廃止しました。\nさらにその後の取り決めで、清は【領事裁判権】や、関税を自由に決められない協定関税などを認めさせられました。アメリカやフランスとも同じような条約を結びました。\nそれでもイギリスが期待したほど貿易はのびなかったため、イギリスはフランスとともに【アロー戦争】(1856〜60年)を起こしました。1860年の北京条約で、清は天津などの開港、九竜半島南部の割譲、外国の外交官の北京駐在などを認めました。\nこうして清は、朝貢・冊封の秩序の中心から、欧米と不平等な条約を結ぶ国の一つへと立場を変えられていきました。',
        key: '南京条約(1842年):香港島の割譲・上海など5港の開港・公行の廃止。追加の取り決めで領事裁判権と協定関税も認めさせられた。',
        chain: { title: '茶とアヘンからアヘン戦争へ', items: [
          ['背景', 'イギリスが清から茶を大量輸入 → 代金の銀が清へ流出'],
          ['できごと', 'イギリスがインド産アヘンを清に密輸', '清からは銀が流出し、中毒者がふえる'],
          ['できごと', '林則徐がアヘンを没収・処分(1839年) → アヘン戦争(1840〜42年)'],
          ['結果', '南京条約(1842年):香港島の割譲・5港の開港', '続く取り決めで領事裁判権・協定関税'],
          ['その後', 'アヘン戦争の知らせが日本に伝わり、幕府は異国船打払令をゆるめる(1842年)']] },
        ex: [{ q: 'アヘン戦争の原因を、イギリス・インド・清の3つの地域の関係から説明しよう。', hint: '「茶」「アヘン」「銀」がどこからどこへ動いたかを考えます。', steps: ['イギリスは清から茶を大量に輸入し、代金として銀を払っていた。', 'イギリスは銀を取り返すため、植民地インドのアヘンを清に密輸した。', '清ではアヘン中毒が広がり、今度は銀が国外に流れ出した。', '清が林則徐にアヘンを取りしまらせたことに、イギリスが反発して戦争を起こした。'], a: 'イギリスが茶の代金として失った銀を取り返すため、インド産アヘンを清に密輸した。清がそのアヘンを取りしまったことにイギリスが反発し、戦争になった。', check: '茶(清→イギリス)、アヘン(インド→清)、銀(清→国外)の流れが矛盾なくつながっているか確かめます。' }] },
      { h: '清の動揺と改革:太平天国と洋務運動', t: 'アヘン戦争の後、清の国内は大きく動揺しました。戦争の賠償金や銀の流出で人々の負担が重くなり、社会の不満が高まったからです。\n1851年、キリスト教の影響を受けた【洪秀全】が【太平天国】をたて、満洲人の清朝をたおして漢人の国をつくる「滅満興漢」をかかげて反乱を起こしました。太平天国は南京を都として一時は大きな勢力となりました。\n清の正規軍はこれをおさえられず、【曽国藩】や【李鴻章】ら漢人の官僚が地元で組織した軍(郷勇)や、外国人が指揮する軍の力を借りて、1864年にようやく鎮圧しました。\nこの経験から、清では、西洋の軍事技術や工業を取り入れて国を強くしようとする【洋務運動】が始まりました。兵器工場や造船所、紡績工場などがつくられました。\nただし洋務運動は、「【中体西用】」(中国の伝統的な政治や道徳を本体とし、西洋の技術を用いる)という考えにもとづいていました。政治のしくみそのものは変えなかった点が、のちに明治維新と比べられることになります。',
        key: '洋務運動は「中体西用」:政治のしくみは変えず、西洋の技術だけを取り入れた。',
        ex: [{ q: '清の洋務運動と日本の明治維新を比べ、いちばん大きなちがいを説明しよう。', hint: '「技術だけ取り入れたか」「政治のしくみまで変えたか」に注目します。', steps: ['洋務運動は、兵器工場や造船所など、西洋の技術を取り入れた。', 'しかし「中体西用」の考えで、皇帝を中心とする政治のしくみや伝統的な制度は変えなかった。', '明治維新は、技術だけでなく、藩の廃止(廃藩置県)や身分制の見直し、のちには憲法と議会など、政治・社会のしくみそのものを変えた。', 'したがって、改革の範囲がちがう、とまとめる。'], a: '洋務運動は政治のしくみを変えずに西洋の技術だけを取り入れたが、明治維新は技術に加えて、中央集権化や身分制の改革など政治・社会のしくみそのものを変えた。', check: '「技術」と「制度・しくみ」の2つの言葉で比べられているか確かめます。' }] },
      { h: '日本の開国と江戸幕府の滅亡', t: 'アヘン戦争で清が敗れたという知らせは、幕府に大きな衝撃を与えました。幕府は1842年、外国船を砲撃して追いはらう方針(異国船打払令)をゆるめ、外国船に燃料や水を与える【天保の薪水給与令】を出しました。清のように戦争になることをおそれたのです。\n1853年、アメリカの【ペリー】が浦賀に来航して開国を求めました。アメリカは、太平洋を横断する船や捕鯨船の補給地を必要としていました。幕府は1854年に【日米和親条約】を結び、下田・函館を開きました。\n1858年には【日米修好通商条約】を結んで貿易を始めました。この条約は、領事裁判権を認め、関税自主権がない不平等条約で、清の条約と共通の特徴をもっていました。同じような条約を、オランダ・ロシア・イギリス・フランスとも結びました。\n貿易が始まると、生糸や茶が大量に輸出されて国内で品不足になり、物価が上がりました。また、金と銀の交換比率が日本と外国でちがったため、金貨が大量に海外に流れ出しました。人々の生活が苦しくなり、外国を追いはらえという攘夷運動と、天皇を尊ぶ尊王論が結びついた【尊王攘夷運動】が高まりました。\n薩摩藩はイギリスと(薩英戦争、1863年)、長州藩は4か国の艦隊と(1864年)戦って力の差を知り、攘夷から倒幕へと方針を変えました。1866年に【薩長同盟】が結ばれ、1867年に徳川慶喜が【大政奉還】を行って、江戸幕府は終わりました。',
        key: '清の敗北を知った幕府は戦争を避けて開国した。日米修好通商条約(1858年)は清と同じく領事裁判権と関税自主権の欠如を含む不平等条約。',
        chain: { title: '開国から幕府の滅亡へ', items: [
          ['背景', 'アヘン戦争で清が敗北 → 幕府は天保の薪水給与令(1842年)'],
          ['できごと', 'ペリー来航(1853年) → 日米和親条約(1854年) → 日米修好通商条約(1858年)'],
          ['結果', '生糸などの輸出で品不足・物価上昇、金の流出', '人々の不満が高まり、尊王攘夷運動へ'],
          ['できごと', '薩英戦争(1863年)・4か国艦隊の下関砲撃(1864年)で攘夷の無理を知る → 薩長同盟(1866年)'],
          ['その後', '大政奉還(1867年) → 戊辰戦争(1868〜69年)を経て新政府が全国を支配']] },
        ex: [{ q: '開国後に尊王攘夷運動が高まった理由を、貿易の影響から説明しよう。', hint: '輸出がふえると、国内の品物はどうなるかを考えます。', steps: ['日米修好通商条約で貿易が始まり、生糸や茶が大量に輸出された。', '国内で品物が不足し、物価が上がった。金貨の流出も起きた。', '人々の生活が苦しくなり、外国との貿易と、条約を結んだ幕府への不満が高まった。', 'その不満が、外国を追いはらい天皇を尊ぼうとする尊王攘夷運動に結びついた。'], a: '貿易で生糸などが大量に輸出されて品不足と物価の上昇が起き、金も流出して生活が苦しくなった。その不満が、外国と幕府に向かい、尊王攘夷運動が高まった。', check: '「貿易 → 物価上昇 → 生活苦 → 外国と幕府への不満」の順でつながっているか確かめます。' }] },
      { h: '明治維新:近代国家づくりの急ぎ足', t: '新政府は、欧米に対抗できる国をつくることを急ぎました。清のように欧米の圧力に押されつづけないためには、国の力を一つにまとめる必要があったからです。\n1868年、【五箇条の御誓文】で新しい政治の方針を示しました。1869年の【版籍奉還】で大名に土地と人民を天皇に返させ、1871年の【廃藩置県】で藩をなくして府県を置き、中央から役人を送る【中央集権国家】をつくりました。\n【富国強兵】をかかげ、学制(1872年)で学校制度を、徴兵令(1873年)で国民の軍隊を、【地租改正】(1873年)で地価の3%を現金で納める安定した税のしくみをつくりました。【殖産興業】として、官営の【富岡製糸場】(1872年)を建て、1872年には新橋〜横浜間に鉄道を開通させました。\n一方、国民が政治に参加することを求める【自由民権運動】が1874年の民撰議院設立の建白書から始まりました。政府は1881年に国会の開設を約束し、伊藤博文が中心となって【大日本帝国憲法】(1889年)を定め、1890年に帝国議会が開かれました。日本は、アジアで初めて憲法にもとづく議会政治を本格的に始めた国となりました。\nこれらの改革のねらいの一つは、欧米に「近代国家」と認めさせ、不平等条約を改正することでした。',
        key: '廃藩置県で中央集権化 → 富国強兵・殖産興業 → 憲法(1889年)と議会(1890年)。ねらいの一つは条約改正。',
        ex: [{ q: '明治政府が、廃藩置県・徴兵令・地租改正をセットで進めたのはなぜか。「富国強兵」と結びつけて説明しよう。', hint: '「全国を治める → 兵を集める → お金を集める」の関係を考えます。', steps: ['廃藩置県で藩をなくし、政府が全国を直接治められるようにした。', '全国を直接治められるようになったので、全国の男子から兵を集める徴兵令が可能になった。', '地租改正で、全国から毎年決まった額の税(現金)を集められるようにした。', '兵(強兵)とお金(富国)を国全体から集めるために、3つは互いに支え合う改革だった。'], a: '廃藩置県で政府が全国を直接治め、そのうえで徴兵令で全国から兵を、地租改正で安定した税収を集めた。3つは富国強兵のために互いに必要な改革だったから。', check: '3つの改革のうち、1つが欠けると他の2つが成り立ちにくいことを説明できるか確かめます。' }] },
      { h: '国境の画定と、変わる東アジアの国際関係', t: '国民国家には、はっきりした【国境】が必要です。明治政府は、周辺の地域との境界を次々に決めていきました。\n北では、1869年に蝦夷地を【北海道】と改めて開拓使を置き、開拓を進めました。そこに住んでいた【アイヌ】の人々は、土地や伝統的な暮らしを奪われ、同化を強いられました。1875年にはロシアと【樺太・千島交換条約】を結び、樺太をロシア領、千島列島全体を日本領としました。南では、1876年に小笠原諸島の領有を各国に通告しました。\n琉球は、清への朝貢を続けながら薩摩の支配も受けていました。政府は1872年に琉球藩を置き、1879年には軍や警察を送って【沖縄県】を置きました(【琉球処分】)。清はこれに抗議しました。\n清とは1871年に【日清修好条規】を結びました。これはたがいに領事裁判権を認め合う、日本が初めて結んだ【対等な条約】でした。一方、朝鮮に対しては、1875年の【江華島事件】をきっかけに、翌1876年に【日朝修好条規】を結ばせました。この条約は、朝鮮に日本の領事裁判権を認めさせるなど、【朝鮮にとって不平等な条約】でした。\nこのように、東アジアの国際関係は、朝貢・冊封の秩序から、条約にもとづく関係へ変わっていきました。その中で日本は、欧米から受けた不平等を、朝鮮に負わせる側にも立ったのです。',
        key: '日清修好条規(1871年)は対等、日朝修好条規(1876年)は朝鮮に不平等。琉球処分(1879年)で沖縄県を設置。',
        flow: { title: '明治初期の日本と周りの国・地域', cols: 3, rows: [
          [['ロシア', 'k', 1, '樺太・千島交換条約(1875年)'], ['北海道', 'b', 1, '開拓使(1869年)・アイヌへの同化'], ['小笠原諸島', 'b', 1, '領有を通告(1876年)']],
          [['清', 'o', 1, '日清修好条規(1871年)・対等'], ['琉球', 'g', 1, '琉球処分(1879年)→ 沖縄県'], ['朝鮮', 'r', 1, '日朝修好条規(1876年)・朝鮮に不平等']]
        ], legend: [['b', '日本の領域に組みこむ'], ['g', '清との両属から日本へ'], ['o', '対等な条約'], ['r', '日本に有利な不平等条約'], ['k', '国境を決める']] },
        ex: [{ q: '日清修好条規(1871年)と日朝修好条規(1876年)を比べ、条約の性格のちがいを説明しよう。', hint: '領事裁判権を「どちらが」認めたかに注目します。', steps: ['日清修好条規では、日本と清がたがいに領事裁判権を認め合った。', 'つまり、どちらか一方だけが有利になる内容ではなく、対等な条約だった。', '日朝修好条規では、朝鮮が日本の領事裁判権を一方的に認めさせられた。', 'つまり、日本が欧米から受けた不平等を、朝鮮に負わせる内容だった。'], a: '日清修好条規はたがいに領事裁判権を認め合う対等な条約だったが、日朝修好条規は朝鮮だけが日本の領事裁判権を認める、朝鮮にとって不平等な条約だった。', check: '「たがいに」と「一方的に」のちがいがはっきり書かれているか確かめます。' }] },
      { h: 'もっと深く:不平等条約の中身──領事裁判権・関税自主権・最恵国待遇', t: '清も日本も「不平等条約」を結ばされましたが、何がどう不平等だったのでしょうか。中身を3つに分けると、なぜ両国がその改正に長く苦しんだのかが分かります。\n①【領事裁判権】:外国人が罪を犯しても、その国の法律ではなく、その外国の領事がその外国の法律で裁く権利です。自国の法で外国人を裁けないので、主権が及ばない人々が国内にいることになります。\n②【関税自主権がない】:輸入品にかける税(関税)の率を、自分の国だけで決められないことです。相手国と協議して決める【協定関税】となり、低い税率におさえられました。安い外国製品が大量に入っても国内の産業を守れず、政府の税収も増やせません。\n③【片務的最恵国待遇】:ある国に新しい特権を与えると、条約を結んでいるほかの国にも自動的に同じ特権を与えなければならない、という約束が一方的に課されていたことです。1つの国に譲ると、すべての国に譲ることになります。\n清では、南京条約(1842年)と翌年の追加条約などでこれらが定められ、アロー戦争後の天津条約・北京条約で外国の公使の北京駐在やキリスト教布教の自由なども認めさせられました。日本では日米和親条約(1854年)で片務的最恵国待遇が、日米修好通商条約(1858年)で領事裁判権と協定関税が定められました。\n日本が領事裁判権の撤廃に成功するのは1894年、関税自主権を完全に回復するのは1911年です。不平等条約の改正は、明治政府の外交の最大の課題であり続けました。',
        key: '不平等の中身は、①領事裁判権(外国人を自国の法で裁けない)、②関税自主権がない(協定関税)、③片務的最恵国待遇(一国への譲歩が全国に広がる)。' },
      { h: '入試ではこう出る:清と日本の条約・開港地の比較', t: '入試では、清と日本の開国を【並べて比べる】問題がよく出ます。とくに条約の名前・年・開港地の取りちがえがねらわれます。\n清の【南京条約】(1842年)では、香港島の割譲と、【広州・厦門・福州・寧波・上海】の5港の開港などが決まりました。日本の【日米和親条約】(1854年)では【下田・箱館】の2港が開かれましたが、これは燃料・食料などの補給のためで、貿易は始まっていません。貿易が始まるのは【日米修好通商条約】(1858年)からで、函館・神奈川(横浜)・長崎・新潟・兵庫(神戸)の5港が開かれました。\n定番のひっかけは「日米和親条約で貿易が始まった」「日米修好通商条約で下田が開かれた」「アヘン戦争の講和条約は北京条約」などです。条約名と中身を1対1で結びつけておきましょう。\nもう一つの型が、【情報の伝わり方と対応】を問う論述です。アヘン戦争で清が敗れたという知らせは、オランダ船や中国船を通じて幕府に伝わりました。幕府は1842年、外国船を砲撃して追い払う異国船打払令をゆるめ、来航した船に燃料や水を与える【天保の薪水給与令】を出しています。「他国の経験から学んで政策を変えた」という視点は、論述で高く評価されます。\n解き方の型は、「清の場合」「日本の場合」の2列の表を頭の中につくり、同じ項目(条約名・年・開港地・相手国・その後)を横に並べて比べることです。',
        key: '南京条約=5港開港・香港島割譲。日米和親条約=下田・箱館(貿易なし)。日米修好通商条約=5港で貿易開始。アヘン戦争の情報で幕府は薪水給与令へ。',
        ex: [
          { q: '次の文の正誤を判定し、誤りは正しく直そう。\nア 日米和親条約で下田・箱館が開かれ、アメリカとの貿易が始まった。\nイ 南京条約で、清はイギリスに香港島を割譲した。\nウ 日米修好通商条約では、日本に関税自主権が認められなかった。\nエ アヘン戦争の講和条約として、清はイギリスと北京条約を結んだ。', hint: '条約名と中身を1対1で結びつけて確かめます。', steps: ['ア:和親条約は補給のための開港で、貿易は始まっていない。誤り。', 'イ:南京条約で香港島が割譲された。正しい。', 'ウ:修好通商条約は協定関税で、関税自主権がなかった。正しい。', 'エ:アヘン戦争の講和条約は南京条約。北京条約はアロー戦争後の条約。誤り。'], a: 'ア 誤り(貿易は日米修好通商条約から)、イ 正しい、ウ 正しい、エ 誤り(北京条約→南京条約)', check: '誤りの文が、条約名か中身のどちらか1か所を直せば正しくなるか確かめます。' },
          { q: 'アヘン戦争での清の敗北は、幕府の対外政策にどのような影響を与えたか説明しよう。', hint: '1825年に出されていた法令と、1842年に出された法令を比べます。', steps: ['アヘン戦争の前、幕府は異国船打払令(1825年)で外国船を砲撃して追い払う方針だった。', '清がイギリスに敗れたという情報が、オランダ船などを通じて幕府に伝わった。', '幕府は、外国船を追い払えば戦争になり、日本も清のように敗れるおそれがあると考えた。', 'そこで1842年、天保の薪水給与令を出し、来航した外国船に燃料や水を与えて帰す方針に改めた。'], a: '清の敗北を知った幕府は、外国船を追い払うと戦争をまねくおそれがあると考え、異国船打払令をゆるめて、1842年に外国船に燃料や水を与える天保の薪水給与令を出した。', check: '「前の政策→情報→判断→新しい政策」の順に因果がつながっているか確かめます。' }
        ] }
    ],
    drill: [
      { lv: 1, q: '1851年に清で反乱を起こし、太平天国を建てた人物はだれ?', a: '洪秀全', exp: '洪秀全はキリスト教の影響を受けた宗教結社をつくり、「滅満興漢」(清をたおして漢民族の国を復興する)をかかげました。\n太平天国は南京を首都とし、1864年まで続きました。鎮圧には、曾国藩や李鴻章らの郷勇(地方の義勇軍)が活躍し、彼らがのちの洋務運動の担い手になります。' },
      { lv: 1, q: '1858年、勅許(天皇の許可)を得ないまま日米修好通商条約に調印した大老はだれ?', a: '井伊直弼', exp: '井伊直弼は勅許なしで調印し、反対派を安政の大獄で処罰しました。\nそのため1860年、桜田門外の変で暗殺されます。幕府の権威が大きく下がり、尊王攘夷運動が高まるきっかけとなりました。' },
      { lv: 1, q: '開港後の日本で、最大の輸出品となったものは何?', a: '生糸', exp: '開港当初、日本の輸出品の中心は生糸で、次いで茶でした。\nヨーロッパで蚕の病気が流行していたこともあって、日本の生糸は大量に輸出されました。その結果、国内では生糸が不足して値上がりし、西陣などの絹織物業が打撃を受けました。' },
      { lv: 2, q: '関税自主権がないことは、日本の国内産業と政府にとってどのような不利益があったか説明しよう。', a: '輸入品に高い関税をかけられないので、安い外国製品が大量に入ってきても国内の産業を守ることができず、また関税による税収も増やせなかった。', exp: '関税には、①国内の産業を外国との競争から守る、②政府の収入になる、という2つの役割があります。\n協定関税で税率が低くおさえられていると、この2つの役割がどちらも果たせません。実際に、開港後には安いイギリス製の綿織物が入り、国内の綿作や綿織物業が打撃を受けました。\n採点のポイントは、「産業を守れない」と「税収が増やせない」の両方を書けているかです。' },
      { lv: 2, q: '開港直後の日本の貿易で、最大の貿易相手国がアメリカではなくイギリスだったのはなぜか説明しよう。', a: 'アメリカでは1861年から南北戦争が起きて、アジアとの貿易に力を入れられなかったのに対し、イギリスは産業革命で工業力が強く、アジアに広い貿易網をもっていたから。', exp: '日本に開国を求めたのはアメリカでしたが、貿易額ではイギリスが圧倒的に多くなりました。\nイギリスは、綿織物などの工業製品を売りこみ、生糸や茶を買い入れました。アメリカは国内の南北戦争(1861〜65年)で、それどころではなかったのです。\n採点のポイントは、①アメリカの南北戦争、②イギリスの工業力と貿易網、の2点です。国際関係の中で日本の開国を見る視点が大切です。' },
      { lv: 3, q: '開港後の日本で物価が急に上がった理由を、「生糸」と「金と銀の交換比率」の2点から説明しよう。', a: '①生糸が大量に輸出されたため、国内で品不足になって値上がりした。②日本では金と銀の交換比率が約1対5で、外国(約1対15)より金が安かったため、外国人が銀を持ちこんで金に交換し、大量の金が国外に流出した。幕府は金の含有量を減らした小判(万延小判)をつくって対応したので、貨幣の価値が下がり、物価がさらに上がった。', exp: '1つ目は「もの」の面です。生糸など輸出品が海外に流れ、国内の供給が減って値段が上がりました。\n2つ目は「お金」の面です。日本では銀に対して金が安かったので、外国の銀を日本に持ちこんで金に換えると、それだけでもうかりました。金の流出を止めるため、幕府は金の量を減らした万延小判を発行しますが、貨幣の価値が下がったことで物価はさらに上昇しました。\n採点のポイントは、①輸出による品不足、②金銀比価のちがいと金の流出、③貨幣改鋳による物価上昇、の3点です。物価上昇が下級武士や庶民の生活を苦しめ、攘夷運動が高まる背景になったことも結びつけましょう。' },
      { lv: 3, q: 'アロー戦争(第2次アヘン戦争)をきっかけに、ロシアが清から得た領土を挙げ、それが東アジアの国際関係にどのような意味をもったか説明しよう。', a: 'ロシアは1858年のアイグン条約で黒竜江(アムール川)以北を、1860年の北京条約で沿海州を得た。沿海州にはウラジヴォストークを建設し、日本海に面した港を手に入れたことで、東アジアに直接進出する足場を得た。これは、のちに朝鮮や中国東北部をめぐって日本と対立する背景となった。', exp: 'アロー戦争で清が英仏に苦しめられているすきに、ロシアは仲介役などを通して領土を広げました。\nウラジヴォストークは「東方を支配せよ」という意味をもつ港で、ロシアの東アジア進出の拠点となりました。\n採点のポイントは、①アイグン条約(黒竜江以北)と北京条約(沿海州)、②ウラジヴォストークの建設、③日本・朝鮮・中国東北部との関係(のちの日露対立)、の3点です。英仏の動きだけでなく、ロシアの動きにも目を向けることが大切です。' }
    ],
    faq: [
      ['清と日本は同じように開港させられたのに、なぜその後がちがったの?', '理由は1つではありませんが、よく挙げられるのは、日本が政治のしくみまで変える改革を短い期間で進めたこと、清は国土が広く、太平天国など大きな内乱をかかえていたことです。\nまた、日本は欧米にとって、清ほど大きな市場ではなかったため、圧力の強さにもちがいがありました。どちらが「優れていた」と単純に考えないことが大切です。'],
      ['日朝修好条規の「朝鮮は自主の国」という文には、どんな意味があったの?', '朝鮮は清と朝貢・冊封の関係にありました。「自主の国」と書くことで、清の朝鮮に対する宗主権(上に立つ権利)を否定し、日本が朝鮮に影響力をのばしやすくするねらいがあったと考えられています。\nこの朝鮮をめぐる日本と清の対立が、のちの日清戦争につながります。'],
      ['琉球処分はなぜ「処分」とよばれるの?', '政府の公文書で使われたことばがそのまま歴史用語になったものです。琉球王国の人々の意思とは別に、軍や警察の力を背景に王国を廃止して沖縄県を置いたことを指します。'],
      ['「領事裁判権」と「治外法権」は同じもの?', '厳密には少しちがいます。【治外法権】は、外交官などが滞在する国の法律や裁判に従わなくてよいという、広い意味の特権です。【領事裁判権】は、そのうち「外国人が罪を犯したとき、その国の領事が自国の法で裁く」という裁判についての権利を指します。\n日本史の教科書では、不平等条約の内容として「領事裁判権(治外法権)」のように並べて書かれることが多く、入試でもほぼ同じ意味で使われます。ただし、正確に書くなら、不平等条約で問題になったのは「領事裁判権」だと覚えておきましょう。']
    ],
    terms: [['朝貢・冊封', '周りの国が中国皇帝にみつぎ物をささげ、皇帝がその王を国王として認める関係'], ['南京条約', '1842年、アヘン戦争の講和条約。香港島の割譲・5港の開港など'], ['洋務運動', '「中体西用」の考えで、西洋の技術を取り入れた清の近代化運動'], ['尊王攘夷運動', '天皇を尊び、外国を追いはらおうとした幕末の運動'], ['廃藩置県', '1871年、藩をなくして府県を置き、中央集権体制をつくった改革'], ['日清修好条規', '1871年、日本と清が結んだ対等な条約'], ['日朝修好条規', '1876年、江華島事件をきっかけに朝鮮に結ばせた、朝鮮に不平等な条約'], ['琉球処分', '1872年の琉球藩設置から1879年の沖縄県設置までの、琉球を日本に組みこむ過程']],
    miss: ['南京条約(1842年・アヘン戦争)と北京条約(1860年・アロー戦争)を混同する。香港島の割譲は南京条約、九竜半島南部の割譲は北京条約です。', '日清修好条規も不平等条約だと思いこむ。日清修好条規は対等で、不平等なのは日朝修好条規です。「清とは対等、朝鮮には不平等」とセットで覚えます。', '日本の開国の「和親条約」と「通商条約」の中身を取りちがえる。貿易を始め、不平等な内容をふくむのは1858年の日米修好通商条約です。', '洋務運動を「失敗だったから意味がない」と片づける。工場や軍備は実際につくられました。問題は、政治のしくみを変えなかった点にあります。'],
    sum: ['東アジアには中国皇帝中心の朝貢・冊封の秩序があり、欧米の条約の秩序とぶつかった。', 'アヘン戦争(1840〜42年)の南京条約で清は開港し、続く取り決めで不平等な条件も認めさせられた。', '清は太平天国の乱を経て、技術中心の洋務運動を進めた。', '日本は清の敗北を見て開国し、不平等条約のもとで幕府がたおれ、明治維新で政治のしくみまで変えた。', '日本は国境を画定し、清とは対等な条約、朝鮮には不平等な条約を結んだ。'],
    next: '次は「帝国主義と日清・日露戦争(hs_teikoku)」です。欧米の列強が世界を分割していく中で、日本がどのように列強の一員になっていったのか、そしてそれが朝鮮や中国にとって何を意味したのかを学びます。'
  };

  L.hs_teikoku = {
    goal: '帝国主義が起きた理由と、アフリカ・アジアの分割の様子を説明でき、日清戦争・日露戦争から韓国併合までの流れを、日本・中国・朝鮮・アジアの民族運動のそれぞれの立場から説明できるようになる。',
    intro: '19世紀の終わりから20世紀のはじめ、世界地図の色はわずか30年ほどで大きく塗りかえられました。アフリカのほとんどがヨーロッパの国々の植民地になり、中国も勢力範囲に切り分けられます。日本はこのとき、植民地にされる側ではなく、植民地をもつ側に入っていきました。同じできごとが、立場によってまったくちがって見えることを意識して読みましょう。',
    pre: '前の単元までに、イギリスの産業革命と、国民国家づくりの競争、そして清と日本の開港を学びました。\n日本は1889年に大日本帝国憲法を定め、1890年に帝国議会を開いて、憲法と議会をもつ【立憲国家】になりました。\n明治政府の大きな目標は、不平等条約の改正、つまり【領事裁判権の撤廃】と【関税自主権の回復】でした。\n朝鮮は、清と朝貢・冊封の関係を続けていましたが、1876年の日朝修好条規以後、日本の影響も強まり、朝鮮をめぐって日本と清が対立していました。',
    secs: [
      { h: '第2次産業革命と帝国主義', t: '19世紀後半、産業の中心が大きく変わりました。石炭と蒸気機関の時代から、【石油】と【電力】を使い、鉄鋼・化学などの【重化学工業】が中心の時代へと移ったのです。これを【第2次産業革命】といいます。この分野では、イギリスを追い上げた【ドイツ】と【アメリカ】が大きくのびました。\n重化学工業には巨大な設備と資金が必要なので、大企業や銀行が力をもつようになりました。各国は、①原料の確保、②製品を売る市場、③余ったお金(資本)を投資する先、を求めて、海外に植民地や勢力範囲を広げようとしました。\nこのように、列強(強い国々)が軍事力を背景に、アジア・アフリカなどを植民地や勢力範囲として支配しようとした動きや考え方を【帝国主義】といいます。おおむね1870年代〜第一次世界大戦のころの時代をさします。\n列強は、自分たちの支配を「遅れた地域に文明を広める使命」などと正当化しました。人種によって優劣があるという誤った考えも、支配の言いわけに使われました。\n国内でも、植民地の獲得は国民の誇りや人気とつながり、ナショナリズムと帝国主義が結びつきました。',
        key: '第2次産業革命(石油・電力・重化学工業)→ 原料・市場・投資先を求めて植民地を拡大=帝国主義。',
        ex: [{ q: '第2次産業革命が、列強の植民地獲得競争(帝国主義)につながったのはなぜか説明しよう。', hint: '重化学工業に必要なものを3つ考えます。', steps: ['第2次産業革命で、石油・電力を使う重化学工業が中心になった。', '重化学工業には大量の原料(石油・ゴムなど)が必要だった。', '大量につくった製品を売る市場と、大企業・銀行が蓄えた資本を投資する先も必要になった。', 'これらを確保するため、列強は軍事力を背景に植民地や勢力範囲を広げた。'], a: '重化学工業の発展で、原料の確保、製品の市場、資本の投資先が必要になり、それを得るために列強が植民地や勢力範囲を広げようとしたから。', check: '「原料・市場・投資先」の3つが答えに入っているか確かめます。' }] },
      { h: 'アフリカ・アジア・太平洋の分割', t: '帝国主義の動きがもっとも急だったのがアフリカです。1884〜85年、ドイツの【ビスマルク】が【ベルリン会議】を開き、アフリカの土地は、先に実際に支配した国が領有できる、という原則を確認しました。これをきっかけに、列強は競ってアフリカに進出しました。\nイギリスはエジプトと南アフリカを結ぶ南北方向に(縦断政策)、フランスはアフリカ北西部から東へ(横断政策)勢力をのばし、1898年にはスーダンのファショダで両国が衝突しかけました(ファショダ事件・フランスが譲歩)。20世紀のはじめには、独立を保ったのは【エチオピア】(1896年にイタリア軍を破る)と【リベリア】だけになりました。\nアジアでは、インドで1857年に起きた大反乱(インド大反乱)のあと、イギリスがインドを直接統治し、1877年にヴィクトリア女王を皇帝とする【インド帝国】をつくりました。フランスは1887年にベトナム・カンボジアを合わせて【フランス領インドシナ連邦】をつくりました。東南アジアで独立を保ったのは、英仏の勢力の間にあった【タイ】だけでした。\n太平洋では、アメリカが1898年にハワイを併合し、同じ年のスペインとの戦争(米西戦争)でフィリピンなどを得ました。\nこうして、世界のほとんどの地域が、列強のどこかの支配か影響のもとに置かれました。地図の境界線は、そこに住む人々の民族や生活とは関係なく引かれることが多く、今日の紛争の原因にもなっています。',
        key: 'ベルリン会議(1884〜85年)→ アフリカ分割。独立を保ったのはエチオピア・リベリア。東南アジアではタイだけ。',
        ex: [{ q: '20世紀のはじめのアフリカで、植民地にならずに独立を保った国を2つ挙げ、そのうち1つについて理由を説明しよう。', hint: '1896年のできごとを思い出しましょう。', steps: ['ベルリン会議以後、アフリカのほとんどが列強の植民地になった。', '独立を保ったのは、エチオピアとリベリアだった。', 'エチオピアは、1896年にアドワの戦いでイタリア軍を破り、独立を守った。'], a: 'エチオピアとリベリア。エチオピアは1896年に侵攻してきたイタリア軍を破り、独立を守った。', check: '東南アジアで独立を保ったタイと混同していないか確かめます。' }] },
      { h: '日清戦争と条約改正', t: '1894年、朝鮮で東学という宗教を信じる人々を中心に、大規模な農民の反乱(【甲午農民戦争】)が起きました。朝鮮政府が清に出兵を求めると、日本も対抗して出兵し、両国の軍が衝突して【日清戦争】が始まりました。\nちょうど開戦直前の1894年7月、外務大臣【陸奥宗光】のもとで日英通商航海条約が結ばれ、【領事裁判権の撤廃】が実現しました。ロシアの南下を警戒するイギリスが、日本を味方につけたいと考えたことが背景にあります。\n戦争は日本の勝利に終わり、1895年の【下関条約】で、清は①朝鮮の独立を認め、②【遼東半島・台湾・澎湖諸島】を日本にゆずり、③賠償金2億両を支払うことになりました。①は、清と朝鮮の朝貢・冊封の関係が終わったことを意味します。\nところが、【ロシア・ドイツ・フランス】が遼東半島を清に返すよう求め(【三国干渉】)、日本はこれを受け入れました。国内では「臥薪嘗胆」(将来のために苦しみにたえる)を合言葉に、ロシアへの対抗心が高まり、軍備の拡張が進みました。\n日本は台湾に【台湾総督府】を置き、住民の抵抗を武力でおさえて植民地支配を始めました。賠償金の一部は八幡製鉄所(1901年操業開始)の建設などに使われ、日本の重工業化が進みました。',
        key: '下関条約(1895年):朝鮮の独立承認・遼東半島と台湾などの割譲・賠償金。三国干渉で遼東半島を返還。領事裁判権の撤廃は1894年(陸奥宗光)。',
        ex: [{ q: '下関条約で清が「朝鮮の独立」を認めたことには、東アジアの国際関係の上でどのような意味があったか。', hint: '清と朝鮮の伝統的な関係を思い出しましょう。', steps: ['朝鮮は、清の皇帝に朝貢し、冊封を受ける関係にあった。', '「朝鮮の独立」を認めることは、清がこの関係(宗主権)を放棄することを意味する。', 'これにより、東アジアの朝貢・冊封の秩序は事実上くずれた。', '同時に、清の影響がなくなった朝鮮に、日本(やロシア)が影響力をのばしやすくなった。'], a: '清が朝鮮に対する宗主権を放棄し、朝貢・冊封の秩序がくずれたことを意味した。その結果、日本などが朝鮮に影響力をのばしやすくなった。', check: '「朝貢・冊封の終わり」と「日本の進出」の2点が入っているか確かめます。' }] },
      { h: '中国分割と義和団戦争', t: '日清戦争で清の弱さが明らかになると、列強は清から港や地域を借りる(【租借】)形で、次々に勢力範囲をつくりました。1898年ごろ、ドイツは膠州湾、ロシアは旅順・大連、イギリスは威海衛と九竜半島などを租借しました。これを【中国分割】といいます。\n出遅れたアメリカは、1899年に国務長官ジョン=ヘイの名で【門戸開放】・機会均等を各国によびかけ、中国の市場にどの国も平等に参加できるよう求めました。\n清の中では、日本の明治維新を手本に、憲法や議会をつくる改革を進めようとする動き(【変法運動】、1898年)が起きました。しかし保守派の西太后らによって、わずか100日ほどで止められました。\n一方、民衆の間では外国やキリスト教への反感が高まり、【義和団】が「扶清滅洋」(清を助け、西洋をほろぼせ)をかかげて北京に入りました。清朝もこれに乗って列強に宣戦しましたが、1900年、日本とロシアを主力とする【8か国の連合軍】が北京を占領しました。\n1901年の【北京議定書】で、清は巨額の賠償金を支払い、北京などに外国軍が駐留することを認めました。この後もロシアは満州(中国東北部)に大軍を置き続け、日本との対立が深まります。',
        key: '中国分割(租借地)→ 義和団(扶清滅洋)→ 8か国連合軍が北京占領 → 北京議定書(1901年)。ロシアは満州に居座り、日露対立へ。',
        ex: [{ q: '義和団戦争の後、日本とロシアの対立が深まったのはなぜか説明しよう。', hint: '戦争の後、ロシアの軍がどこに残ったかを考えます。', steps: ['義和団戦争で、日本とロシアは連合軍の主力として出兵した。', '戦争が終わった後も、ロシアは満州に大軍を置き続けた。', '満州のとなりの朝鮮(韓国)に勢力をのばしたい日本にとって、ロシアの南下は大きな脅威だった。', 'こうして、満州と韓国をめぐって日本とロシアの対立が深まった。'], a: '義和団戦争の後もロシアが満州に軍を置き続け、朝鮮半島に進出しようとする日本と、満州・韓国をめぐって利害が衝突したから。', check: '日英同盟(1902年)が、このロシアへの対抗から結ばれたことと結びつけられるか確かめます。' }] },
      { h: '日露戦争', t: 'ロシアの南下を警戒していたのは、日本だけではありませんでした。世界中に植民地をもつイギリスも、ロシアの進出をおそれていました。そこで1902年、日本とイギリスは【日英同盟】を結びました。\n1904年、【日露戦争】が始まりました。日本は旅順の攻略や奉天の会戦、1905年の日本海海戦などで勝利しましたが、多くの死傷者を出し、戦費も限界に近づいていました。ロシアでも国内で革命運動(1905年の第1次ロシア革命)が起き、戦争を続けるのが難しくなりました。\nそこでアメリカ大統領【セオドア=ローズヴェルト】の仲介で、1905年に【ポーツマス条約】が結ばれました。日本は、①韓国に対する指導・監督権、②旅順・大連の租借権、③長春以南の鉄道とその利権(のちの南満州鉄道)、④北緯50度以南の樺太(サハリン)などを得ました。\nしかし、賠償金は得られませんでした。重い税にたえてきた国民の不満が爆発し、東京では【日比谷焼き打ち事件】が起きました。\n日露戦争は、「アジアの国がヨーロッパの大国に勝った」ことで世界に衝撃を与えました。その一方で、日本はこの勝利によって韓国の支配と満州への進出を本格化させ、列強の一員として帝国主義の道を進んでいきます。',
        key: '日英同盟(1902年)→ 日露戦争(1904〜05年)→ ポーツマス条約(1905年):韓国の指導権・南樺太など。賠償金はなく、日比谷焼き打ち事件。',
        chain: { title: '日清戦争から韓国併合へ', items: [
          ['背景', '朝鮮をめぐる日本と清の対立'],
          ['できごと', '日清戦争(1894〜95年) → 下関条約', '朝鮮の独立承認・台湾などの割譲'],
          ['結果', '三国干渉で遼東半島を返還 → ロシアへの反感', 'ロシアは旅順・大連を租借、義和団戦争後も満州に駐留'],
          ['できごと', '日英同盟(1902年) → 日露戦争(1904〜05年) → ポーツマス条約', '韓国に対する指導・監督権を得る'],
          ['その後', '韓国の保護国化(1905年・統監府) → 韓国併合(1910年・朝鮮総督府)']] },
        ex: [{ q: '次のできごとを古い順に並べよう。ア ポーツマス条約 イ 三国干渉 ウ 日英同盟 エ 北京議定書', hint: '日清戦争 → 中国分割 → 義和団 → 同盟 → 日露戦争 の順です。', steps: ['日清戦争の下関条約(1895年)の直後に三国干渉。→ イ', '義和団戦争の後、1901年に北京議定書。→ エ', 'ロシアの満州駐留に対抗して、1902年に日英同盟。→ ウ', '日露戦争の講和として、1905年にポーツマス条約。→ ア'], a: 'イ → エ → ウ → ア', check: '1895 → 1901 → 1902 → 1905 と年が小さい順になっているか確かめます。' }] },
      { h: '日露戦争後のアジア:民族運動と韓国併合', t: '日露戦争の結果は、アジアの人々に複雑な影響を与えました。一方では、立憲国家の日本が専制国家のロシアに勝ったことが、アジア各地で「自分たちも変われる」という希望を生みました。\n【イラン】では立憲革命(1905年〜)、【オスマン帝国】では憲法の復活を求める青年トルコ革命(1908年)が起きました。【インド】では、イギリスがベンガル分割令(1905年)で民族運動を分断しようとすると、国民会議派が1906年に英貨排斥・スワデーシ(国産品愛用)・スワラージ(自治)・民族教育をかかげました。【ベトナム】では、ファン=ボイ=チャウらが日本に留学生を送るドンズー(東遊)運動を進めましたが、日本政府はフランスとの関係を優先し、留学生を国外に退去させました。\n【中国】では、東京で孫文らが中国同盟会(1905年)を結成し、三民主義(民族・民権・民生)をかかげました。1911年に【辛亥革命】が起こり、1912年に孫文を臨時大総統とする【中華民国】が成立し、清はほろびました。\n他方、【韓国】にとって日露戦争は、植民地化への道でした。日本は1905年に韓国の外交権をうばって保護国とし、【統監府】を置きました(初代統監は伊藤博文)。韓国の人々は義兵運動などで抵抗しましたが、1909年に伊藤博文がハルビンで安重根に暗殺されると、日本は1910年に【韓国併合】を行い、【朝鮮総督府】を置いて支配しました。\n日本は1911年、外務大臣【小村寿太郎】のもとで関税自主権を回復し、条約改正を達成しました。こうして日本は欧米と対等な立場を手に入れましたが、それは台湾と朝鮮を植民地とする帝国としての立場でもありました。',
        key: '日露戦争はアジアの民族運動を勇気づけたが、韓国にとっては植民地化(1905年保護国化、1910年併合)への道だった。1911年、関税自主権の回復で条約改正を達成。',
        ex: [{ q: '日露戦争での日本の勝利は、インドの民族運動の指導者と、韓国の人々にとって、それぞれどのような意味をもったか。', hint: '同じできごとを、2つの立場から見ます。', steps: ['インドの人々から見ると、アジアの立憲国家がヨーロッパの大国に勝ったことは、自分たちも植民地支配から抜け出せるという希望になった。', '実際、インドでは1906年に国民会議派が自治などを求める方針をかかげ、民族運動が強まった。', '韓国の人々から見ると、日本の勝利によって日本の韓国支配を止める国がなくなった。', '実際、韓国は1905年に保護国とされ、1910年に併合された。'], a: 'インドの民族運動にとっては、植民地支配からの解放への希望となった。一方、韓国の人々にとっては、日本による保護国化と併合、つまり植民地化への道となった。', check: '同じできごとが「希望」と「植民地化」という反対の意味をもったことが書かれているか確かめます。' }] },
      { h: 'もっと深く:帝国主義を支えた考え方──社会進化論と「文明化の使命」', t: '帝国主義は、軍事力や経済力だけで進められたのではありません。人々に「植民地支配は正しい」と思わせる【考え方】がありました。\nその一つが【社会進化論】です。生物は生存競争の中で進化するというダーウィンの進化論を、人間の社会や民族にあてはめ、「強い民族が弱い民族を支配するのは自然なことだ」とする考え方です。これは人種による優劣という誤った見方と結びつき、植民地支配を正当化する理屈として使われました。\nもう一つが「【文明化の使命】」という考え方です。ヨーロッパの人々は、自分たちが「遅れた」人々に文明を広める役割をもつと考えました。イギリスの詩人キプリングの「白人の責務」ということばがよく知られています。実際には、鉄道や学校の建設も、支配と資源獲得のために行われた面が強かったのです。\n日本も、この考え方と無関係ではありませんでした。福沢諭吉が書いたとされる「脱亜論」(1885年、新聞『時事新報』の社説)は、日本はアジアの国々と同じ道を歩むのではなく、欧米の列強と同じ立場に立つべきだと主張したものとして知られています。日本は、不平等条約に苦しむ「される側」から出発し、台湾・朝鮮を植民地とする「する側」へと変わっていきました。\n帝国主義を学ぶときは、「なぜ列強は進出できたか」だけでなく、「支配する側はそれをどう正当化したか」「支配された側はどう受けとめ、どう抵抗したか」という複数の立場から見ることが大切です。',
        key: '社会進化論や「文明化の使命」が植民地支配を正当化した。日本は不平等条約を課される側から、植民地をもつ側へと立場を変えた。' },
      { h: '入試ではこう出る:条約改正の担当者と二つの講和条約', t: '日本史と重なるこの単元では、【条約改正の流れ】と【下関条約・ポーツマス条約の比較】が定番です。\n条約改正は、担当した外務大臣の順に押さえます。【井上馨】は鹿鳴館での欧化政策を進めましたが、外国人判事を任用する案などが批判されて失敗しました。【大隈重信】も外国人判事の任用案が問題になり、襲撃されて交渉は中断します。【青木周蔵】は交渉を進めましたが、1891年の【大津事件】(ロシア皇太子が警察官に切りつけられた事件)で辞任しました。そして【陸奥宗光】が1894年、日清戦争の直前に【日英通商航海条約】を結び、【領事裁判権の撤廃】に成功します。最後に【小村寿太郎】が1911年、【関税自主権の完全回復】を実現しました。\nイギリスが1894年に改正に応じた背景には、ロシアのシベリア鉄道建設(1891年着工)による南下への警戒がありました。国際関係とつなげると、論述でも使える知識になります。\n講和条約は、表にして比べます。【下関条約】(1895年)は、朝鮮の独立承認、遼東半島・台湾・澎湖諸島の割譲、賠償金2億両、開港など。【ポーツマス条約】(1905年)は、韓国に対する指導権、旅順・大連の租借権、長春以南の鉄道の利権、北緯50度以南の樺太、沿海州などの漁業権で、【賠償金はなし】でした。\nひっかけの定番は、「ポーツマス条約で賠償金を得た」「下関条約で樺太を得た」「領事裁判権の撤廃は小村寿太郎」などです。',
        key: '1894年 陸奥宗光=領事裁判権の撤廃、1911年 小村寿太郎=関税自主権の回復。下関条約は賠償金あり、ポーツマス条約は賠償金なし。',
        ex: [
          { q: '次の組み合わせのうち、誤っているものを1つ選び、正しく直そう。\nア 井上馨 ― 鹿鳴館で欧化政策を進めた\nイ 青木周蔵 ― 大津事件の責任をとって辞任した\nウ 陸奥宗光 ― 関税自主権の完全回復に成功した\nエ 小村寿太郎 ― ポーツマス条約の交渉で日本全権を務めた', hint: '1894年と1911年の成果を、だれが上げたか思い出します。', steps: ['ア:井上馨は鹿鳴館外交で知られる。正しい。', 'イ:青木周蔵は1891年の大津事件で辞任した。正しい。', 'ウ:陸奥宗光が実現したのは1894年の領事裁判権の撤廃。関税自主権の回復は1911年の小村寿太郎。誤り。', 'エ:小村寿太郎はポーツマス会議の日本全権。正しい。'], a: 'ウ(陸奥宗光が実現したのは領事裁判権の撤廃。関税自主権の完全回復は小村寿太郎)', check: '「陸奥=1894=領事裁判権」「小村=1911=関税自主権」の2組が正しく結べているか確かめます。' },
          { q: '下関条約とポーツマス条約を「賠償金」の点で比べ、そのちがいが日本国内にどのような反応を生んだか説明しよう。', hint: 'ポーツマス条約のあと、東京で何が起きたかを思い出します。', steps: ['下関条約では、清から賠償金2億両を得た。', 'ポーツマス条約では、ロシアから賠償金を得られなかった。', '日露戦争では多くの戦死者を出し、増税や国債で国民の負担も大きかった。', 'そのため、賠償金がないことに不満をもった民衆が日比谷焼き打ち事件を起こした。'], a: '下関条約では清から賠償金2億両を得たが、ポーツマス条約では賠償金を得られなかった。日露戦争は多くの犠牲と重い税負担をともなっていたため、国民の不満が爆発し、日比谷焼き打ち事件が起きた。', check: '「比較(あり/なし)」と「その結果(国民の反応)」の両方が書けているか確かめます。' }
        ] }
    ],
    drill: [
      { lv: 1, q: '日清戦争の講和条約で日本が得たが、ロシア・ドイツ・フランスの三国干渉によって清に返した半島はどこ?', a: '遼東半島', exp: '三国干渉のあと、ロシアは返還された遼東半島の旅順・大連を租借しました。\n日本国内では「臥薪嘗胆」をスローガンにロシアへの反感が高まり、軍備の拡張が進みます。これが日露戦争への道の一歩になりました。' },
      { lv: 1, q: '1898年、アフリカでイギリスの縦断政策とフランスの横断政策が衝突した事件を何という?', a: 'ファショダ事件', exp: 'スーダンのファショダで英仏の軍が向き合いましたが、フランスが譲歩して戦争は避けられました。\nその後、ドイツへの警戒から英仏は接近し、1904年に英仏協商を結びます。アフリカ分割の対立が、ヨーロッパの同盟関係を変えたことに注目しましょう。' },
      { lv: 1, q: '1898年の米西戦争の結果、アメリカがスペインから獲得したアジアの島々はどこ?', a: 'フィリピン', exp: 'アメリカは米西戦争でフィリピン・グアム・プエルトリコを得て、同じ1898年にはハワイも併合しました。\nアメリカも太平洋・アジアに進出する帝国主義国の一つになったことを押さえましょう。これが1899年の門戸開放の主張にもつながります。' },
      { lv: 2, q: '1894年、イギリスが日本との条約改正(領事裁判権の撤廃)に応じた理由を、ロシアの動きと結びつけて説明しよう。', a: 'ロシアがシベリア鉄道の建設を始めるなど東アジアへの南下を強めていたため、イギリスはロシアに対抗するうえで日本との関係を強めておくことが有利だと考えたから。', exp: '日本の法典の整備や憲法の制定など、国内の近代化が進んだことも条件の一つでした。\nしかし、大きなきっかけは国際関係です。イギリスはアジアでロシアと対立しており、日本を味方につけることに利点を見いだしました。この流れは、1902年の日英同盟につながっていきます。\n採点のポイントは、「ロシアの南下」と「イギリスの対抗の必要」が結びついているかです。' },
      { lv: 2, q: '社会進化論とはどのような考え方か。また、それが帝国主義の時代にどのように使われたか説明しよう。', a: '生物の進化論を人間の社会や民族にあてはめ、生存競争で強い者が生き残るのは自然だとする考え方。強い民族が弱い民族を支配するのは当然だという理屈として、列強の植民地支配を正当化するのに使われた。', exp: '社会進化論は、19世紀後半に広まりました。\n人種や民族に優劣があるという誤った考えと結びつき、植民地支配や差別を正当化する役割を果たしました。今日では、科学的にも倫理的にも否定されている考え方です。\n採点のポイントは、①進化論を社会にあてはめたこと、②植民地支配の正当化に使われたこと、の2点です。' },
      { lv: 3, q: '日露戦争中から1910年の韓国併合までの過程を、3つの段階に分けて説明しよう。', a: '①日露戦争中の1904年、第1次日韓協約で日本が推薦する顧問を韓国政府に置かせた。②1905年の第2次日韓協約で韓国の外交権をうばって保護国とし、統監府を置いた(初代統監は伊藤博文)。③1907年の第3次日韓協約で内政の権限もにぎり、韓国の軍隊を解散させた。義兵運動などの抵抗をおさえ、1909年に伊藤博文が安重根に暗殺されたあと、1910年に韓国を併合した。', exp: '韓国併合は、一度に行われたのではなく、外交→内政→併合と段階的に進められました。\n第3次日韓協約の前には、韓国皇帝がハーグの万国平和会議に使者を送って抗議した事件(ハーグ密使事件)があり、日本はこれを理由に皇帝を退位させています。\n採点のポイントは、①顧問の設置、②外交権の剥奪と統監府、③内政権の掌握と軍隊解散、④併合、の順番が正しいかと、韓国側の抵抗(義兵運動など)に触れているかです。' },
      { lv: 3, q: '日本は「不平等条約を結ばされる側」から「植民地をもつ側」へと立場を変えた。この変化を、1890年代から1910年までの具体的なできごとを挙げて説明しよう。', a: '日本は幕末に結んだ不平等条約のもとで近代化を進め、1894年に領事裁判権を撤廃した。同じ年に始まった日清戦争に勝ち、1895年の下関条約で台湾を植民地とした。さらに日露戦争に勝ってポーツマス条約で韓国への指導権を認めさせ、1910年に韓国を併合した。こうして日本は、欧米列強と同じように植民地をもつ帝国主義国となった。', exp: 'このテーマは、「近代化」と「帝国主義」をつなぐ重要な論点です。\n日本は、列強に対抗するために近代化を急ぎましたが、その過程で自らもアジアの近隣地域を支配する側に立ちました。\n採点のポイントは、①条約改正(1894年)、②台湾の領有(1895年)、③韓国併合(1910年)の3つの具体例と、④「される側からする側へ」という変化をまとめる一文です。支配された台湾・朝鮮の人々の立場にも触れられると、さらに深い答えになります。' }
    ],
    faq: [
      ['「帝国主義」と、昔の「帝国」はどうちがうの?', 'ローマ帝国やモンゴル帝国のように、広い地域を支配した国は昔からありました。\n歴史の用語としての帝国主義は、主に19世紀後半からの、工業化した列強が原料・市場・投資先を求めて世界を分割した動きを指します。経済の工業化と強く結びついている点が特徴です。'],
      ['なぜイギリスは日本と同盟を結んだの?', 'イギリスは世界中に植民地をもち、ロシアの南下がインドや中国の権益をおびやかすことを心配していました。しかし、南アフリカでの戦争などで、アジアに大きな兵力を割く余裕がありませんでした。\nそこで、ロシアと対立していた日本と組むことで、アジアでのロシアの進出をおさえようとしたのです。'],
      ['日比谷焼き打ち事件で、国民はなぜそんなに怒ったの?', '日露戦争は日清戦争よりはるかに多くの戦死者を出し、戦費をまかなうための増税で国民の生活は苦しくなっていました。\nそれなのに賠償金がまったく得られなかったため、「これだけ犠牲をはらったのに」という不満が爆発しました。'],
      ['「植民地」「租借地」「勢力範囲」はどうちがうの?', '支配の強さの順に並べると、植民地 > 租借地 > 勢力範囲 です。\n【植民地】は、その地域をまるごと自国の領土として支配するものです(例:日本の台湾、イギリスのインド)。【租借地】は、一定の期間を決めて土地を借り、その間は事実上自国のように支配するものです(例:ドイツの膠州湾、ロシアの旅順・大連)。【勢力範囲】は、領土にはしないものの、鉄道や鉱山などの利権を優先的に手に入れる地域のことです(例:列強による中国分割での各国の勢力範囲)。\n中国は全体が植民地になったわけではありませんが、租借地と勢力範囲によって「分割」されていった、と整理しましょう。']
    ],
    terms: [['帝国主義', '列強が軍事力を背景に、アジア・アフリカなどを植民地や勢力範囲として支配しようとした動き(おおむね1870年代〜第一次世界大戦)'], ['第2次産業革命', '19世紀後半、石油・電力を使う重化学工業が中心になった変化'], ['ベルリン会議', '1884〜85年、ビスマルクが開いた、アフリカ分割の原則を決めた会議'], ['三国干渉', '1895年、ロシア・ドイツ・フランスが遼東半島を清に返すよう日本に求めたこと'], ['門戸開放', '1899年、アメリカが中国市場への各国の平等な参加を求めた主張'], ['ポーツマス条約', '1905年、日露戦争の講和条約。アメリカの仲介'], ['辛亥革命', '1911年に始まり、1912年に中華民国を成立させ、清をほろぼした革命'], ['韓国併合', '1910年、日本が韓国を植民地とし、朝鮮総督府を置いたこと']],
    miss: ['領事裁判権の撤廃(1894年・陸奥宗光)と関税自主権の回復(1911年・小村寿太郎)の年と人物を逆にする。日清戦争の直前が領事裁判権、韓国併合の翌年が関税自主権と、戦争と結びつけて覚えます。', '三国干渉の3国に、イギリスやアメリカを入れてしまう。正しくはロシア・ドイツ・フランス。イギリスはむしろ日本と同盟を結ぶ側です。', 'ポーツマス条約で賠償金を得たと思う。得られなかったから日比谷焼き打ち事件が起きた、と結果とセットで覚えます。', '日露戦争を「アジアの解放につながった」とだけ説明する。韓国にとっては植民地化への道であり、日本自身も列強と同じ帝国主義の道を進んだことを忘れないようにします。'],
    sum: ['第2次産業革命を背景に、列強は原料・市場・投資先を求めて植民地を広げた(帝国主義)。', 'ベルリン会議以後アフリカは分割され、アジア・太平洋も列強の支配下に入った。', '日清戦争(1894〜95年)で日本は台湾を得たが、三国干渉で遼東半島を返した。', '中国分割・義和団戦争の後、日英同盟を結んだ日本は日露戦争(1904〜05年)に勝った。', '日露戦争はアジアの民族運動を刺激したが、日本は韓国を併合(1910年)し、1911年に条約改正を達成した。'],
    next: '次は「第一次世界大戦と大衆社会(hs_ww1)」です。帝国主義の対立が世界規模の戦争になり、戦後に国際協調と大衆の時代が始まる流れを学びます。'
  };

  // ===== 国際秩序の変化や大衆化と私たち =====
  L.hs_ww1 = {
    goal: '第一次世界大戦がなぜ起き、なぜ総力戦になったのかを説明でき、ロシア革命、ヴェルサイユ体制・ワシントン体制による国際協調、アジアの民族運動、大衆社会の成立を、日本の動きと結びつけて説明できるようになる。',
    intro: 'もし戦争で、兵士だけでなく、工場で働く人、畑を耕す人、学校の子どもまでが「戦争のための力」として数えられたらどうなるでしょうか。第一次世界大戦はまさにそういう戦争でした。国民全体を巻きこんだ戦争のあと、国民は「それなら政治にも参加させよ」と求め、選挙権が広がり、大衆が社会の主役になる時代が始まります。',
    pre: '前の単元で学んだように、列強は帝国主義のもとで植民地や勢力範囲を広げ、たがいに対立していました。\nドイツは統一(1871年)の後、急速に工業化し、イギリスに追いつこうとしていました。\nバルカン半島は、オスマン帝国の力がおとろえた後、多くの民族が独立や領土を求めて争う地域になっていました。\n日本は日英同盟(1902年)を結び、日露戦争(1904〜05年)に勝ち、韓国を併合(1910年)して、列強の一員になっていました。',
    secs: [
      { h: '列強の対立とバルカン問題', t: 'なぜヨーロッパの小さな地域の事件が、世界大戦になったのでしょうか。それは、列強が2つの陣営に分かれ、同盟によって結びついていたからです。\n一方は、ドイツ・オーストリア・イタリアの【三国同盟】(1882年)です。もう一方は、イギリス・フランス・ロシアの【三国協商】で、露仏同盟、英仏協商(1904年)、英露協商(1907年)によってできあがりました。急成長するドイツに対し、イギリスが警戒を強めたことが背景にあります。\n対立の火種になったのが【バルカン半島】です。スラヴ系の民族を団結させようとするロシアとセルビア(パン=スラヴ主義)と、この地域に勢力をのばしたいオーストリアとドイツ(パン=ゲルマン主義)が対立しました。1908年にオーストリアがボスニア・ヘルツェゴヴィナを併合すると、セルビアは強く反発しました。バルカン半島は「【ヨーロッパの火薬庫】」とよばれました。\n1914年6月、ボスニアの【サライェヴォ】で、オーストリアの帝位継承者夫妻がセルビア人の青年に暗殺されました(【サライェヴォ事件】)。オーストリアがセルビアに宣戦すると、同盟関係によってロシア・ドイツ・フランス・イギリスが次々に参戦し、【第一次世界大戦】になりました。\nなお、イタリアはオーストリアとの領土問題から同盟側を離れ、1915年に協商国側で参戦しました。',
        key: '三国同盟(独・墺・伊)vs 三国協商(英・仏・露)。バルカン半島の民族対立にサライェヴォ事件(1914年)が火をつけ、同盟の連鎖で世界大戦になった。',
        chain: { title: 'サライェヴォ事件から世界大戦へ', items: [
          ['背景', '列強が三国同盟と三国協商に分かれて対立', 'ドイツの急成長にイギリスが警戒'],
          ['背景', 'バルカン半島の民族対立(ヨーロッパの火薬庫)', 'オーストリアのボスニア・ヘルツェゴヴィナ併合(1908年)にセルビアが反発'],
          ['できごと', 'サライェヴォ事件(1914年6月)', 'オーストリアの帝位継承者夫妻がセルビア人青年に暗殺される'],
          ['できごと', 'オーストリアがセルビアに宣戦 → ロシア・ドイツ・フランス・イギリスが参戦'],
          ['結果', '第一次世界大戦(1914〜18年)', '日本も日英同盟を理由に参戦']] },
        ex: [{ q: 'サライェヴォ事件という1つの暗殺事件が、ヨーロッパ全体の戦争に広がったのはなぜか説明しよう。', hint: '事件の後、だれとだれが同盟を結んでいたかを考えます。', steps: ['事件の後、オーストリアがセルビアに宣戦した。', 'セルビアを支援するロシアが参戦し、オーストリアと同盟を結ぶドイツも参戦した。', 'ロシアと結ぶフランス、さらにイギリスも参戦した。', '列強が2つの陣営に分かれ同盟で結ばれていたため、一つの戦争が連鎖的に広がった。'], a: '列強が三国同盟と三国協商の2つの陣営に分かれ、同盟で結ばれていたため、オーストリアとセルビアの戦争に、それぞれを支援する大国が次々に参戦したから。', check: '「同盟の連鎖」という考え方が入っているか確かめます。' }] },
      { h: '総力戦:国民全体を巻きこむ戦争', t: '多くの人は、戦争は数か月で終わると考えていました。しかし、西部戦線(フランス北東部)では、両軍が長い【塹壕】(兵士が身を守るための溝)をほって向き合い、何年も前線がほとんど動かない戦いになりました。\n戦車・飛行機・毒ガス・潜水艦・機関銃などの【新兵器】が使われ、死傷者は過去の戦争と比べものにならないほどふえました。\n長い戦争を続けるため、各国は国民の生活や経済のすべてを戦争に動員しました。工場は武器をつくり、食料や物資は配給になり、男性が戦場に行ったあとの工場や事務所では【女性】が働きました。このように、軍隊だけでなく国の力のすべてを使う戦争を【総力戦】といいます。\nイギリスやフランスは、植民地からも兵士や労働者を集めました。インドなどの人々は、戦争に協力すれば戦後に自治が認められると期待しました。\n1917年、ドイツが中立国の船も攻撃する【無制限潜水艦作戦】を始めると、アメリカが協商国側で参戦しました。1918年11月、ドイツでは革命が起きて皇帝が退位し、休戦協定が結ばれて戦争は終わりました。',
        key: '総力戦=国民・経済・植民地のすべてを動員する戦争。女性の社会進出が進み、植民地の人々は戦後の自治を期待した。',
        ex: [{ q: '第一次世界大戦が「総力戦」とよばれる理由を、国民の生活の変化から2つ挙げて説明しよう。', hint: '工場・食料・女性・植民地のうち2つを使います。', steps: ['長期戦になり、武器や物資を大量につくり続ける必要があった。', '工場は軍需品の生産に切りかえられ、食料などは配給制になった。', '男性が兵士として戦場に行ったため、女性が工場などで働くようになった。', 'このように、軍隊だけでなく国民全体が戦争のために動員された。'], a: '工場が軍需品の生産に動員され食料も配給制になったこと、男性に代わって女性が工場などで働いたことなど、国民の生活全体が戦争のために動員されたから。', check: '「軍隊だけでなく国民全体」という点が答えに入っているか確かめます。' }] },
      { h: 'ロシア革命とソ連の成立', t: 'ロシアは戦争で大きな損害を受け、食料や燃料が不足して、人々の不満が高まっていました。\n1917年3月(ロシアの暦では2月)、首都で労働者や兵士が立ち上がり、皇帝ニコライ2世が退位して帝政がたおれました(三月革命)。しかし、新しくできた臨時政府は戦争を続けたため、人々の不満はおさまりませんでした。\n同じ年の11月(ロシアの暦では10月)、【レーニン】が率いるボリシェヴィキが臨時政府をたおし、労働者・兵士の代表会議(ソヴィエト)にもとづく政権を樹立しました(十一月革命)。これが【ロシア革命】です。新政権は「平和に関する布告」で、無併合・無賠償・民族自決による講和を各国によびかけ、「土地に関する布告」で地主の土地を取り上げました。\nソヴィエト政権は1918年にドイツと単独で講和し、戦争から離れました。社会主義の広がりをおそれたイギリス・フランス・アメリカ・日本などは、革命に干渉する軍を送りました。日本は1918年に【シベリア出兵】を行い、他国が撤兵したあとも長くとどまり、1922年に撤兵しました。\n1922年、ロシアなどの共和国が集まって【ソヴィエト社会主義共和国連邦】(ソ連)が成立しました。世界で初めての社会主義国家の誕生は、資本主義の国々に大きな衝撃を与えました。',
        key: 'ロシア革命(1917年)でレーニンがソヴィエト政権を樹立。日本はシベリア出兵(1918〜22年)。1922年にソ連成立。',
        ex: [{ q: 'ロシア革命が日本の国内に与えた影響を、シベリア出兵と米騒動を結びつけて説明しよう。', hint: '出兵すると軍は大量の何を必要とするかを考えます。', steps: ['ロシア革命に干渉するため、日本はシベリア出兵を決めた。', '出兵すると軍が大量の米を必要とするとみて、商人による米の買い占めが起きた。', '米の値段が急に上がり、1918年に各地で米の安売りを求める米騒動が起きた。', '米騒動の責任をとって内閣が退陣し、原敬の政党内閣が成立した。'], a: 'ロシア革命への干渉としてシベリア出兵が決まると、米の買い占めで米価が急上昇し、1918年に米騒動が起きた。これをきっかけに内閣が退陣し、原敬の本格的な政党内閣が生まれた。', check: '「ロシア革命 → シベリア出兵 → 米の買い占め → 米騒動 → 政党内閣」の順になっているか確かめます。' }] },
      { h: '日本と第一次世界大戦:大戦景気と大正デモクラシー', t: '日本は1914年、【日英同盟】を理由にドイツに宣戦し、中国の山東半島にあったドイツの拠点(青島)と、赤道より北のドイツ領南洋諸島を占領しました。\n1915年には、中国の袁世凱政府に【二十一か条の要求】を出し、山東省のドイツ権益を日本が引きつぐことなどの多くを認めさせました。中国の人々は強く反発し、受け入れた日を「国恥記念日」としました。\n経済では、ヨーロッパの国々がアジア市場から手を引いたすきに、日本の綿織物などがアジアに、生糸がアメリカに大量に輸出され、海運業・造船業も大きくのびました。これを【大戦景気】といいます。日本は、外国に借金をする国(債務国)から、外国にお金を貸す国(債権国)に変わりました。急に大金持ちになった人々は「成金」とよばれました。\nしかし物価の上昇に賃金が追いつかず、多くの人々の生活は苦しくなりました。1918年の【米騒動】の後、【原敬】が、大臣の多くを衆議院の第一党の党員で占める本格的な【政党内閣】をつくりました。\n吉野作造は、主権の所在は問わずに、政治の目的を民衆の幸福におき、民衆の意見にもとづいて政治を行うべきだとする【民本主義】を説きました。このような民主主義を求める風潮を【大正デモクラシー】といいます。',
        key: '日本は日英同盟を理由に参戦し、二十一か条の要求(1915年)を出した。大戦景気で債権国になったが物価高で米騒動(1918年)→ 原敬の政党内閣。' },
      { h: 'ヴェルサイユ体制・ワシントン体制とアジアの民族運動', t: '1919年、【パリ講和会議】が開かれました。アメリカ大統領【ウィルソン】は、前年に発表した【十四か条の平和原則】で、秘密外交の廃止、軍備の縮小、【民族自決】(それぞれの民族が自分たちのことを自分たちで決める)、国際平和機構の設立などを示していました。\n【ヴェルサイユ条約】で、敗れたドイツはすべての植民地を失い、アルザス・ロレーヌをフランスに返し、軍備を制限され、巨額の賠償金を課されました。民族自決の原則によって、東ヨーロッパではポーランドなどの国々が独立しました。1920年には【国際連盟】が発足し、日本は常任理事国になりましたが、提案したアメリカは議会の反対で加盟しませんでした。日本は山東省のドイツ権益の継承を認められ、赤道以北の旧ドイツ領南洋諸島を委任統治することになりました。\nしかし、民族自決は【アジア・アフリカの植民地には適用されません】でした。これに失望し、また民族自決に励まされた人々は、各地で運動を起こしました。朝鮮では1919年3月1日、日本からの独立を求める【三・一独立運動】が起き、日本は武力でおさえました。中国では同じ年の5月4日、山東権益の返還を求める【五・四運動】が起き、中国政府はヴェルサイユ条約の調印を拒否しました。インドでは【ガンディー】が非暴力・不服従の運動を指導しました。\nアジア・太平洋については、1921〜22年の【ワシントン会議】で新しい秩序がつくられました。海軍軍縮条約で主力艦の保有比率を米英5・日本3などとし、四か国条約で太平洋の現状維持を約束して【日英同盟は廃棄】され、九か国条約で中国の主権尊重と門戸開放を確認しました。日本は山東省の旧ドイツ権益を中国に返しました。\nこの後、ヨーロッパではロカルノ条約(1925年)、世界的には不戦条約(1928年)が結ばれ、1920年代は【国際協調】の時代となりました。',
        key: '民族自決は東ヨーロッパには適用、アジアの植民地には適用されず → 三・一独立運動・五・四運動(1919年)。ワシントン会議で日英同盟廃棄・海軍軍縮・中国の主権尊重。',
        ex: [{ q: '1919年に朝鮮と中国で起きた民族運動の名前と、それぞれが何を求めたかを答えよう。また、共通する背景を説明しよう。', hint: 'パリ講和会議で示された原則を思い出しましょう。', steps: ['朝鮮では三・一独立運動が起き、日本の植民地支配からの独立を求めた。', '中国では五・四運動が起き、日本が引きついだ山東省の旧ドイツ権益の返還を求めた。', '共通の背景として、パリ講和会議で民族自決の原則が唱えられたことがある。', 'しかし、その原則がアジアには適用されなかったことへの失望が、運動を大きくした。'], a: '朝鮮の三・一独立運動は日本からの独立を、中国の五・四運動は山東省の権益返還を求めた。共通の背景は、民族自決の原則が唱えられながら、アジアには適用されなかったことへの失望と反発である。', check: '運動の名前・場所・要求が正しく対応しているか(三・一=朝鮮、五・四=中国)確かめます。' }, { q: 'ワシントン会議で結ばれた3つの条約と、それぞれの日本への影響を整理しよう。', hint: '「海軍」「太平洋」「中国」の3つのテーマに分けます。', steps: ['海軍軍縮条約:主力艦の保有比率を米英5・日本3などとした。日本の海軍の拡大がおさえられた。', '四か国条約:太平洋の島々の現状維持を約束した。これにより日英同盟が廃棄された。', '九か国条約:中国の主権尊重・門戸開放を約束した。日本は山東省の旧ドイツ権益を中国に返した。'], a: '海軍軍縮条約で日本の主力艦はアメリカ・イギリスの6割に制限され、四か国条約で日英同盟が廃棄され、九か国条約で中国の主権尊重が決まり日本は山東権益を返した。', check: '3つの条約のテーマ(海軍・太平洋・中国)が重なっていないか確かめます。' }] },
      { h: '大衆社会の成立', t: '総力戦を経験した各国では、戦争に協力した国民、特に労働者や女性の発言力が高まりました。「戦争で義務を果たしたのだから、政治に参加する権利も」という考えが広がり、選挙権が大きく広がりました。\nイギリスでは1918年に30歳以上の女性に、1928年には21歳以上の男女に選挙権が認められました。アメリカでは1920年に女性参政権が実現しました。ドイツでは、1919年の【ヴァイマル憲法】が男女普通選挙を定め、人間らしい生活を保障する【社会権】を初めて明記しました。\n経済では、戦後に繁栄したアメリカで、フォード社などが流れ作業で自動車を大量生産し、【大量生産・大量消費】の生活が広がりました。【ラジオ】や【映画】、新聞・雑誌が普及し、多くの人々が同じ情報や娯楽を楽しむようになりました。このように、大衆(一般の多くの人々)が政治・経済・文化の主役になる社会を【大衆社会】といいます。\n日本でも都市化が進み、会社員などの新中間層や、電話交換手・タイピストなどとして働く「職業婦人」がふえました。1925年にはラジオ放送が始まりました。平塚らいてうや市川房枝らは新婦人協会(1920年)をつくって女性の権利を求め、1922年には部落差別からの解放をめざす全国水平社がつくられました。\n1925年、加藤高明内閣のもとで【普通選挙法】が成立し、満25歳以上のすべての男子が衆議院議員の選挙権をもつことになりました。同じ年に、国のしくみを変えようとする運動や社会主義運動を取りしまる【治安維持法】も制定されました。女性の参政権は、日本ではまだ認められませんでした。',
        key: '総力戦の後、選挙権が拡大し、大量生産・大量消費とラジオ・映画が大衆社会を生んだ。日本は1925年に普通選挙法(男子のみ)と治安維持法。',
        flow: { title: '選挙権の拡大(第一次世界大戦の前後)', cols: 3, rows: [
          [['イギリス', 'r', 1, '1918年 30歳以上の女性にも / 1928年 21歳以上の男女'], ['アメリカ', 'b', 1, '1920年 女性参政権'], ['ドイツ', 'o', 1, '1919年 ヴァイマル憲法で男女普通選挙']],
          [['日本', 'g', 3, '1925年 普通選挙法:満25歳以上の男子(女性は1945年の法改正まで認められない)']]
        ], legend: [['r', 'イギリス'], ['b', 'アメリカ'], ['o', 'ドイツ'], ['g', '日本']] },
        ex: [{ q: '1925年の日本で、普通選挙法と治安維持法が同じ年に制定されたのはなぜだと考えられるか説明しよう。', hint: '選挙権が広がると、政府はどんな動きを心配したかを考えます。', steps: ['普通選挙法で、納税額の制限がなくなり、満25歳以上の男子全員が選挙権をもった。', '有権者が大きくふえ、労働者や農民の声が政治に入るようになった。', '政府は、ロシア革命の影響を受けた社会主義運動が広がることを心配していた。', 'そこで、選挙権を広げると同時に、国のしくみを変えようとする運動を取りしまる治安維持法をつくった。'], a: '普通選挙で労働者や農民の政治参加が広がる一方、ロシア革命の影響による社会主義運動の広がりを政府がおそれ、それを取りしまるために治安維持法を同時に制定したと考えられる。', check: '「選挙権の拡大」と「社会主義運動の取りしまり」の2つがセットになっているか確かめます。' }] },
      { h: 'もっと深く:なぜ戦争は4年以上も続いたのか', t: '1914年の夏、多くの人は「クリスマスまでには終わる」と考えていました。ドイツは、まず西のフランスを短期間でたおし、そのあと東のロシアと戦う計画を立てていました。しかし、この予想は外れます。\n1914年9月の【マルヌの戦い】でドイツ軍の進撃が止まると、西部戦線では両軍が長い【塹壕】(兵士がひそむ溝)を掘って向き合う【塹壕戦】になりました。前線はスイス国境から北海近くまで延び、ほとんど動かなくなります。\nなぜ動かなかったのか。【機関銃】と鉄条網によって、守る側が圧倒的に有利になったからです。攻める兵士は、塹壕から出たとたんに機関銃で撃たれました。わずかな前進のために、数十万人規模の死傷者が出る戦いもありました。\nこの行きづまりを破るため、【毒ガス】・【戦車】・【飛行機】・【潜水艦】などの新兵器が次々に使われました。科学技術と工業力が戦争の勝敗を左右するようになり、戦争は国の経済全体を動員する総力戦へと変わっていきます。\n戦争の流れを変えたのは、1917年の2つのできごとです。ドイツの【無制限潜水艦作戦】をきっかけに【アメリカが参戦】し、一方でロシアでは革命が起き、ソヴィエト政権が1918年にドイツと単独で講和しました(ブレスト=リトフスク条約)。最後は、1918年11月にドイツで革命が起きて皇帝が退位し、休戦協定が結ばれて戦争が終わりました。',
        key: '機関銃と鉄条網で守る側が有利になり、西部戦線は塹壕戦で動かなくなった。1917年のアメリカ参戦とロシアの離脱が流れを変え、1918年のドイツ革命で終結した。' },
      { h: '入試ではこう出る:14か条・国際連盟・ヴェルサイユ条約', t: 'この単元では、戦後の国際秩序についての【正誤問題】と、【ドイツへの処置】をめぐる論述がよく出ます。\nアメリカ大統領【ウィルソン】は1918年1月に【14か条の平和原則】を発表しました。秘密外交の廃止、海洋の自由、軍備の縮小、民族自決(東ヨーロッパなどの一部)、国際平和機構の設立などです。これにもとづき、1920年に【国際連盟】が発足しました。本部は【ジュネーヴ】で、日本は常任理事国になりました。\nひっかけの定番は次の3つです。①「アメリカは国際連盟の中心となって加盟した」→誤り。上院がヴェルサイユ条約の批准を拒否し、アメリカは加盟しませんでした。②「国際連盟は発足当初からドイツ・ソ連も加盟した」→誤り。当初は除外されていました(ドイツは1926年、ソ連は1934年に加盟)。③「民族自決は世界中に適用された」→誤り。主に東ヨーロッパに限られました。\n【ヴェルサイユ条約】(1919年)でドイツは、すべての植民地の放棄、アルザス・ロレーヌのフランスへの返還、軍備の制限、ラインラントの非武装化、巨額の賠償金などを課されました。\n論述では、「ヴェルサイユ体制の問題点」が問われます。敗戦国ドイツへのきびしい処置がドイツ国民の不満を生んだこと、民族自決がアジア・アフリカに適用されなかったこと、提唱国アメリカが連盟に入らなかったことの3点を軸に書きましょう。',
        key: '国際連盟の弱点:アメリカ不参加・当初はドイツとソ連を除外・軍事制裁の手段なし。ヴェルサイユ条約のきびしい内容がドイツの不満を生んだ。',
        ex: [
          { q: '国際連盟について述べた次の文の正誤を判定し、誤りは正しく直そう。\nア 国際連盟の本部は、スイスのジュネーヴに置かれた。\nイ 国際連盟の設立を提唱したアメリカは、常任理事国として加盟した。\nウ 日本は国際連盟の常任理事国となった。\nエ ドイツとソ連は、国際連盟の発足当初から加盟していた。', hint: '「アメリカ」「ドイツ」「ソ連」がいつ加盟したか(しなかったか)を確かめます。', steps: ['ア:本部はジュネーヴ。正しい。', 'イ:アメリカは上院の反対で加盟しなかった。誤り。', 'ウ:日本はイギリス・フランス・イタリアとともに常任理事国になった。正しい。', 'エ:発足当初、ドイツ(敗戦国)とソ連(革命政権)は除外されていた。誤り。'], a: 'ア 正しい、イ 誤り(アメリカは加盟しなかった)、ウ 正しい、エ 誤り(当初は除外され、ドイツは1926年、ソ連は1934年に加盟)', check: '誤りの2文を直すと、連盟の弱点(大国の不参加)が見えてくるか確かめます。' },
          { q: 'ヴェルサイユ条約でドイツに課された内容を3つ挙げ、それがドイツ国民にどのような感情を生んだか説明しよう。', hint: '領土・軍備・お金の3つの面から考えます。', steps: ['領土:すべての植民地を失い、アルザス・ロレーヌをフランスに返還した。', '軍備:陸軍や海軍の規模がきびしく制限され、ラインラントが非武装化された。', 'お金:巨額の賠償金の支払いを課された。', 'ドイツは交渉に参加できず条約をおしつけられたため、国民の間に強い不満と屈辱感が生まれ、のちにナチスが条約の破棄を訴えて支持を集める背景になった。'], a: '植民地の放棄とアルザス・ロレーヌの返還、軍備の制限とラインラントの非武装化、巨額の賠償金。ドイツは条約をおしつけられたと受けとめ、国民の間に強い不満と屈辱感が広がった。', check: '「領土・軍備・賠償金」の3つの面がそろい、国民感情と後の時代へのつながりが書けているか確かめます。' }
        ] }
    ],
    drill: [
      { lv: 1, q: '1914年、日本が第一次世界大戦に参戦する根拠とした同盟は何?', a: '日英同盟', exp: '日本は日英同盟を理由にドイツに宣戦し、中国の山東半島の青島や、赤道以北のドイツ領南洋諸島を占領しました。\n同盟の義務というより、アジアでの勢力を広げる好機と考えた面が大きかったことも押さえておきましょう。' },
      { lv: 1, q: '国際連盟の本部が置かれた都市はどこ?', a: 'ジュネーヴ(スイス)', exp: 'スイスは永世中立国で、国際機関の本部を置くのに適していました。\n第二次世界大戦後の国際連合の本部はニューヨークです。連盟と国連の本部を取りちがえないようにしましょう。' },
      { lv: 2, q: 'ロシア革命直後にレーニンが出した「平和に関する布告」は、どのような講和の原則を呼びかけたか。また、それがウィルソンの14か条とどう関係するか説明しよう。', a: '無併合・無償金・民族自決にもとづく即時の講和を、すべての交戦国に呼びかけた。社会主義の側から出されたこの呼びかけに対抗する形で、ウィルソンは14か条の平和原則を発表し、民族自決や国際平和機構などの理念を示した。', exp: '「無併合」は領土をうばわない、「無償金」は賠償金をとらない、という意味です。\nこの呼びかけは、戦争に疲れた各国の人々に大きな影響を与えました。アメリカは、社会主義の影響が広がることを警戒し、自由主義の側からの戦後構想として14か条を示したのです。\n採点のポイントは、①無併合・無償金・民族自決、②14か条が対抗する形で出された、の2点です。' },
      { lv: 2, q: '第一次世界大戦中、日本が「大戦景気」とよばれる好景気をむかえた理由を説明しよう。', a: 'ヨーロッパの国々が戦争に追われてアジア市場から後退したため、日本製品がアジアに輸出された。また、連合国への軍需品や、好景気のアメリカへの生糸の輸出も増えた。その結果、日本は輸出が輸入を上回り、債務国から債権国になった。', exp: '大戦景気では、造船業や海運業が大きく伸び、「船成金」が生まれました。また、ドイツからの輸入が止まったことで化学工業も発展しました。\n一方で、物価が上がり、庶民の生活は苦しくなりました。これが1918年の米騒動の背景の一つになります。\n採点のポイントは、①ヨーロッパのアジア市場からの後退、②連合国・アメリカへの輸出、③債権国への転換、の3点です。' },
      { lv: 3, q: '1918年に成立した原敬内閣が「初の本格的な政党内閣」とよばれる理由と、その政策の限界を説明しよう。', a: '原敬は衆議院の第一党である立憲政友会の総裁で、陸軍・海軍・外務大臣以外の閣僚を政友会の党員で固めたから。また、爵位をもたない「平民宰相」として国民の期待を集めた。しかし、普通選挙には慎重で、選挙権の納税資格を直接国税3円以上に引き下げるにとどまった。', exp: '米騒動で寺内正毅内閣がたおれたあと、原敬内閣が成立しました。\n政党内閣とは、議会の多数党が内閣を組織するものです。原内閣は、鉄道の拡張や高等教育の充実など、支持基盤を広げる政策を進めました。\n採点のポイントは、①衆議院第一党の総裁が首相、②閣僚の多くが党員、③普通選挙に慎重だったという限界、の3点です。普通選挙の実現は1925年の加藤高明内閣まで待つことになります。' },
      { lv: 3, q: '国際連盟の設立を提唱したアメリカが、連盟に加盟しなかった理由を説明しよう。また、そのことが連盟にどのような弱点をもたらしたか、ほかの弱点と合わせて説明しよう。', a: 'アメリカでは、ヨーロッパの争いに巻きこまれることを嫌う孤立主義の考えが強く、上院がヴェルサイユ条約の批准を拒否したため加盟しなかった。最大の経済大国が参加しなかったことで、連盟の影響力は弱まった。さらに、議決が原則として全会一致であったことや、違反国に対して経済制裁しかできず軍事的な制裁の手段をもたなかったことも弱点だった。', exp: 'アメリカには、19世紀以来、ヨーロッパのことに深く関わらないというモンロー主義の伝統がありました。\n連盟の弱点は、1930年代の満州事変やイタリアのエチオピア侵攻で、侵略を止められないという形で表に出ます。\n採点のポイントは、①孤立主義・上院の批准拒否、②大国の不参加による影響力の低下、③全会一致・軍事制裁の手段なし、の3点です。国際連合ではこれらの反省がどう生かされたかと比べると、理解が深まります。' }
    ],
    faq: [
      ['第一次世界大戦は、なぜ「世界」大戦なの?ヨーロッパの戦争では?', '主な戦場はヨーロッパでしたが、列強の植民地から兵士や労働者が動員され、アフリカや中東、太平洋でも戦いがありました。\n日本やアメリカ、オスマン帝国なども参戦し、世界の多くの地域を巻きこんだので、世界大戦とよばれます。'],
      ['民族自決は、なぜアジアやアフリカには適用されなかったの?', '戦勝国のイギリスやフランス、日本は、自分たちの植民地を手放すつもりがなかったからです。民族自決が適用されたのは、主に敗れたドイツ・オーストリア・ロシアの支配下にあった東ヨーロッパの地域でした。'],
      ['ロシアの暦で「2月」「10月」というのはなぜ?', '当時のロシアは、ほかのヨーロッパの国々とはちがう古い暦(ユリウス暦)を使っていて、約13日のずれがありました。\nそのため、同じ革命が「二月革命・十月革命」とも「三月革命・十一月革命」ともよばれます。'],
      ['「総力戦」は、第一次世界大戦が初めてなの?', '国民を大規模に動員する戦争の先がけとしては、フランス革命期の国民軍や、アメリカの南北戦争などが挙げられます。\nしかし、工業力・科学技術・国民の生活・植民地の人々までを、4年以上にわたって国全体で動員した点で、第一次世界大戦は本格的な総力戦の始まりとされます。\n総力戦になると、戦争に協力した国民は「その見返りに政治に参加させてほしい」と求めるようになりました。大戦後に多くの国で選挙権が広がった(女性参政権を含む)のは、この流れの一つです。']
    ],
    terms: [['三国協商', 'イギリス・フランス・ロシアの協力関係。ドイツ中心の三国同盟と対立した'], ['総力戦', '軍隊だけでなく、国民・経済・植民地のすべてを動員する戦争'], ['ロシア革命', '1917年、帝政がたおれ、レーニンらがソヴィエト政権を樹立した革命'], ['二十一か条の要求', '1915年、日本が中国に出した、山東省のドイツ権益の継承などの要求'], ['民族自決', 'それぞれの民族が、自分たちの政治のあり方を自分たちで決めるという原則'], ['ワシントン体制', 'ワシントン会議(1921〜22年)で決まった、アジア・太平洋の国際秩序'], ['大衆社会', '一般の多くの人々が、政治・経済・文化の主役となる社会'], ['普通選挙法', '1925年、満25歳以上のすべての男子に衆議院議員の選挙権を与えた法律']],
    miss: ['三国同盟と三国協商の国を混同する。「同盟=ドイツ側(独・墺・伊)、協商=イギリス側(英・仏・露)」と覚え、イタリアは途中で協商側に移ったことも押さえます。', '三・一独立運動(朝鮮)と五・四運動(中国)を取りちがえる。「3月1日=朝鮮の独立、5月4日=中国の山東返還」と、日付・場所・要求をセットにします。', 'アメリカが国際連盟の常任理事国だったと思う。提案国なのに議会の反対で加盟しなかった、という点がよく問われます。', '1925年の普通選挙法で女性にも選挙権が与えられたと思う。男子のみで、女性の参政権は1945年です。イギリス・アメリカ・ドイツより遅かったことも比べて覚えます。'],
    sum: ['列強の二つの陣営の対立とバルカン問題から、サライェヴォ事件(1914年)をきっかけに第一次世界大戦が起きた。', '大戦は国民全体を動員する総力戦となり、1917年にはロシア革命とアメリカの参戦があった。', '日本は参戦して二十一か条の要求を出し、大戦景気の後、米騒動を経て原敬の政党内閣が生まれた。', 'ヴェルサイユ体制とワシントン体制で国際協調が進んだが、民族自決はアジアに適用されず、三・一独立運動や五・四運動が起きた。', '選挙権の拡大やラジオ・映画の普及で大衆社会が生まれ、日本では1925年に普通選挙法と治安維持法が制定された。'],
    next: '次は「世界恐慌と第二次世界大戦(hs_ww2)」です。1920年代の国際協調が、世界恐慌をきっかけにどのように崩れ、再び世界大戦に向かったのかを学びます。'
  };

  L.hs_ww2 = {
    goal: '世界恐慌に対する各国の対応のちがいを説明でき、ファシズムの台頭と日本の対外膨張がどのように国際協調を崩し、日中戦争・第二次世界大戦・太平洋戦争へつながったのかを、因果でつないで説明できるようになる。',
    intro: '1929年10月、ニューヨークで株価が大暴落しました。遠いアメリカの株の話が、なぜ日本の農村の娘の身売りや、ドイツのヒトラーの登場、そして世界大戦につながったのでしょうか。世界の経済がつながっていたからこそ、不況も世界中に広がり、各国が「自分の国だけ助かる道」を選んだことが、次の戦争への道を開いたのです。',
    pre: '1920年代は、ヴェルサイユ体制・ワシントン体制のもとで国際協調が進んだ時代でした。\nアメリカは第一次世界大戦後、世界一の経済大国となり、ヨーロッパの国々に資金を貸していました。ドイツはアメリカの資金を借りて賠償金を払い、イギリス・フランスはそれでアメリカへの借金を返す、というお金の流れがありました。\n日本では、1920年代に戦後恐慌や関東大震災(1923年)、金融恐慌(1927年)など不況が続いていました。\nイタリアでは、すでに1922年に【ムッソリーニ】のファシスト党が政権をにぎっていました。',
    secs: [
      { h: '世界恐慌と各国の対応', t: '1929年10月、ニューヨークのウォール街で株価が大暴落し、【世界恐慌】が始まりました。アメリカの銀行や会社が次々に倒れ、失業者があふれました。アメリカがヨーロッパに貸していた資金を引き上げたため、不況は世界中に広がりました。\nアメリカでは、1933年に大統領となった【フランクリン=ローズヴェルト】が【ニューディール】(新しい政策)を進めました。大規模な公共事業で仕事をつくり、農業の生産を調整し、労働者の権利を保護するなど、政府が積極的に経済に関わる政策でした。\nイギリスやフランスは、本国と植民地を一つの経済圏にまとめ、外国の商品には高い関税をかけてしめ出す【ブロック経済】を行いました。イギリスは1932年のオタワ会議で、イギリス連邦内の特恵関税を決めました。\nソ連は、資本主義国との結びつきが弱く、【五か年計画】(1928年〜)による計画経済で工業化を進めていたため、恐慌の影響をほとんど受けませんでした。ただし、農業の強制的な集団化などで、多くの人々が犠牲になりました。\n広い植民地をもたないドイツ・イタリア・日本は、ブロック経済によって市場をしめ出されました。これらの国では、「持てる国」に対抗し、軍事力で領土や勢力圏を広げようとする動きが強まっていきます。',
        key: '恐慌への対応:アメリカ=ニューディール、イギリス・フランス=ブロック経済、ソ連=五か年計画。植民地の少ない独・伊・日は対外膨張へ。',
        flow: { title: '世界恐慌への各国の対応', cols: 3, rows: [
          [['アメリカ', 'b', 1, 'ニューディール:公共事業・農業調整'], ['イギリス・フランス', 'r', 1, 'ブロック経済:植民地との経済圏'], ['ソ連', 'k', 1, '五か年計画:恐慌の影響が小さい']],
          [['ドイツ', 'o', 1, 'ナチ党の政権 → 軍備拡張'], ['イタリア', 'o', 1, 'ファシスト党 → エチオピア侵攻'], ['日本', 'o', 1, '満州事変 → 国際連盟脱退']]
        ], legend: [['b', '政府が経済に介入'], ['r', '「持てる国」のブロック経済'], ['k', '社会主義の計画経済'], ['o', '「持たざる国」の対外膨張']] },
        ex: [{ q: 'イギリス・フランスのブロック経済が、ドイツ・イタリア・日本の対外膨張をうながしたのはなぜか説明しよう。', hint: 'ブロック経済の外にいる国は、製品をどこに売ればよいかを考えます。', steps: ['ブロック経済は、本国と植民地の間で貿易を優先し、外国の商品に高い関税をかけるしくみだった。', '広い植民地をもたないドイツ・イタリア・日本は、製品を売る市場や原料の入手先をせばめられた。', 'これらの国では、「自分たちも勢力圏をもたなければ生き残れない」という考えが強まった。', 'その結果、軍事力で領土や勢力圏を広げようとする対外膨張が進んだ。'], a: 'ブロック経済によって、植民地の少ないドイツ・イタリア・日本は市場や原料の入手先からしめ出され、自分たちの勢力圏を軍事力で広げようとする動きが強まったから。', check: '「持てる国」と「持たざる国」の対立という視点で説明できているか確かめます。' }] },
      { h: 'ファシズムの台頭:ナチス・ドイツ', t: '【ファシズム】とは、個人の自由や議会政治を否定し、一つの政党と指導者が国民を強く統制して、対外的な膨張をはかる政治のあり方を広くさすことばです。イタリアのファシスト党が始まりで、ドイツのナチ党も代表例です。\nドイツは、ヴェルサイユ条約の重い賠償金や、1923年の激しいインフレで苦しんでいました。世界恐慌でアメリカの資金が引き上げられると、失業者が急増し、人々は議会政治に失望しました。\nそのなかで、【ヒトラー】の率いる【ナチ党】は、ヴェルサイユ体制の打破や、ユダヤ人への差別をあおる主張で支持を集め、1932年の選挙で第一党になりました。1933年にヒトラーが首相になると、【全権委任法】で議会の承認なしに法律をつくれるようにし、ほかの政党を解散させて独裁体制をつくりました。\n注意したいのは、ナチ党が武力によるクーデタではなく、【選挙で支持を集めて】政権をにぎったことです。民主主義の手続きの中から独裁が生まれたという事実は、今も重要な教訓とされています。\nドイツは1933年に国際連盟を脱退し、1935年に再軍備を宣言、1936年にはラインラント(フランスとの国境近くの非武装地帯)に軍を進めました。国内では公共事業と軍需産業で失業を減らしながら、ユダヤ人の権利を奪う法律をつくり、迫害を強めました。',
        key: 'ナチ党は選挙で第一党となり(1932年)、ヒトラー首相(1933年)が全権委任法で独裁。民主主義の手続きから独裁が生まれた。',
        ex: [{ q: 'ナチ党が多くのドイツ国民の支持を集めた背景を、2つの面から説明しよう。', hint: '「経済」と「ヴェルサイユ条約への不満」に分けます。', steps: ['経済の面:世界恐慌でアメリカの資金が引き上げられ、ドイツでは失業者が急増した。', '人々は不況を解決できない議会政治に失望し、強い指導者を求めるようになった。', '国際関係の面:ドイツの人々は、植民地を失い重い賠償金を課されたヴェルサイユ条約に強い不満をもっていた。', 'ナチ党は、仕事の回復とヴェルサイユ体制の打破を訴えて支持を集めた。'], a: '世界恐慌で失業者が急増し議会政治への失望が広がったことと、重い賠償などを課したヴェルサイユ条約への不満が強かったこと。ナチ党はその両方に訴えて支持を集めた。', check: '「経済の苦しさ」と「ヴェルサイユ条約への不満」の2点が入っているか確かめます。' }] },
      { h: '日本の恐慌と満州事変・日中戦争', t: '日本では、1930年に浜口雄幸内閣が金の輸出を解禁して(金解禁)経済を立て直そうとしましたが、ちょうど世界恐慌と重なり、深刻な【昭和恐慌】になりました。アメリカ向けの生糸の輸出が激減して繭の値段が暴落し、米の値段も下がって、特に農村が苦しみました。\n人々の間に政党や財閥への不満が高まるなか、中国東北部(満州)に駐留していた日本の陸軍(【関東軍】)は、満州を日本の勢力下に置けば不況から抜け出せると考えました。1931年9月、奉天郊外の柳条湖で南満州鉄道の線路を爆破し、これを中国側のしわざとして軍事行動を始めました(【満州事変】)。1932年には清の最後の皇帝溥儀を元首とする【満州国】をつくりました。\n国内では、1932年の【五・一五事件】で犬養毅首相が海軍の青年将校らに暗殺され、政党内閣がとだえました。国際連盟はリットン調査団の報告をもとに、満州国を認めない勧告を採択し、日本は1933年に【国際連盟脱退】を通告して、国際的に孤立していきました。\n1936年には陸軍の青年将校らによる【二・二六事件】が起き、その後、軍部の政治への発言力が強まりました。1937年7月、北京郊外の盧溝橋での日中両軍の衝突から【日中戦争】が始まりました。中国では国民党と共産党が再び協力して(第2次国共合作)抵抗し、戦争は長期化しました。日本軍は首都南京を占領した際、捕虜や住民を殺害しました(南京事件)。\n1938年、日本は【国家総動員法】を制定し、議会の承認なしに国民や物資を戦争に動員できるようにしました。',
        key: '昭和恐慌 → 満州事変(1931年)→ 満州国(1932年)→ 国際連盟脱退(1933年)→ 日中戦争(1937年)→ 国家総動員法(1938年)。',
        chain: { title: '世界恐慌から日中戦争へ(日本)', items: [
          ['背景', '世界恐慌 + 金解禁 → 昭和恐慌(1930年)', '生糸・米の値段が暴落し、農村が苦しむ'],
          ['できごと', '満州事変(1931年) → 満州国の建国(1932年)', '関東軍が柳条湖で鉄道を爆破し、軍事行動を始める'],
          ['できごと', '五・一五事件(1932年)で政党内閣がとだえる'],
          ['結果', '国際連盟が満州国を認めず → 日本は国際連盟脱退を通告(1933年)', '国際的な孤立'],
          ['その後', '二・二六事件(1936年) → 日中戦争(1937年) → 国家総動員法(1938年)']] },
        ex: [{ q: '昭和恐慌と満州事変は、どのようにつながっているか説明しよう。', hint: '軍が満州に何を求めたかを考えます。', steps: ['世界恐慌と金解禁が重なり、日本は昭和恐慌になった。', '生糸や米の値段が暴落し、農村をはじめ人々の生活が苦しくなった。', '不況を解決できない政党や財閥に対する不満が高まった。', '関東軍は、満州の資源や土地を手に入れれば不況から抜け出せると考え、満州事変を起こした。'], a: '昭和恐慌で人々の生活が苦しくなり、政党への不満が高まるなか、関東軍は満州を勢力下に置くことで不況を打開しようとして満州事変を起こした。', check: '「不況 → 不満 → 満州に打開策を求める」という因果になっているか確かめます。' }] },
      { h: '第二次世界大戦の始まりと拡大', t: 'ドイツは1938年にオーストリアを併合し、さらにチェコスロヴァキアのズデーテン地方を要求しました。同じ年の【ミュンヘン会談】で、イギリスとフランスは戦争を避けるため、この要求を認めました。相手の要求をある程度認めて衝突を避けようとするこの政策を【宥和政策】といいます。\nしかしドイツは、1939年にチェコスロヴァキアを解体し、さらにポーランドに領土を要求しました。1939年8月、ドイツは対立していたはずのソ連と【独ソ不可侵条約】を結び、世界を驚かせました。そして9月1日、ドイツが【ポーランドに侵攻】すると、イギリス・フランスがドイツに宣戦し、【第二次世界大戦】が始まりました。\nドイツは1940年にフランスを降伏させ、イタリアもドイツ側で参戦しました。イギリスは首相チャーチルのもとで抵抗を続けました。1941年6月、ドイツは不可侵条約を破ってソ連に攻めこみ(独ソ戦)、戦争は東ヨーロッパに広がりました。\n1941年8月、アメリカのローズヴェルトとイギリスのチャーチルは【大西洋憲章】を発表し、領土の不拡大、民族自決、国際的な平和機構の再建など、戦後の世界の原則を示しました。\nドイツの占領地では、ユダヤ人が強制収容所に送られ、約600万人が殺害されたとされます(【ホロコースト】)。',
        key: 'ミュンヘン会談(1938年・宥和政策)→ 独ソ不可侵条約(1939年8月)→ ポーランド侵攻(1939年9月)で第二次世界大戦。',
        ex: [{ q: 'イギリス・フランスの宥和政策は、なぜ戦争を防げなかったと考えられるか説明しよう。', hint: 'ミュンヘン会談の後、ドイツが何をしたかを考えます。', steps: ['ミュンヘン会談で、イギリス・フランスはドイツのズデーテン地方の要求を認めた。', 'これで戦争を避けられると考えたが、ドイツは翌年チェコスロヴァキアを解体した。', 'さらにポーランドに領土を要求し、独ソ不可侵条約でソ連との衝突を避けたうえで侵攻した。', '要求を認めたことが、かえってドイツに「さらに要求しても英仏は戦わない」と思わせた。'], a: '要求を認めればドイツは満足すると考えたが、ドイツはかえって英仏が強く反対しないと見て拡大を続け、チェコスロヴァキア解体、ポーランド侵攻へと進んだから。', check: 'ミュンヘン会談(1938年)→ チェコスロヴァキア解体 → 独ソ不可侵条約 → ポーランド侵攻(1939年)の順になっているか確かめます。' }] },
      { h: '太平洋戦争:日本の南進とアメリカとの開戦', t: '日中戦争が長引くなか、日本は不足する石油・ゴムなどの資源を求めて、東南アジアへの進出(【南進】)を考えるようになりました。ドイツがフランスやオランダを降伏させると、その植民地を手に入れる好機と見たのです。\n1940年9月、日本は北部フランス領インドシナに軍を進め(北部仏印進駐)、同じ月に【日独伊三国同盟】を結びました。1941年4月には、北方の安全を確保するためソ連と【日ソ中立条約】を結びました。\nアメリカとの交渉も行われましたが、1941年7月に日本が南部仏印に進駐すると、アメリカは日本への【石油輸出を全面的に禁止】しました。石油の多くをアメリカからの輸入に頼っていた日本にとって、これは大きな打撃でした。アメリカは、中国やフランス領インドシナからの撤兵などを求め、交渉はまとまりませんでした。\n1941年12月8日、日本はイギリス領マレー半島に上陸し、ハワイの【真珠湾】のアメリカ海軍基地を攻撃して、アメリカ・イギリスに宣戦しました(【太平洋戦争】)。日本は「大東亜共栄圏」をかかげ、欧米の植民地支配からのアジアの解放を主張しました。\nしかし実際の占領地では、日本軍が資源や食料を取り立て、住民を労働に動員しました。植民地の朝鮮や台湾では、日本語の使用や神社参拝を強いる【皇民化政策】が進められ、朝鮮では日本式の氏名に変えさせる創氏改名(1940年)も行われました。1942年6月のミッドウェー海戦で敗れてから、日本は守勢に回りました。',
        key: '南進 → 北部仏印進駐・三国同盟(1940年)→ 南部仏印進駐(1941年7月)→ アメリカの石油禁輸 → 真珠湾攻撃・マレー半島上陸(1941年12月8日)。',
        chain: { title: '日中戦争から太平洋戦争へ', items: [
          ['背景', '日中戦争が長期化し、石油・ゴムなどの資源が不足'],
          ['できごと', '北部仏印進駐・日独伊三国同盟(1940年9月)', 'アメリカとの関係が悪化'],
          ['できごと', '日ソ中立条約(1941年4月) → 南部仏印進駐(1941年7月)'],
          ['結果', 'アメリカが対日石油輸出を全面禁止(1941年8月)', '日米交渉はまとまらない'],
          ['その後', 'マレー半島上陸・真珠湾攻撃(1941年12月8日) → 太平洋戦争']] },
        ex: [{ q: '日本が南部仏印進駐の後、アメリカとの開戦に向かった理由を、石油に注目して説明しよう。', hint: '日本は石油をどこから輸入していたかを考えます。', steps: ['日本は日中戦争を続けるために、大量の石油を必要としていた。', '石油の多くは、アメリカからの輸入に頼っていた。', '南部仏印進駐に対し、アメリカは石油の輸出を全面的に禁止した。', '日本は、石油を確保するにはオランダ領東インドなど南方の資源地帯をおさえるしかないと考え、アメリカ・イギリスとの開戦に踏み切った。'], a: '石油の多くをアメリカに頼っていた日本は、南部仏印進駐への対抗としてアメリカに石油を止められ、南方の資源を武力で確保しようとして開戦に向かった。', check: '「南部仏印進駐 → 石油禁輸 → 南方の資源を求めて開戦」の順になっているか確かめます。' }] },
      { h: '戦争の終わりと、その被害', t: '1943年、ソ連のスターリングラードでドイツ軍が降伏し、同じ年にイタリアが降伏しました。1944年6月、連合国軍がフランスのノルマンディーに上陸し、ドイツは東西からはさまれました。1945年2月の【ヤルタ会談】では、アメリカ・イギリス・ソ連の首脳が戦後の処理を話し合い、ソ連の対日参戦なども密約されました。1945年5月、ドイツは降伏しました。\nアジア・太平洋では、1944年にサイパン島が陥落すると、日本本土への空襲が激しくなりました。1945年3月の東京大空襲では、一晩で約10万人が亡くなったとされます。1945年3月末からは【沖縄戦】が行われ、住民を巻きこんだ地上戦で、多くの沖縄の人々が犠牲になりました。\n1945年7月、連合国は日本に無条件降伏を求める【ポツダム宣言】を発表しました。8月6日に【広島】、8月9日に【長崎】に原子爆弾が投下され、8月8日にはソ連が日ソ中立条約を破って日本に宣戦しました。日本は8月14日にポツダム宣言を受け入れ、8月15日に天皇がラジオで国民に終戦を伝え、9月2日に降伏文書に署名しました。\n第二次世界大戦は、軍人だけでなく、空襲や地上戦、強制労働、虐殺などで、非常に多くの民間人が犠牲になった戦争でした。日本の侵略と植民地支配によって、中国や東南アジア、朝鮮の人々にも大きな被害が出ました。\nこの反省から、1945年10月、戦争を防ぐための新しい国際機関として【国際連合】が発足しました。',
        key: 'ドイツ降伏(1945年5月)→ 沖縄戦 → ポツダム宣言(7月)→ 広島(8月6日)・ソ連参戦(8月8日)・長崎(8月9日)→ 受諾(8月14日)・終戦の放送(8月15日)。',
        ex: [{ q: '1945年8月の次のできごとを、起きた順に並べよう。ア 長崎に原子爆弾が投下される イ ソ連が日本に宣戦する ウ ポツダム宣言の受諾 エ 広島に原子爆弾が投下される', hint: '日付は 6日・8日・9日・14日 です。', steps: ['8月6日:広島に原子爆弾が投下された。→ エ', '8月8日:ソ連が日ソ中立条約を破って日本に宣戦した。→ イ', '8月9日:長崎に原子爆弾が投下された。→ ア', '8月14日:日本がポツダム宣言を受け入れた(15日に国民に放送)。→ ウ'], a: 'エ → イ → ア → ウ', check: '6日 → 8日 → 9日 → 14日 と、日付が小さい順になっているか確かめます。' }] },
      { h: 'もっと深く:国際協調はどこで崩れたのか──1920年代から1930年代へ', t: '第二次世界大戦は、突然始まったわけではありません。1920年代に築かれた【国際協調】が、1930年代に一つずつ崩れていった結果でした。\n1920年代後半は、比較的安定した時代でした。アメリカの資金でドイツの賠償金支払いを助けるドーズ案(1924年)、ドイツと周辺国が国境を保障し合ったロカルノ条約(1925年)、ドイツの国際連盟加盟(1926年)、そして戦争を国際紛争の解決手段としないと約束した【不戦条約】(1928年)が結ばれました。日本も、幣原喜重郎外相のもとで協調外交を進めていました。\nこの協調を支えていたのは、アメリカを中心とするお金の流れでした。だから【世界恐慌】(1929年)でそのお金の流れが止まると、各国は自国を守るブロック経済に走り、協調の土台が失われたのです。\n1930年代には、協調体制への挑戦が続きます。1931年に満州事変、1933年に日本とドイツが国際連盟を脱退、1935年にドイツが再軍備を宣言し、イタリアがエチオピアに侵攻、1936年にドイツがラインラントに軍を進めました。連盟はイタリアに経済制裁を科しましたが、石油を禁輸の対象にしないなど不徹底で、侵略を止められませんでした。\nこうして、「ルールを破っても止められない」という経験が積み重なり、各国は軍事力にたよるようになりました。第二次世界大戦を学ぶときは、「いつ・どの段階で引き返せなくなったのか」という視点で年表を見ると、理解が深まります。',
        key: '1920年代の協調(ドーズ案・ロカルノ条約・不戦条約)は、アメリカ中心のお金の流れに支えられていた。世界恐慌でそれが止まり、1930年代に侵略を止められない状態が積み重なった。' },
      { h: '入試ではこう出る:1931〜1941年の年代整序と因果', t: 'この単元の最頻出は、【1931年から1941年までの年代整序】です。日本・ドイツ・国際関係のできごとが混ざって出るので、年ごとに整理しておきましょう。\n1931年 満州事変。1932年 満州国の建国、五・一五事件。1933年 日本が国際連盟脱退を通告、ドイツでヒトラー政権成立。1936年 二・二六事件。1937年 盧溝橋事件から【日中戦争】。1938年 【国家総動員法】。1939年 【独ソ不可侵条約】、ドイツのポーランド侵攻で第二次世界大戦。1940年 北部仏印進駐、【日独伊三国同盟】。1941年4月 【日ソ中立条約】、6月 独ソ戦、7月 南部仏印進駐、8月 アメリカの対日石油輸出禁止、12月8日 マレー半島上陸と真珠湾攻撃。\nなぜこの順番になるのか、因果で結ぶと忘れにくくなります。たとえば、日中戦争の長期化→資源を求めて南進→仏印進駐→アメリカの経済制裁→開戦、という鎖です。日ソ中立条約は、北(ソ連)の安全を確保して南進に集中するために結ばれました。\nひっかけでは、「日独伊三国同盟の後に日中戦争が始まった」(逆)、「独ソ戦の後に独ソ不可侵条約」(逆)などがよく出ます。\n時間配分のコツは、まず4つのできごとを「1930年代前半・後半・1940年・1941年」の4つの箱に分けることです。同じ年の中の順番は、因果関係で決めます。',
        key: '日中戦争の長期化 → 南進 → 仏印進駐 → アメリカの石油禁輸 → 開戦。日ソ中立条約は「北を固めて南へ」のため。',
        ex: [
          { q: '次のできごとを古い順に並べよう。ア 日独伊三国同盟 イ 国家総動員法の制定 ウ 日ソ中立条約 エ 二・二六事件', hint: '「1930年代後半」「1940年」「1941年」の箱に分けます。', steps: ['エ 二・二六事件は1936年。', 'イ 国家総動員法は、日中戦争が始まった翌年の1938年。', 'ア 日独伊三国同盟は1940年。', 'ウ 日ソ中立条約は1941年4月。'], a: 'エ → イ → ア → ウ', check: '「日中戦争の長期化→総動員→同盟で国際的に孤立を補う→北を固めて南進」という流れと合っているか確かめます。' },
          { q: '1940年に結ばれた日独伊三国同盟が、日米関係を悪化させた理由を説明しよう。', hint: 'アメリカがヨーロッパの戦争でどちらを支援していたかを考えます。', steps: ['1940年当時、ヨーロッパではドイツがイギリスと戦っており、アメリカはイギリスを支援していた。', '三国同盟は、アメリカの参戦をけん制する(アメリカを仮想敵とする)性格をもっていた。', 'さらに日本は同じ時期に北部仏印に進駐し、東南アジアへ進出し始めた。', 'アメリカは日本をドイツと結んだ敵対的な国と見て、屑鉄の輸出禁止などで経済的な圧力を強めた。'], a: 'アメリカがイギリスを支援していたのに対し、三国同盟はイギリスと戦うドイツと日本が結び、アメリカをけん制するものだったから。同じ時期の北部仏印進駐とあわせ、アメリカは日本を敵対的と見なし、屑鉄の輸出禁止などの経済的な圧力を強めた。', check: 'ヨーロッパの戦争とアジアの動きの両方が結びつけられているか確かめます。' }
        ] }
    ],
    drill: [
      { lv: 1, q: '1928年に結ばれた、国際紛争を解決する手段として戦争に訴えないことを約束した条約は何?', a: '不戦条約(ケロッグ=ブリアン条約)', exp: 'アメリカのケロッグ国務長官とフランスのブリアン外相の提唱で結ばれ、日本も調印しました。\nただし、違反した国への制裁の規定がなく、満州事変などの侵略を止めることはできませんでした。日本国憲法第9条の考え方の源流の一つともいわれます。' },
      { lv: 1, q: '満州事変について調査するため、国際連盟が派遣した調査団を何という?', a: 'リットン調査団', exp: 'リットン調査団の報告書は、満州事変を日本の自衛のための行動とは認めず、満州国も認めませんでした。\nこの報告にもとづく勧告が連盟総会で採択されると、日本は1933年に国際連盟からの脱退を通告しました。' },
      { lv: 1, q: '1938年に制定された、政府が議会の承認なしに人や物資を戦争のために動員できるようにした法律は何?', a: '国家総動員法', exp: '日中戦争の長期化に対応するため、近衛文麿内閣のもとで制定されました。\nこれにより、政府は勅令によって労働力・物資・物価などを統制できるようになりました。議会の役割が小さくなったことが重要なポイントです。' },
      { lv: 2, q: '1939年8月、ドイツとソ連が不可侵条約を結んだことは、世界に大きな衝撃を与えた。なぜ衝撃的だったのか、また、この条約の直後に何が起きたか説明しよう。', a: '反共産主義をかかげるナチス・ドイツと、共産主義国家のソ連という、敵対していたはずの2国が手を結んだから。条約の直後の1939年9月、ドイツがポーランドに侵攻し、イギリス・フランスがドイツに宣戦して第二次世界大戦が始まった。', exp: 'ドイツは東側(ソ連)の安全を確保したうえで、ポーランドに侵攻しました。条約には、ポーランドなどを独ソで分け合う秘密の取り決めもありました。\n日本では、ドイツと防共協定を結んでソ連に対抗していたため、当時の平沼騏一郎内閣は「欧州の天地は複雑怪奇」と述べて総辞職しました。\n採点のポイントは、①反共のドイツと共産のソ連が結んだ意外さ、②ポーランド侵攻と大戦の開始、の2点です。' },
      { lv: 2, q: '1935年、イタリアがエチオピアに侵攻したとき、国際連盟が侵略を止められなかった理由を説明しよう。', a: '連盟はイタリアに経済制裁を科したが、戦争の継続に欠かせない石油が禁輸の対象に含まれないなど制裁が不徹底だったうえ、アメリカなど連盟外の国との貿易も続いたため、効果が上がらなかったから。', exp: '国際連盟は軍事的な制裁の手段をもたず、経済制裁にたよるしかありませんでした。\nしかもその経済制裁も、各国の利害から不徹底に終わりました。イタリアは1936年にエチオピアを併合し、1937年には連盟を脱退します。\n採点のポイントは、①経済制裁の不徹底(石油が対象外など)、②連盟外の国の存在(アメリカ不参加)、の2点です。連盟の構造的な弱点と結びつけて書きましょう。' },
      { lv: 3, q: '1920年代の国際協調が1930年代に崩れた理由を、経済と政治の両面から150字程度で説明しよう。', a: '経済面では、1920年代の協調はアメリカの資金がドイツなどに流れることで支えられていたが、世界恐慌でその流れが止まり、各国がブロック経済をとって対立を深めた。政治面では、恐慌の打撃を受けた日本・ドイツ・イタリアが対外膨張で活路を求め、国際連盟を脱退するなどして協調体制に挑戦したが、連盟は軍事制裁の手段をもたず、侵略を止められなかった。', exp: '論述では、「経済」と「政治」の2つの面を分けて書くと、読み手に伝わりやすくなります。\n経済面のキーワードは「アメリカ資本」「世界恐慌」「ブロック経済」、政治面のキーワードは「対外膨張」「連盟脱退」「制裁の限界」です。\n採点のポイントは、①協調を支えていたしくみ(アメリカの資金)、②恐慌によるその崩壊、③日独伊の挑戦、④連盟の限界、の4点です。具体例(満州事変・エチオピア侵攻など)を1つ入れると説得力が増します。' },
      { lv: 3, q: '太平洋戦争中に日本がかかげた「大東亜共栄圏」の理念と、占領地での支配の実態を比べて説明しよう。', a: '理念としては、欧米の植民地支配からアジアを解放し、日本を中心にアジアの国々が共に栄えることをかかげた。しかし実態は、石油やゴムなどの資源を確保するための軍政が中心で、住民を労働力として動員したり、日本語教育や神社参拝を強制したりした。そのため、各地で日本への反発や抵抗運動が起こった。', exp: 'このテーマは、「かかげた理念」と「実際に行われたこと」を比べる、典型的な論述の型です。\n東南アジアでは、日本の占領を最初は欧米からの解放として歓迎した人々もいましたが、きびしい支配の中で抗日運動が広がりました。フィリピンの抗日ゲリラや、ベトナム独立同盟(ベトミン)などがその例です。\n採点のポイントは、①理念(解放・共存共栄)、②実態(資源確保・動員・同化の強制)、③現地の反発・抵抗、の3点です。理念と実態の「ずれ」をはっきり示しましょう。' }
    ],
    faq: [
      ['ファシズムと軍国主義はどうちがうの?', 'ファシズムは、一つの政党と指導者が国民を統制する政治体制をさし、イタリアのファシスト党やドイツのナチ党が典型です。\n日本の場合、一つの政党が独裁したわけではなく、軍部が政治の主導権をにぎり、国民を戦争に動員していきました。そのため「軍国主義」とよぶことも多く、ファシズムと同じといえるかどうかは研究者の間でも議論があります。'],
      ['なぜ日本は、アメリカと戦えば不利だと分かっていたのに開戦したの?', '日本の指導者の多くも、アメリカとの国力の差が大きいことは理解していました。\nしかし、石油を止められたままでは日中戦争も続けられず、中国からの撤兵などのアメリカの要求も受け入れられないとして、短期決戦に望みをかけて開戦を選びました。'],
      ['世界恐慌のとき、日本は他国より早く不況から抜け出したって本当?', '1931年末に金の輸出を再び禁止すると円の価値が下がり(円安)、日本の綿織物などの輸出がのびました。軍需産業への支出もふえ、日本は比較的早く恐慌から回復しました。\nただし、日本製品が安く大量に輸出されたことに、ブロック経済をとるイギリスなどは強く反発し、国際的な対立が深まりました。'],
      ['「太平洋戦争」「アジア・太平洋戦争」「大東亜戦争」は何がちがうの?', 'どれも、1941年12月に始まった日本と連合国の戦争を指すよび名ですが、どこに注目するかがちがいます。\n「大東亜戦争」は、開戦当時の日本政府が決めた正式なよび名です。戦後、占領期に公文書で使うことが禁じられ、代わりに「太平洋戦争」が広く使われるようになりました。\nしかし「太平洋戦争」だと、アメリカとの戦いばかりが目立ち、中国や東南アジアでの戦争が見えにくくなります。そこで近年は、それらを含めて「アジア・太平洋戦争」とよぶことも増えています。よび名の背景にある「歴史の見方」のちがいに注目しましょう。']
    ],
    terms: [['世界恐慌', '1929年、ニューヨークの株価暴落から世界中に広がった大不況'], ['ニューディール', 'フランクリン=ローズヴェルトが進めた、政府が積極的に経済に関わる恐慌対策'], ['ブロック経済', '本国と植民地で経済圏をつくり、他国の商品をしめ出す政策'], ['ファシズム', '個人の自由や議会政治を否定し、一党と指導者が国民を統制して対外膨張をはかる政治'], ['満州事変', '1931年、関東軍が柳条湖事件を起こして始めた中国東北部での軍事行動'], ['宥和政策', '相手の要求をある程度認めて衝突を避けようとする政策。ミュンヘン会談が代表例'], ['大西洋憲章', '1941年、ローズヴェルトとチャーチルが示した戦後の世界の原則'], ['ポツダム宣言', '1945年7月、連合国が日本に無条件降伏を求めた宣言']],
    miss: ['満州事変(1931年)と日中戦争(1937年)を混同する。柳条湖事件 → 満州事変、盧溝橋事件 → 日中戦争と、事件の名前とセットで覚えます。', 'ナチ党がクーデタで政権をとったと思う。選挙で第一党になり、首相となってから独裁を進めたことが重要です。', '第二次世界大戦の始まりを真珠湾攻撃(1941年)と答える。ヨーロッパではドイツのポーランド侵攻(1939年)で始まり、太平洋戦争はそれに加わる形で1941年に始まりました。', 'ソ連の対日参戦を8月15日の後と思う。正しくは8月8日で、広島(6日)と長崎(9日)の間です。'],
    sum: ['世界恐慌(1929年)に対し、アメリカはニューディール、イギリス・フランスはブロック経済で対応した。', '植民地の少ないドイツ・イタリア・日本では対外膨張の動きが強まり、ドイツではナチ党が選挙を通じて独裁体制をつくった。', '日本は満州事変・国際連盟脱退で孤立し、1937年に日中戦争が始まった。', 'ドイツのポーランド侵攻(1939年)で第二次世界大戦が始まり、日本の南進とアメリカの石油禁輸を経て1941年に太平洋戦争が始まった。', '1945年、ドイツ・日本が降伏した。多くの民間人が犠牲となった反省から国際連合がつくられた。'],
    next: '次は「冷戦と脱植民地化(hs_reisen)」です。戦争が終わった世界が、アメリカとソ連の対立と、アジア・アフリカの独立という2つの大きな動きの中で、どう再編されたかを学びます。'
  };

  // ===== グローバル化と私たち =====
  L.hs_reisen = {
    goal: '冷戦がなぜ始まり、ヨーロッパとアジアでどのように展開したかを説明でき、アジア・アフリカの脱植民地化と、占領・独立・高度経済成長という戦後日本の歩みを、冷戦と結びつけて説明できるようになる。',
    intro: '第二次世界大戦で一緒にドイツや日本と戦ったアメリカとソ連。戦争が終わると、この2つの大国は、世界をどうつくりなおすかをめぐって激しく対立しました。直接は戦わない「冷たい戦争」でしたが、アジアでは朝鮮戦争やベトナム戦争という「熱い戦争」が起きました。戦後の日本の憲法、自衛隊、日米安保条約、そして経済成長も、この冷戦の流れの中で形づくられています。',
    pre: '第二次世界大戦は1945年に終わり、同じ年の10月に【国際連合】が発足しました。\n【資本主義】は、個人や企業が自由に経済活動を行い、市場での競争を通じて生産や価格が決まるしくみです。【社会主義】は、土地や工場などを国や社会のものとし、計画にもとづいて生産を行うしくみです。アメリカは資本主義、ソ連は社会主義の中心でした。\n第二次世界大戦の末期、ソ連軍は東ヨーロッパを、アメリカ軍は西ヨーロッパや日本を、それぞれ占領・解放していました。\n朝鮮半島は、日本の植民地支配から解放されたあと、北緯38度線を境に、北をソ連、南をアメリカが占領しました。',
    secs: [
      { h: '戦後の国際秩序:国際連合とブレトン=ウッズ体制', t: '第二次世界大戦の反省から、連合国は二度と世界大戦を起こさないためのしくみを考えました。国際連盟がアメリカの不参加や、侵略を止める力の弱さのために失敗したからです。\n1945年10月に発足した【国際連合】では、【安全保障理事会】に、侵略に対して経済制裁だけでなく軍事的な措置もとれる強い権限を与えました。アメリカ・イギリス・フランス・ソ連・中国の5か国が【常任理事国】となり、重要なことがらには1か国でも反対すれば決まらない【拒否権】をもちました。\n経済では、世界恐慌のときのブロック経済が戦争の原因の一つになった反省から、自由な貿易を守るしくみがつくられました。【国際通貨基金(IMF)】と国際復興開発銀行(世界銀行)が設立され、アメリカのドルを中心に各国の通貨の交換比率を固定しました。1947年には関税と貿易に関する一般協定(GATT)が結ばれました。この体制を、会議が開かれた地名から【ブレトン=ウッズ体制】といいます。\nまた、ドイツではニュルンベルク、日本では東京で【国際軍事裁判】が開かれ、戦争の指導者が裁かれました。\nしかし、常任理事国の拒否権は、アメリカとソ連が対立するようになると、安全保障理事会がなかなか決定できない原因にもなりました。',
        key: '国際連合(1945年):安全保障理事会の常任理事国5か国に拒否権。経済はブレトン=ウッズ体制(IMF・世界銀行・GATT)でブロック経済の反省に立つ。',
        ex: [{ q: '戦後につくられたブレトン=ウッズ体制には、戦前のどのような反省が生かされているか説明しよう。', hint: '世界恐慌のとき、各国が経済でとった政策を思い出しましょう。', steps: ['世界恐慌のとき、イギリス・フランスなどはブロック経済をとり、他国の商品をしめ出した。', 'その結果、市場をしめ出された国々が対外膨張に向かい、戦争の原因の一つになった。', 'そこで戦後は、IMFでドルを中心に通貨の交換比率を安定させ、GATTで関税を下げて自由な貿易を進めることにした。'], a: '世界恐慌のときのブロック経済が国どうしの対立を深め、戦争の原因になったという反省から、通貨を安定させ、自由な貿易を守るしくみをつくった。', check: '「ブロック経済 → 対立 → 戦争」という戦前の流れと、戦後の「自由貿易」とが対比されているか確かめます。' }] },
      { h: '冷戦の始まり:ヨーロッパの分断', t: '戦後、東ヨーロッパの国々では、ソ連の影響のもとで共産党中心の政権が次々にできました。1946年、イギリスの前首相チャーチルは、ヨーロッパの東西の間に「【鉄のカーテン】」がおろされていると演説しました。\n1947年、アメリカ大統領【トルーマン】は、共産主義の広がりを封じこめる政策(【トルーマン=ドクトリン】)を発表し、同じ年に、ヨーロッパの経済復興を援助する【マーシャル=プラン】を打ち出しました。経済が苦しいと共産主義が広がりやすいと考えたからです。ソ連と東ヨーロッパの国々はこの援助を受け入れず、対抗する組織をつくりました。\nこのように、アメリカを中心とする【資本主義(西側)陣営】と、ソ連を中心とする【社会主義(東側)陣営】が、直接の戦争はしないまま激しく対立した状態を【冷戦】(冷たい戦争)といいます。\n対立の最前線はドイツでした。1948〜49年、ソ連は西ベルリンへの交通を断ち切りました(【ベルリン封鎖】)。1949年、ドイツは西の【ドイツ連邦共和国】(西ドイツ)と東の【ドイツ民主共和国】(東ドイツ)に分かれました。同じ年、西側は軍事同盟の【北大西洋条約機構(NATO)】をつくり、東側は1955年に【ワルシャワ条約機構】をつくりました。\nソ連も1949年に原子爆弾の開発に成功し、米ソは核兵器の開発競争を続けました。核兵器による全面戦争の危険が、かえって直接の戦争をおさえる面もありました。',
        key: 'トルーマン=ドクトリン・マーシャル=プラン(1947年)→ ベルリン封鎖(1948〜49年)→ 東西ドイツ・NATO(1949年)。東側はワルシャワ条約機構(1955年)。',
        flow: { title: '冷戦の二つの陣営', cols: 2, head: ['西側(資本主義)', '東側(社会主義)'], rows: [
          [['アメリカ合衆国', 'b', 1, '大統領トルーマン'], ['ソ連', 'r', 1, '指導者スターリン']],
          [['トルーマン=ドクトリン・マーシャル=プラン(1947年)', 'b'], ['コミンフォルム(1947年)・コメコン(1949年)', 'r']],
          [['西ドイツ(1949年)', 'b'], ['東ドイツ(1949年)', 'r']],
          [['NATO(1949年)', 'b'], ['ワルシャワ条約機構(1955年)', 'r']],
          [['日本・韓国など(アジアの西側)', 'b'], ['中華人民共和国・北朝鮮など(アジアの東側)', 'r']]
        ], legend: [['b', '西側(資本主義陣営)'], ['r', '東側(社会主義陣営)']] },
        ex: [{ q: 'アメリカがマーシャル=プランでヨーロッパの経済復興を援助したのは、冷戦とどのように関係しているか説明しよう。', hint: '経済が苦しい国では、どんな考えが広がりやすいとアメリカは考えたかを思い出しましょう。', steps: ['戦後のヨーロッパは戦争で荒れ、経済が苦しかった。', 'アメリカは、生活が苦しいと人々が共産主義を支持しやすくなると考えた。', 'そこで、経済を復興させることで、西ヨーロッパに共産主義が広がるのを防ごうとした。', 'これはトルーマン=ドクトリンの「封じこめ」と同じねらいをもつ政策だった。'], a: '経済の苦しさが共産主義の広がりにつながると考え、西ヨーロッパの経済を立て直して、ソ連の影響が広がるのを防ぐ(封じこめる)ためだった。', check: '「援助=親切」だけでなく、「共産主義の封じこめ」という冷戦のねらいが書かれているか確かめます。' }] },
      { h: 'アジアの冷戦:中国・朝鮮・ベトナム', t: 'ヨーロッパでは「冷たい」対立にとどまった冷戦も、アジアでは実際の戦争になりました。\n中国では、日本の降伏後、国民党と共産党の内戦が再び始まりました。共産党が勝ち、1949年10月、【毛沢東】を主席とする【中華人民共和国】が成立しました。国民党の蔣介石は【台湾】に逃れ、中華民国政府を維持しました。\n朝鮮半島では、1948年に南に【大韓民国】(韓国)、北に【朝鮮民主主義人民共和国】(北朝鮮)が成立しました。1950年、北朝鮮が韓国に攻めこみ、【朝鮮戦争】が始まりました。アメリカ軍を中心とする国連軍が韓国を、中国の人民義勇軍が北朝鮮を支援し、1953年に休戦協定が結ばれました。半島の分断は今も続いています。\nベトナムでは、1945年に【ホー=チ=ミン】がベトナム民主共和国の独立を宣言しましたが、もどってきたフランスとの戦争(インドシナ戦争)になりました。1954年のジュネーヴ休戦協定でフランスは撤退しましたが、ベトナムは北緯17度線で南北に分かれました。その後、共産主義の広がりをおそれたアメリカが南ベトナムを支援し、1965年から北ベトナムへの爆撃(北爆)を始めて、【ベトナム戦争】が本格化しました。\nアメリカは1973年に撤退し、1975年に南ベトナムの首都サイゴンが陥落して、翌1976年に南北が統一されました。ベトナム戦争は、アメリカ国内や世界で大きな反戦運動を引き起こしました。',
        key: '中華人民共和国(1949年)、朝鮮戦争(1950〜53年・休戦)、ベトナム戦争(北爆1965年〜、統一1976年)。アジアでは冷戦が「熱い戦争」になった。',
        ex: [{ q: '冷戦が「冷たい戦争」とよばれるのに、アジアでは朝鮮戦争やベトナム戦争が起きたのはなぜか説明しよう。', hint: '米ソが「直接」戦ったかどうかに注目します。', steps: ['冷戦は、アメリカとソ連が直接戦争をしないまま対立したことから「冷たい戦争」とよばれる。', 'しかしアジアでは、国が南北に分かれ、それぞれを東側・西側が支援した。', '朝鮮戦争では、アメリカ中心の国連軍と中国の義勇軍が戦い、ベトナム戦争ではアメリカ軍が直接戦った。', 'つまり、米ソが直接は戦わなくても、その対立がアジアの分断国家での戦争として表れた。'], a: '米ソは直接戦わなかったが、アジアでは国が東西の陣営に分かれ、それぞれを大国が支援したため、分断された国の内部での戦争(朝鮮戦争・ベトナム戦争)として冷戦の対立が表れたから。', check: '「米ソは直接戦っていない」と「代わりの戦争が起きた」の2点が書かれているか確かめます。' }] },
      { h: '脱植民地化と第三世界', t: '第二次世界大戦で、ヨーロッパの国々は大きく力を落としました。また、戦争中に植民地の人々も動員されたことで、独立を求める声はいっそう強まりました。こうして、植民地が独立していく【脱植民地化】が進みました。\nアジアでは、1945年にインドネシアがスカルノのもとで独立を宣言し(オランダは1949年に承認)、1946年にフィリピン、1947年にインドとパキスタンが分かれて独立しました。インドの初代首相は【ネルー】です。インドとパキスタンの分離独立のとき、宗教のちがいから大規模な衝突が起き、多くの難民が生まれました。\n西アジアでは、1948年にユダヤ人の国家【イスラエル】が建国され、反対するアラブ諸国との間で第1次中東戦争が起きました。土地を追われた多くのパレスチナ人が難民となり、【パレスチナ問題】は今も続いています。1956年には、エジプトのナセル大統領がスエズ運河の国有化を宣言しました。\n1955年、インドネシアのバンドンで【アジア・アフリカ会議】が開かれ、29か国が参加して、主権と領土の尊重、内政不干渉、平和共存などをうたう【平和十原則】を発表しました。東西どちらの陣営にも属さない国々は【第三世界】とよばれ、1961年には非同盟諸国首脳会議も開かれました。\n1960年には、アフリカで17か国が独立し、「【アフリカの年】」とよばれました。しかし、独立後も、植民地時代に引かれた国境線をめぐる紛争や、先進国との経済格差(【南北問題】)などの課題が残りました。',
        key: 'インド・パキスタンの独立(1947年)、イスラエル建国(1948年)、アジア・アフリカ会議(1955年・平和十原則)、アフリカの年(1960年)。',
        ex: [{ q: '第二次世界大戦の後に、アジアやアフリカで独立が相次いだ理由を2つ挙げよう。', hint: '「ヨーロッパ側の変化」と「植民地側の変化」に分けます。', steps: ['ヨーロッパ側:イギリス・フランス・オランダなどは戦争で国力を大きく落とし、植民地を支配し続ける力が弱まった。', '植民地側:戦争中に兵士や労働者として動員された人々の間で、独立を求める民族運動が強まった。', 'また、大西洋憲章や国際連合憲章で、民族自決の考えが国際的に認められていった。'], a: 'ヨーロッパの国々が戦争で国力を落とし、植民地支配を続ける力が弱まったことと、戦争に動員された植民地の人々の間で独立を求める民族運動が強まったこと。', check: '「支配する側」と「支配される側」の両方から理由を挙げているか確かめます。' }] },
      { h: '占領下の日本と独立の回復', t: '敗戦後の日本は、マッカーサーを最高司令官とする【GHQ】(連合国軍最高司令官総司令部)に占領されました。GHQが日本政府に指令を出し、日本政府が政治を行う間接統治のしくみでした。\n占領の初めの方針は、日本が二度と戦争を起こさないための【非軍事化】と【民主化】でした。軍隊は解散され、【財閥解体】で大企業の独占を解き、【農地改革】で地主の土地を小作人に分け、労働組合法などで労働者の権利を保障しました。1945年の選挙法改正で、満20歳以上の【男女】に選挙権が与えられ、女性参政権が初めて実現しました。そして【日本国憲法】が1946年11月3日に公布、1947年5月3日に施行され、国民主権・基本的人権の尊重・平和主義を原則としました。\nところが、冷戦が深まり、中国で共産党が優勢になると、アメリカは日本を【アジアにおける西側の拠点】として経済的に立て直す方針に転じました。民主化よりも経済の復興が重視されるようになり、この変化は「逆コース」ともよばれます。\n1950年に【朝鮮戦争】が始まると、アメリカ軍の物資の注文(【特需】)で日本の経済は急速に回復しました。また、GHQの指令で【警察予備隊】がつくられ、これがのちに保安隊、1954年には【自衛隊】になりました。\n1951年、日本は【サンフランシスコ平和条約】に調印し、翌1952年に独立を回復しました。ソ連などは調印せず、中華人民共和国も中華民国も会議に招かれませんでした。同じ日に【日米安全保障条約】が結ばれ、独立後もアメリカ軍が日本に駐留することになりました。沖縄や小笠原諸島は、引き続きアメリカの統治下に置かれました。',
        key: '占領初期=非軍事化・民主化(財閥解体・農地改革・女性参政権・日本国憲法)→ 冷戦で経済復興重視へ → 朝鮮特需・警察予備隊(1950年)→ サンフランシスコ平和条約・日米安保条約(1951年調印)。',
        chain: { title: '冷戦が変えた日本の占領政策', items: [
          ['背景', '敗戦(1945年) → GHQによる占領', '初めは非軍事化と民主化が中心'],
          ['できごと', '財閥解体・農地改革・女性参政権・日本国憲法(1946年公布・1947年施行)'],
          ['できごと', '冷戦の深まり、中国で共産党が優勢に', 'アメリカは日本を西側の拠点として経済復興させる方針へ'],
          ['結果', '朝鮮戦争(1950年)の特需で経済が回復 / 警察予備隊の創設'],
          ['その後', 'サンフランシスコ平和条約と日米安全保障条約(1951年調印、1952年発効)', '西側の一員として独立を回復。沖縄はアメリカの統治下に']] },
        ex: [{ q: '朝鮮戦争は、日本にどのような影響を与えたか。経済と安全保障の2つの面から説明しよう。', hint: '「特需」と「警察予備隊」がキーワードです。', steps: ['経済の面:アメリカ軍が日本で大量の物資を注文した(特需)。', 'そのため、日本の工業生産がのび、戦後の経済が急速に回復した。', '安全保障の面:在日アメリカ軍が朝鮮半島に出動したため、日本の治安維持のためにGHQの指令で警察予備隊がつくられた。', '警察予備隊は保安隊を経て、1954年に自衛隊になった。'], a: '経済の面では、アメリカ軍からの大量の注文(特需)で日本の経済が回復した。安全保障の面では、警察予備隊がつくられ、のちの自衛隊につながった。', check: '経済と安全保障の両方について、1つずつ具体的に書かれているか確かめます。' }] },
      { h: '55年体制・高度経済成長と、近隣諸国との関係', t: '独立後の日本では、1955年に保守政党が合同して【自由民主党】ができ、これに社会党が野党第一党として対抗する体制が長く続きました。これを【55年体制】といいます。\n1956年、ソ連と【日ソ共同宣言】を結んで国交を回復すると、それまで安全保障理事会で反対していたソ連が賛成に回り、日本は【国際連合への加盟】を実現しました。1960年には日米安全保障条約が改定され、反対する大規模な運動(安保闘争)が起きました。\n経済は、1950年代半ばから1973年ごろまで、年平均で約10%の成長を続けました。これを【高度経済成長】といいます。テレビ・洗濯機・冷蔵庫などの家庭電化製品が広まり、1964年には【東海道新幹線】が開通し、【東京オリンピック】が開かれました。一方で、工場の排水や排煙による【公害】が深刻になり、水俣病などの被害が出ました。\n近隣の国々との関係では、1965年に【日韓基本条約】を結んで韓国と国交を正常化しました。1972年には【沖縄】がアメリカから日本に返還されましたが、多くのアメリカ軍基地が残りました。同じ1972年、田中角栄首相が中国を訪れて【日中共同声明】を出し、中華人民共和国と国交を正常化しました。1978年には日中平和友好条約が結ばれました。\nこのように、戦後日本の歩みは、冷戦の中でアメリカとの同盟を軸にしながら、近隣諸国との戦後処理を一つずつ進めていく過程でもありました。',
        key: '日ソ共同宣言 → 国連加盟(1956年)。高度経済成長(1950年代半ば〜1973年)。日韓基本条約(1965年)、沖縄返還・日中共同声明(1972年)。',
        ex: [{ q: '日本が国際連合に加盟できたのが、独立回復(1952年)の直後ではなく1956年だったのはなぜか説明しよう。', hint: '安全保障理事会の「拒否権」を思い出しましょう。', steps: ['国際連合に加盟するには、安全保障理事会の勧告が必要で、常任理事国は拒否権をもっていた。', 'ソ連はサンフランシスコ平和条約に調印しておらず、日本とは国交がなかった。', 'そのため、ソ連が拒否権を使い、日本の加盟に反対していた。', '1956年の日ソ共同宣言で国交が回復すると、ソ連が反対しなくなり、日本は国連に加盟できた。'], a: 'ソ連とは国交がなく、安全保障理事会の常任理事国であるソ連が日本の加盟に反対していたから。1956年の日ソ共同宣言で国交が回復し、ソ連が支持に回って加盟が実現した。', check: '「拒否権」と「日ソ共同宣言」の2つが因果でつながっているか確かめます。' }] },
      { h: 'もっと深く:占領政策はなぜ「転換」したのか', t: '日本の占領政策は、最初から最後まで同じだったわけではありません。冷戦の深まりとともに、大きく方向を変えました。この変化を、のちに「【逆コース】」とよぶことがあります。\n占領の初めの目標は、【非軍事化】と【民主化】でした。軍隊の解体、戦争指導者の処罰と公職追放に加え、財閥解体、農地改革、労働組合の育成(労働三法)、教育基本法の制定、日本国憲法の制定などが進められました。日本が二度と戦争を起こさない国にすることが、アメリカの主な関心だったのです。\nところが、1947年ごろから米ソの対立が深まり、中国では共産党が優勢になっていきます。アメリカにとって、アジアで頼りになる友好国が必要になりました。1948年には、アメリカの陸軍長官が、日本を共産主義に対する「防壁」にすると演説しています。\nこうして目標は、「弱い日本」から「経済的に自立した、西側の一員としての日本」へと変わりました。1948年の【経済安定九原則】、1949年の【ドッジ=ライン】(1ドル=360円の単一為替レートの設定など)で経済の立て直しが進められます。一方で、労働運動や共産党員に対する締めつけ(レッドパージ)が行われ、戦争指導者などの公職追放は解除されていきました。\n1950年に朝鮮戦争が始まると、警察予備隊がつくられ、のちの自衛隊につながります。占領政策の転換は、日本の戦後のかたちが、国内の事情だけでなく冷戦という国際関係によって決まったことを示しています。',
        key: '占領政策は「非軍事化・民主化」から、冷戦の深まりとともに「経済の自立と西側の一員化」へ転換した。ドッジ=ライン・レッドパージ・警察予備隊がその表れ。' },
      { h: '入試ではこう出る:東西の「対になる」できごとと講和の形', t: '冷戦の初期は、西側の動きに東側がこたえる(またはその逆)という【対になる】できごとが多いので、ペアで覚えると整理しやすくなります。\n①1947年、アメリカの【トルーマン=ドクトリン】(共産主義の封じこめ)と【マーシャル=プラン】(ヨーロッパ経済復興援助) ↔ ソ連側の【コミンフォルム】(共産党の情報交換機関)。②1948年、西側の占領地区での通貨改革 ↔ ソ連の【ベルリン封鎖】(1948〜49年)。③1949年、西側の【NATO】 ↔ 1955年、東側の【ワルシャワ条約機構】(西ドイツのNATO加盟に対抗)。④マーシャル=プラン ↔ 1949年、東側の経済協力機構【コメコン】。\nひっかけの定番は、「ワルシャワ条約機構に対抗してNATOがつくられた」(順番が逆)や、「ベルリンの壁は1949年に築かれた」(正しくは1961年)などです。\n日本では、【サンフランシスコ平和条約】(1951年調印、1952年発効)の講和の形がよく問われます。この講和は、ソ連などが調印せず、中国の代表(中華人民共和国・中華民国)はどちらも会議に招かれず、インドなどは参加しなかったため、すべての交戦国との講和ではない【単独講和(片面講和)】とよばれました。同じ日に【日米安全保障条約】が結ばれ、日本は西側陣営の一員として独立を回復しました。\n論述では、「なぜ全面講和にならなかったか」を冷戦と結びつけて書くのが型です。',
        key: 'トルーマン=ドクトリン/マーシャル=プラン↔コミンフォルム、通貨改革↔ベルリン封鎖、NATO(1949)↔ワルシャワ条約機構(1955)。サンフランシスコ平和条約は単独講和。',
        ex: [
          { q: '次の組み合わせのうち、「西側の動き」と、それに対抗した「東側の動き」として正しいものをすべて選ぼう。\nア マーシャル=プラン ― コメコン\nイ NATO ― ワルシャワ条約機構\nウ 西側占領地区の通貨改革 ― ベルリンの壁の建設(1949年)\nエ トルーマン=ドクトリン ― コミンフォルム', hint: 'ウは、年と東側の対応の両方を確かめます。', steps: ['ア:マーシャル=プランに対抗して、東側は1949年にコメコンをつくった。正しい。', 'イ:NATO(1949年)に対し、西ドイツのNATO加盟に対抗して1955年にワルシャワ条約機構ができた。正しい。', 'ウ:通貨改革に対抗したのはベルリン封鎖(1948〜49年)。ベルリンの壁は1961年。誤り。', 'エ:封じこめ政策に対し、ソ連は1947年にコミンフォルムをつくった。正しい。'], a: 'ア・イ・エ', check: 'ウを「西側占領地区の通貨改革 ― ベルリン封鎖」に直すと正しくなることを確かめます。' },
          { q: 'サンフランシスコ平和条約による講和が「単独講和(片面講和)」とよばれる理由を、冷戦と結びつけて説明しよう。', hint: '会議に参加したが調印しなかった国、招かれなかった国、参加しなかった国を分けて考えます。', steps: ['講和会議にはソ連なども出席したが、条約に調印しなかった。', '中国の代表は、中華人民共和国と中華民国のどちらを招くかで米英の意見が分かれ、どちらも招かれなかった。', 'インドなども会議に参加しなかった。', 'その結果、アメリカを中心とする西側の国々とだけ講和することになった。冷戦の対立が講和の形を決めたといえる。'], a: 'ソ連などが調印せず、中国の代表も招かれず、インドなども参加しなかったため、すべての交戦国との講和(全面講和)にならず、アメリカを中心とする西側諸国とだけの講和になったから。冷戦で東西が対立していたことが、講和の形に表れた。', check: '「どの国が講和に加わらなかったか」と「その原因としての冷戦」の両方が書けているか確かめます。' }
        ] }
    ],
    drill: [
      { lv: 1, q: '1955年、インドネシアのバンドンで開かれ、平和十原則を採択した会議は何?', a: 'アジア・アフリカ会議(バンドン会議)', exp: 'アジア・アフリカの29か国が集まり、反植民地主義や平和共存をうたいました。\n前年の周恩来とネルーによる平和五原則を発展させたものです。東西どちらにも属さない「第三世界」の国々が、国際政治の中で存在感を示したできごととして重要です。' },
      { lv: 1, q: '1956年、日本とソ連の国交を回復させた文書は何?', a: '日ソ共同宣言', exp: '鳩山一郎内閣のときに調印されました。\nこれでソ連が日本の国際連合加盟に反対しなくなり、同じ1956年に日本は国連に加盟しました。平和条約は結ばれず、北方領土の問題は残されたままです。' },
      { lv: 1, q: 'ドッジ=ラインで定められた、円とドルの単一為替レートは1ドル何円?', a: '360円', exp: '1949年、それまで品目ごとにばらばらだった為替レートを、1ドル=360円の単一レートに定めました。\nこの固定レートは、1971年のドル・ショックまで続き、日本の輸出の拡大を支えました。' },
      { lv: 2, q: '1960年が「アフリカの年」とよばれる理由を説明しよう。', a: 'この年に、アフリカで17か国が一斉に独立したから。', exp: 'フランス領だった西アフリカの国々を中心に、多くの国が独立しました。\nただし、独立後も、植民地時代に引かれた国境が民族の分布と合わないことや、特定の産物にたよるモノカルチャー経済などの問題が残り、内戦や貧困に苦しむ国も多くありました。独立の「その後」にも目を向けましょう。' },
      { lv: 2, q: '1962年のキューバ危機は、その後の米ソ関係にどのような変化をもたらしたか説明しよう。', a: '核戦争の寸前までいった反省から、米ソは直接話し合うための直通電話(ホットライン)を設け、1963年には部分的核実験禁止条約を結ぶなど、緊張を和らげる方向に進んだ。', exp: 'キューバ危機は、ソ連がキューバにミサイル基地を建設しようとしたことから起こり、ソ連がミサイルを撤去して回避されました。\n「核兵器を使えば双方が滅びる」ことを実感した米ソは、対話と軍備管理の道を探るようになります。これが1970年代のデタント(緊張緩和)につながっていきます。\n採点のポイントは、①核戦争の危機の反省、②ホットラインや部分的核実験禁止条約などの具体例、の2点です。' },
      { lv: 3, q: '戦後の農地改革は、日本の社会と経済にどのような影響を与えたか説明しよう。', a: '政府が地主の土地を買い上げて小作人に安く売り渡したため、多くの自作農が生まれ、寄生地主制が解体された。農民の生活が安定して購買力が高まり、国内市場が広がって高度経済成長を支えた。また、自分の土地をもった農民の多くは保守的になり、保守政党の支持基盤となった。', exp: '戦前の農村では、小作人が高い小作料に苦しみ、それが国内市場のせまさや対外膨張の一因になったと考えられていました。\n農地改革は、その構造を変える民主化政策でした。農民が家電製品などを買えるようになったことは、のちの高度経済成長を支える国内需要につながります。\n採点のポイントは、①自作農の創出と寄生地主制の解体、②経済面(購買力・国内市場)、③政治面(保守政党の支持基盤)の3点です。' },
      { lv: 3, q: '1965年に日韓基本条約が結ばれた背景と、その主な内容、残された課題を説明しよう。', a: '背景:ベトナム戦争が激しくなる中で、アメリカは東アジアの西側の国どうしの結びつきを強めるため、日韓の国交正常化を後押しした。内容:韓国政府を朝鮮半島にある唯一の合法的な政府と確認し、国交を開いた。あわせて結ばれた協定で、日本が韓国に経済協力を行い、両国間の請求権の問題は解決されたとした。課題:植民地支配への評価や、個人への補償をめぐる議論が続き、北朝鮮とは国交がないままとなった。', exp: '日韓の国交正常化交渉は1951年から始まりましたが、植民地支配の評価などをめぐって長く難航しました。\n冷戦の中で、アメリカは日本と韓国が協力することを望み、韓国の朴正熙政権も経済発展のために日本の資金を必要としていました。\n採点のポイントは、①冷戦・ベトナム戦争という背景、②韓国政府を唯一の合法政府と確認・経済協力、③残された課題(補償の議論・北朝鮮との国交なし)の3点です。' }
    ],
    faq: [
      ['冷戦はいつ始まったの?はっきりした日付はあるの?', '冷戦は、宣戦布告で始まる戦争ではないので、はっきりした開始の日はありません。\n一般に、1946年の「鉄のカーテン」演説や、1947年のトルーマン=ドクトリン・マーシャル=プランのころから、対立がはっきりしたと説明されます。'],
      ['日本国憲法はGHQがつくったものなの?', 'GHQが作成した草案をもとに日本政府が改正案をつくり、帝国議会で審議・修正されて成立しました。\n議会での審議の中で、生存権の規定が加えられるなど、日本側の意見も反映されています。形式的には大日本帝国憲法の改正の手続きをとりました。'],
      ['高度経済成長はなぜ1973年ごろに終わったの?', '1973年の第4次中東戦争をきっかけに、アラブの産油国が原油価格を大きく引き上げた【石油危機】が起きたからです。\n安い石油に頼って成長してきた日本経済は大きな打撃を受け、翌1974年には戦後初めてのマイナス成長になりました。'],
      ['冷戦の時代に、なぜ核兵器は実際の戦争で使われなかったの?', '米ソがともに大量の核兵器をもつようになると、一方が核で攻撃すれば、相手も核で反撃し、双方が滅びてしまう状態になりました。この「おたがいに攻撃できない」状態で戦争を防ぐ考え方を【核抑止】といいます。\n朝鮮戦争でも、戦争の拡大は避けられました。国連軍司令官のマッカーサーは中国本土への攻撃の拡大を主張しましたが、トルーマン大統領に解任されています。\nただし、核抑止は「たまたまうまくいった」面もあります。キューバ危機のように、核戦争の寸前までいったこともありました。核抑止は平和を保証するものではない、という見方も大切です。']
    ],
    terms: [['冷戦', '第二次世界大戦後、アメリカ中心の西側とソ連中心の東側が、直接の戦争をしないまま対立した状態'], ['マーシャル=プラン', '1947年に発表された、アメリカによるヨーロッパの経済復興援助計画'], ['NATO', '1949年に結成された、アメリカと西ヨーロッパ諸国などの軍事同盟'], ['脱植民地化', '第二次世界大戦後、アジア・アフリカの植民地が次々に独立していったこと'], ['第三世界', '東西どちらの陣営にも属さない、アジア・アフリカなどの国々'], ['特需', '朝鮮戦争の際の、アメリカ軍による日本での大量の物資の注文'], ['55年体制', '1955年から続いた、自由民主党が政権をにぎり、社会党が野党第一党として対抗する体制'], ['高度経済成長', '1950年代半ばから1973年ごろまで続いた、日本の急速な経済成長']],
    miss: ['サンフランシスコ平和条約で、すべての国と講和したと思う。ソ連などは調印せず、中国はどちらの政府も招かれていません。だから日ソ共同宣言(1956年)や日中共同声明(1972年)が必要になりました。', 'NATO(1949年)とワルシャワ条約機構(1955年)の成立年や陣営を逆にする。西側の同盟が先にでき、それに対抗して東側の同盟ができた、と順番の理由で覚えます。', '朝鮮戦争の休戦を「終戦」と思う。1953年に結ばれたのは休戦協定で、平和条約は結ばれていません。', '日本国憲法の公布日と施行日を逆にする。公布は1946年11月3日(現在の文化の日)、施行は1947年5月3日(憲法記念日)です。'],
    sum: ['戦後、国際連合とブレトン=ウッズ体制がつくられ、戦前のブロック経済などの反省が生かされた。', 'トルーマン=ドクトリン・マーシャル=プラン(1947年)から冷戦がはっきりし、ドイツは東西に分断された。', 'アジアでは中華人民共和国の成立、朝鮮戦争、ベトナム戦争と、冷戦が実際の戦争になった。', 'アジア・アフリカで脱植民地化が進み、1955年のアジア・アフリカ会議や1960年のアフリカの年に第三世界の台頭が表れた。', '日本は占領下の民主化から、冷戦のなかで経済復興重視へ変わり、1952年に独立を回復して高度経済成長をとげた。'],
    next: '次は「冷戦の終結とグローバル化(hs_global)」です。石油危機から冷戦の終わり、そして国境をこえて人・もの・お金が動く現代の世界と、その課題を学びます。'
  };

  L.hs_global = {
    goal: '1970年代の経済の転換から冷戦の終結までの流れを説明でき、グローバル化の進展とその光と影、現代の地球規模の課題について、日本と世界を結びつけて考えられるようになる。',
    intro: 'スマートフォンの部品は世界中の国でつくられ、私たちはインターネットで地球の裏側のニュースを瞬時に知ることができます。こうした「国境をこえたつながり」は、冷戦が終わった1990年代から一気に広がりました。しかし、つながりが深まったからこそ、一つの国の金融危機や感染症が世界中に広がるようにもなりました。この単元は、いま私たちが生きている世界がどうできたかを知る、歴史総合のしめくくりです。',
    pre: '前の単元で学んだように、戦後の世界は、アメリカ中心の西側とソ連中心の東側が対立する【冷戦】の時代でした。\n戦後の国際経済は、アメリカのドルを中心に通貨の交換比率を固定する【ブレトン=ウッズ体制】のもとで動いていました。日本は1ドル=360円の固定相場でした。\n日本は1950年代半ばから【高度経済成長】を続け、1968年には国民総生産(GNP)が資本主義国の中でアメリカに次ぐ第2位になりました。\n【グローバル化】とは、人・もの・お金・情報が国境をこえて地球規模で動き、世界の結びつきが強まることです。',
    secs: [
      { h: '1970年代の転換:ドル・ショックと石油危機', t: '1960年代、アメリカはベトナム戦争などで多くのドルを海外に支払い、経済の力が弱まっていました。1971年、ニクソン大統領はドルと金の交換を停止すると発表しました(【ドル・ショック】)。その後、1973年には主要国が、通貨の交換比率を市場で決める【変動相場制】に移りました。円の価値は上がり、円高が進んでいきます。\n1973年、【第4次中東戦争】が起きると、アラブの産油国は石油の価格を大幅に引き上げ、イスラエルを支持する国々への輸出を制限しました。これが【石油危機(オイル・ショック)】です。1979年にもイラン革命をきっかけに第2次石油危機が起きました。\n安い石油に頼って成長してきた先進国の経済は大きな打撃を受け、物価の上昇と不況が同時に起きました。日本でも物価が急に上がり、1974年には戦後初めてのマイナス成長となって、【高度経済成長は終わり】ました。\n日本の企業は、省エネルギーの技術開発や工場の自動化を進め、自動車や電気機械の輸出をのばして、ほかの先進国より早く危機を乗りこえました(安定成長)。\n世界経済の問題を話し合うため、1975年からは主要な先進国の首脳が集まる【サミット(先進国首脳会議)】が開かれるようになり、日本も最初から参加しました。',
        key: 'ドル・ショック(1971年)→ 変動相場制(1973年)。第4次中東戦争 → 石油危機(1973年)で日本の高度経済成長が終わる。1975年からサミット。',
        ex: [{ q: '1973年の石油危機が、日本の高度経済成長を終わらせたのはなぜか説明しよう。', hint: '日本の工業は、何を燃料・原料にして成長してきたかを考えます。', steps: ['日本の高度経済成長は、中東などから輸入する安い石油に支えられていた。', '第4次中東戦争をきっかけに、アラブの産油国が石油の価格を大幅に引き上げた。', '燃料や原料の費用が急に高くなり、物価が上がって企業の生産も落ちこんだ。', '1974年には戦後初めてのマイナス成長となり、高度経済成長は終わった。'], a: '日本の成長は安い輸入石油に支えられていたが、石油危機で石油の価格が急上昇して物価が上がり、生産が落ちこんだため、1974年に戦後初のマイナス成長となったから。', check: '「安い石油 → 価格の急上昇 → 物価上昇・生産の落ちこみ」の順につながっているか確かめます。' }] },
      { h: '新自由主義とアジアの経済成長', t: '1970年代の不況で、政府が大きな財政で経済を支えるやり方に限界が見えてきました。1980年代、イギリスの【サッチャー】首相やアメリカの【レーガン】大統領は、国営企業の民営化や規制の緩和、減税などで、市場の競争にまかせる政策を進めました。このような考え方を【新自由主義】といいます。日本でも中曽根康弘内閣のもとで、国鉄(現在のJR)などの民営化が行われました。\nアジアでは、韓国・台湾・香港・シンガポールが、輸出向けの工業で急速に成長し、【アジアNIES】(新興工業経済地域)とよばれました。\n中国では、1978年から【鄧小平】の指導で【改革開放】政策が始まりました。社会主義の体制を保ちながら、外国の資本や技術を取り入れ、市場経済を導入しました。中国はのちに「世界の工場」とよばれるほどの工業国になっていきます。\n日本は自動車などの輸出をのばし、アメリカとの間で貿易摩擦が深刻になりました。1985年、ドル高を是正するための先進国の合意(【プラザ合意】)で急速な円高が進むと、輸出企業は苦しみ(円高不況)、日本銀行は金利を下げました。\nその結果、余ったお金が土地や株に流れこみ、実際の経済の力をこえて価格がふくらむ【バブル経済】(1980年代後半)が起きました。1990年代初めにバブルが崩壊すると、日本経済は長い停滞の時期に入りました。',
        key: '新自由主義(サッチャー・レーガン・中曽根)、アジアNIES、中国の改革開放(1978年〜)。日本はプラザ合意(1985年)→ 円高 → 金融緩和 → バブル経済 → 1990年代初めに崩壊。',
        ex: [{ q: 'プラザ合意(1985年)から日本のバブル経済が生まれるまでの流れを説明しよう。', hint: '「円高 → 不況 → 金利 → お金の行き先」の順にたどります。', steps: ['プラザ合意で、ドル高を直すために各国が協力し、急速な円高が進んだ。', '円高で日本の製品が海外で高くなり、輸出企業が苦しむ円高不況になった。', '不況対策として、日本銀行が金利を下げ、お金を借りやすくした。', '借りやすくなったお金が土地や株の購入に流れこみ、価格が実際の価値をこえてふくらんだ(バブル経済)。'], a: 'プラザ合意で急速な円高が進み円高不況になった。その対策として金利が下げられ、余ったお金が土地や株に流れこんで、価格が異常にふくらむバブル経済が生まれた。', check: '世界の動き(プラザ合意)と日本の動き(バブル)が、因果の鎖でつながっているか確かめます。' }] },
      { h: '冷戦の終結とソ連の解体', t: '1979年、ソ連がアフガニスタンに侵攻すると、米ソの対立は再び強まりました(新冷戦)。しかし、軍事費の重い負担と計画経済の行きづまりで、ソ連の経済は深刻な停滞に陥っていました。\n1985年にソ連の指導者となった【ゴルバチョフ】は、【ペレストロイカ】(改革)と【グラスノスチ】(情報公開)をかかげて国内の改革を進め、外交ではアメリカとの対話を進めました。1987年には中距離核戦力(INF)全廃条約を結び、1989年にはアフガニスタンからの撤退を完了しました。\nソ連が東ヨーロッパの国々への介入をやめる姿勢を示すと、1989年、ポーランドやハンガリーなどで共産党の一党支配が次々にくずれました(【東欧革命】)。1989年11月には東西ベルリンを分けていた【ベルリンの壁】が崩壊し、12月の【マルタ会談】で、アメリカのブッシュ大統領とゴルバチョフが【冷戦の終結】を宣言しました。\n1990年に【ドイツが統一】され、1991年12月には、ソ連を構成していた共和国が独立して【ソ連が解体】しました。\n同じころ、アジアでは別の動きもありました。中国では1989年に民主化を求める学生や市民の運動が軍によって鎮圧されました(天安門事件)。一方、韓国では1987年に大統領の直接選挙が実現するなど、民主化が進みました。',
        key: 'ゴルバチョフの改革(1985年〜)→ 東欧革命・ベルリンの壁崩壊・マルタ会談(1989年)→ ドイツ統一(1990年)→ ソ連解体(1991年)。',
        chain: { title: '冷戦の終結', items: [
          ['背景', 'ソ連の経済の停滞と、アフガニスタン侵攻(1979年)による軍事費の負担'],
          ['できごと', 'ゴルバチョフがソ連の指導者に(1985年)', 'ペレストロイカ(改革)・グラスノスチ(情報公開)'],
          ['できごと', '東欧革命 → ベルリンの壁崩壊(1989年11月)'],
          ['結果', 'マルタ会談で冷戦の終結を宣言(1989年12月)', 'アメリカのブッシュ大統領とゴルバチョフ'],
          ['その後', 'ドイツ統一(1990年) → ソ連の解体(1991年12月)']] },
        ex: [{ q: '次のできごとを古い順に並べよう。ア ドイツ統一 イ ソ連の解体 ウ ベルリンの壁の崩壊 エ ゴルバチョフがソ連の指導者になる', hint: '改革 → 東欧の変化 → ドイツ → ソ連 の順です。', steps: ['1985年:ゴルバチョフがソ連の指導者となり、改革を始めた。→ エ', '1989年11月:東欧革命の中でベルリンの壁が崩壊した。→ ウ', '1990年:東西ドイツが統一された。→ ア', '1991年12月:ソ連が解体した。→ イ'], a: 'エ → ウ → ア → イ', check: '1985 → 1989 → 1990 → 1991 と、年が小さい順になっているか確かめます。' }] },
      { h: '冷戦後の世界:地域紛争とテロ', t: '冷戦が終わると、世界は平和になると期待されました。しかし実際には、それまで東西対立の陰におさえこまれていた民族や宗教の対立が表面化し、各地で【地域紛争】が起きました。\n1990年、イラクがクウェートに侵攻すると、翌1991年、アメリカを中心とする多国籍軍がイラクを攻撃しました(【湾岸戦争】)。日本は多額の資金を出しましたが、「人的な貢献がない」と批判され、1992年に【PKO協力法】を制定して、カンボジアに自衛隊を派遣しました。\nヨーロッパでは、多くの民族が暮らすユーゴスラヴィアが解体し、激しい内戦が起きました。アフリカのルワンダでも、民族対立から大規模な虐殺が起きました(1994年)。一方、南アフリカでは人種隔離政策(【アパルトヘイト】)が1991年に廃止され、1994年に【マンデラ】が大統領になりました。\n2001年9月11日、アメリカで【同時多発テロ】が起きました。アメリカは「テロとの戦い」をかかげて、同じ年にアフガニスタンを攻撃し、2003年にはイラク戦争を起こしました。国家ではない組織が大きな攻撃を起こすという、新しい形の脅威が現れたのです。\nこのように、冷戦後の世界では、国家どうしの戦争だけでなく、民族・宗教の対立やテロなど、さまざまな形の争いに向き合うことが課題になりました。',
        key: '冷戦後は民族・宗教の対立による地域紛争が表面化。湾岸戦争(1991年)を機に日本はPKO協力法(1992年)。2001年に同時多発テロ。',
        ex: [{ q: '湾岸戦争は、日本の国際貢献のあり方にどのような変化をもたらしたか説明しよう。', hint: '湾岸戦争のとき、日本が何をして、どう評価されたかを考えます。', steps: ['湾岸戦争(1991年)で、日本は多国籍軍に多額の資金を提供した。', 'しかし、国際社会からは「お金を出すだけで人を出さない」と批判された。', 'これをきっかけに、1992年にPKO協力法が制定された。', 'この法律にもとづき、自衛隊が国連の平和維持活動として初めてカンボジアに派遣された。'], a: '資金だけの協力が批判されたことをきっかけに、1992年にPKO協力法が制定され、自衛隊が国連の平和維持活動に参加するようになった(最初はカンボジア)。', check: '「資金の協力 → 批判 → PKO協力法 → 自衛隊の派遣」の流れになっているか確かめます。' }] },
      { h: 'グローバル化と地域統合', t: '冷戦が終わり、旧社会主義の国々も市場経済に加わると、世界は一つの大きな市場に近づきました。さらに【インターネット】などの情報通信技術が発達し、人・もの・お金・情報が国境をこえて大量かつ瞬時に動くようになりました。これが【グローバル化】です。\n自由な貿易のルールづくりも進みました。1995年には、GATTを発展させた【世界貿易機関(WTO)】が発足しました。また、近い地域の国どうしがまとまる【地域統合】も進みました。ヨーロッパでは、1993年にマーストリヒト条約が発効して【ヨーロッパ連合(EU)】が発足し、1999年には共通通貨【ユーロ】が導入されました(現金の流通は2002年から)。東南アジアには1967年からASEAN(東南アジア諸国連合)があり、アジア太平洋では1989年にAPEC(アジア太平洋経済協力)が始まりました。\nグローバル化には光と影があります。【光】としては、貿易の拡大で多くの国が経済成長し、世界の貧困は全体として減りました。私たちは安くて多様な商品を手に入れ、世界中の人と交流できるようになりました。\n【影】としては、国の中や国どうしの格差が広がったことや、ある国の金融危機がすぐに世界中に広がるようになったことが挙げられます。1997年のアジア通貨危機や、2008年にアメリカの大手証券会社の破綻から広がった世界金融危機(リーマン・ショック)がその例です。\n日本では、バブル崩壊後の長い不況の中で、企業が工場をアジアなどに移す動きが進み、国内の産業の空洞化や、非正規雇用の増加などが課題になりました。',
        key: 'グローバル化=人・もの・お金・情報が国境をこえて動くこと。WTO(1995年)、EU(1993年)・ユーロ(1999年)。光(成長・交流)と影(格差・危機の連鎖)がある。',
        ex: [{ q: 'グローバル化の「光」と「影」を、具体例を挙げて1つずつ説明しよう。', hint: '影は、「つながっているからこそ広がるもの」を考えます。', steps: ['光:貿易や投資が国境をこえて広がり、中国や東南アジアなどの国々が経済成長した。', '光の具体例として、私たちが安く多様な商品を買えるようになったことも挙げられる。', '影:世界の経済が強く結びついたため、ある国の金融危機がすぐに世界中に広がるようになった。', '影の具体例として、2008年のリーマン・ショックが世界的な不況を引き起こしたことが挙げられる。'], a: '光:貿易や投資の拡大で、多くの国が経済成長し、安く多様な商品が手に入るようになった。影:経済が強く結びついたため、2008年のリーマン・ショックのように、一国の金融危機が世界中に広がるようになった。', check: '光と影のそれぞれに、具体的なできごとが1つずつ入っているか確かめます。' }] },
      { h: '現代の課題と、歴史から考えること', t: 'グローバル化した世界では、一つの国だけでは解決できない【地球規模の課題】がふえています。\n【環境問題】では、1972年に国連人間環境会議(ストックホルム)、1992年に地球サミット(リオデジャネイロ)が開かれました。地球温暖化については、1997年に先進国に温室効果ガスの削減を義務づけた【京都議定書】、2015年にすべての国が削減に取り組む【パリ協定】が採択されました。同じ2015年には、国連で【持続可能な開発目標(SDGs)】が採択されました。\n【核兵器】については、1968年に核拡散防止条約(NPT)が結ばれ、2017年には核兵器の開発や保有などを禁止する核兵器禁止条約が採択されました(2021年発効)。唯一の戦争被爆国である日本は、核兵器のない世界をめざすと主張していますが、この条約には参加していません。\nほかにも、難民や移民の受け入れ、感染症の世界的な流行、少子高齢化、大規模な自然災害(1995年の阪神・淡路大震災、2011年の東日本大震災)など、多くの課題があります。\n歴史総合で学んできたように、現代の課題の多くには長い歴史的な背景があります。たとえば、アフリカや西アジアの紛争の一部は、植民地時代に引かれた国境線にさかのぼり、核兵器の問題は第二次世界大戦と冷戦にさかのぼります。\n大切なのは、「なぜ今こうなっているのか」を歴史の因果でたどり、日本と世界のつながりの中で考えることです。それが、これからの社会をつくる私たち一人ひとりの判断の土台になります。',
        key: '地球規模の課題(環境・核兵器・難民・感染症・災害)には歴史的な背景がある。京都議定書(1997年)・パリ協定とSDGs(2015年)。',
        ex: [{ q: '京都議定書(1997年)とパリ協定(2015年)のちがいを、「どの国が削減に取り組むか」に注目して説明しよう。', hint: '先進国だけか、すべての国か、を比べます。', steps: ['京都議定書は、先進国に温室効果ガスの削減を義務づけた。', '発展途上国には削減義務がなく、経済成長した中国やインドなどの排出の増加に対応しにくかった。', 'パリ協定は、先進国も発展途上国も含めたすべての国が、削減目標を立てて取り組むしくみにした。'], a: '京都議定書は先進国にだけ削減を義務づけたが、パリ協定は発展途上国も含むすべての国が、それぞれ削減目標を立てて取り組むしくみになった。', check: '「先進国だけ」と「すべての国」の対比がはっきり書かれているか確かめます。' }] },
      { h: 'もっと深く:なぜソ連型の経済は行きづまったのか', t: 'ソ連が解体した理由を「冷戦に負けたから」だけで説明すると、大事なしくみを見落とします。根本には、ソ連型の【計画経済】の行きづまりがありました。\n計画経済では、国家が「何を、どれだけ、いくらで」つくるかを決めます。重工業や軍事産業を急速に育てるには効果的で、ソ連は戦前から戦後にかけて工業大国になりました。\nしかし、経済が複雑になると弱点が表れます。計画の数字を達成することが目標になり、消費者がほしい品物や質の良さは後回しにされました。競争がないので、新しい技術を生み出す力も弱くなりました。1970〜80年代、西側でコンピューターなどの技術革新が進む中、ソ連は大きく取り残されていきます。\nさらに、アフガニスタンへの軍事侵攻(1979〜89年)が重い負担となり、主な輸出品だった石油の価格が1980年代に下がったことも、財政を苦しめました。1986年のチェルノブイリ原子力発電所事故は、情報をかくす体制の問題を表に出しました。\nこうした中で、1985年に指導者となった【ゴルバチョフ】は、【ペレストロイカ】(改革)と【グラスノスチ】(情報公開)を進めました。しかし、自由化は体制への批判や、各共和国の独立運動を強めることにもなり、1991年にソ連は解体します。\n同じ社会主義国でも、中国は共産党の一党支配を保ったまま、市場経済を取り入れる【改革開放】を進め、経済を成長させました。ソ連と中国の道のちがいは、「経済の改革」と「政治の改革」をどの順番で、どこまで進めたかのちがいとして比べることができます。',
        key: '計画経済は重工業化には強いが、消費財や技術革新に弱い。アフガニスタン侵攻・石油価格の下落も重なり、改革が体制の解体につながった。中国は政治体制を保ったまま市場経済を導入した。' },
      { h: '入試ではこう出る:グラフ・統計と時代を結びつける', t: '共通テストの歴史総合では、【グラフや統計】を読み取り、それがどの時代のどのできごとと結びつくかを判断する問題がよく出ます。この単元で押さえたい「形」は次の3つです。\n①【日本の実質経済成長率】:1950年代半ばから1973年ごろまでは年平均で約10%近い高い成長が続き、1974年に戦後初めてマイナス成長になります。これは1973年の【第1次石油危機】の影響です。その後は4〜5%前後の安定成長が続き、1990年代初めのバブル崩壊後は低い成長が続きます。\n②【円とドルの為替相場】:1949年から1ドル=360円の固定相場。1971年のドル・ショック後に308円に切り上げられ、1973年に変動相場制へ移行します。1985年の【プラザ合意】のあと、円高が急速に進みました。\n③【原油価格】:1973年の第4次中東戦争と1979年のイラン革命をきっかけに、2度の石油危機で大きく上がります。\nグラフ問題の解き方の型は、まず【大きな変化が起きた年】を見つけ、その年の前後に起きたできごとを思い出すことです。細かい数値を覚える必要はありません。「急に上がった・下がった・向きが変わった」点に注目しましょう。\nもう一つの定番は、冷戦終結後の地域統合についての正誤問題です。【マーストリヒト条約】(1992年調印)で1993年に【EU】が発足し、共通通貨【ユーロ】は1999年に導入され、2002年から紙幣・硬貨の流通が始まりました。イギリスは国民投票(2016年)を経て、2020年にEUを離脱しています。',
        key: 'グラフは「大きく変化した年」を見つけ、その年のできごとと結びつける。1974年のマイナス成長=石油危機、1985年以降の急な円高=プラザ合意。',
        ex: [
          { q: 'あるグラフでは、日本の実質経済成長率が、それまでの年平均約10%前後から、ある年に初めてマイナスになっていた。その年と、原因となったできごとを答えよう。', hint: '高度経済成長が終わったきっかけを思い出します。', steps: ['高度経済成長は1950年代半ばから1970年代前半まで続いた。', '1973年に第4次中東戦争が起き、アラブの産油国が原油価格を大きく引き上げた(第1次石油危機)。', '原油を輸入にたよる日本では物価が急上昇し、経済が混乱した。', 'その結果、翌1974年に戦後初めてのマイナス成長となった。'], a: '1974年。原因は、1973年の第4次中東戦争をきっかけとする第1次石油危機。', check: 'グラフの「変化した年」と、その前年に起きた原因のできごとが、時間の順番として合っているか確かめます。' },
          { q: 'ヨーロッパの統合について述べた次の文の正誤を判定し、誤りは正しく直そう。\nア マーストリヒト条約にもとづき、1993年にEUが発足した。\nイ 共通通貨ユーロは、EU発足と同時に紙幣・硬貨の流通が始まった。\nウ イギリスは国民投票の結果を受けて、2020年にEUを離脱した。', hint: 'ユーロの「導入」と「紙幣・硬貨の流通」の年を区別します。', steps: ['ア:マーストリヒト条約は1992年調印、1993年発効でEUが発足した。正しい。', 'イ:ユーロの導入は1999年、紙幣・硬貨の流通は2002年から。EU発足(1993年)と同時ではない。誤り。', 'ウ:2016年の国民投票で離脱が多数となり、2020年に離脱した。正しい。'], a: 'ア 正しい、イ 誤り(導入は1999年、紙幣・硬貨の流通は2002年から)、ウ 正しい', check: 'EU発足(1993年)→ユーロ導入(1999年)→流通開始(2002年)→イギリス離脱(2020年)の順になっているか確かめます。' }
        ] }
    ],
    drill: [
      { lv: 1, q: '1985年にソ連の指導者となり、ペレストロイカを進めた人物はだれ?', a: 'ゴルバチョフ', exp: 'ゴルバチョフは、行きづまった経済を立て直すためにペレストロイカ(改革)を、体制の問題を明らかにするためにグラスノスチ(情報公開)を進めました。\n外交では「新思考外交」をとなえ、アメリカとの軍縮やアフガニスタンからの撤退を進めました。1989年のマルタ会談で、冷戦の終結が宣言されます。' },
      { lv: 1, q: '1989年、北京で民主化を求めて集まった学生や市民を、中国政府が軍隊で鎮圧した事件を何という?', a: '天安門事件', exp: '中国は改革開放で経済の自由化を進めましたが、政治の民主化は認めませんでした。\n同じ1989年に東ヨーロッパでは共産党政権が次々に倒れましたが、中国では共産党の一党支配が続きました。ソ連・東欧と中国の道が分かれた年として押さえましょう。' },
      { lv: 1, q: '1960年代から1980年代にかけて急速に工業化した、韓国・台湾・香港・シンガポールをまとめて何という?', a: 'アジアNIES(新興工業経済地域)', exp: 'これらの国・地域は、安い労働力を生かし、輸出向けの工業を育てる「輸出志向型」の工業化で成長しました。\nのちにASEAN諸国や中国も同じような道をたどり、東アジアは「世界の成長センター」とよばれるようになります。' },
      { lv: 2, q: '1980年代のイギリスとアメリカで進められた新自由主義の政策を、指導者の名前とともに説明しよう。また、同じ時期に日本で行われた同様の政策の例を挙げよう。', a: 'イギリスのサッチャー首相やアメリカのレーガン大統領は、国営企業の民営化や規制緩和、減税などを進め、政府の役割を小さくして市場の競争にまかせようとした。日本でも中曽根康弘内閣のもとで、電電公社(現在のNTT)・専売公社(現在のJT)・国鉄(現在のJRグループ)の民営化が行われた。', exp: '石油危機のあと、先進国では不況と物価上昇が同時に起こり、福祉国家の財政負担が重くなりました。\nそこで、「大きな政府」から「小さな政府」へ転換しようとしたのが新自由主義です。\n採点のポイントは、①民営化・規制緩和などの政策の中身、②指導者名(サッチャー・レーガン)、③日本の三公社の民営化、の3点です。' },
      { lv: 2, q: '1991年の湾岸戦争のあと、日本が初めて自衛隊を国連平和維持活動(PKO)に参加させた国はどこ?また、そのもとになった法律は何?', a: 'カンボジア。国連平和維持活動協力法(PKO協力法、1992年制定)。', exp: '湾岸戦争で日本は多額の資金を出しましたが、「人的な貢献がない」と国際的に批判されました。\nこれを受けて1992年にPKO協力法が制定され、同じ年にカンボジアへ自衛隊が派遣されました。\n冷戦後の日本の国際貢献のあり方が、大きく変わった転機として押さえましょう。' },
      { lv: 3, q: 'ソ連と中国はどちらも社会主義国だったが、1980〜90年代に異なる道をたどった。経済と政治の改革の進め方に注目して、そのちがいを説明しよう。', a: 'ソ連では、ゴルバチョフが経済の改革(ペレストロイカ)と同時に、情報公開(グラスノスチ)などの政治の自由化も進めたため、体制への批判や各共和国の独立運動が強まり、1991年にソ連は解体した。一方、中国は改革開放で市場経済を取り入れて経済の自由化を進めたが、政治では共産党の一党支配を保ち、1989年の天安門事件のように民主化の動きをおさえた。その結果、体制を維持したまま経済成長を続けた。', exp: 'このテーマは、「比較」の論述の典型です。共通点(社会主義・計画経済の行きづまり)を前提に、ちがい(政治の自由化の有無)を軸に書きます。\n採点のポイントは、①ソ連=経済と政治の改革を同時に進めた→解体、②中国=経済は自由化、政治は一党支配を維持→体制維持と成長、の対比がはっきりしているかです。\n「どちらが正しかったか」を書く必要はありません。事実にもとづいてちがいを示しましょう。' },
      { lv: 3, q: '冷戦が終わったあと、旧ユーゴスラヴィアで激しい紛争が起きた理由を説明しよう。', a: 'ユーゴスラヴィアは多くの民族や宗教をかかえる連邦国家で、冷戦の時代は指導者ティトーのもと、独自の社会主義体制でまとまっていた。しかし、ティトーの死後に経済が悪化し、冷戦の終結で東欧の社会主義体制が崩れると、各共和国で民族主義が高まった。1991年にスロヴェニアやクロアチアが独立を宣言し、民族の分布が入り組んだボスニア=ヘルツェゴヴィナなどで激しい内戦が起きた。', exp: '冷戦の時代には、東西の対立という大きなわくが、各国の内部の対立を表に出にくくしていた面がありました。\nそのわくが外れたことで、民族や宗教のちがいが政治の対立として表れたのです。\n採点のポイントは、①多民族・多宗教の連邦国家、②ティトーの死と経済の悪化、③冷戦終結と民族主義の高まり、④独立宣言と内戦、の流れです。「冷戦の終結→地域紛争」という一般的な傾向の具体例として書けるとよいでしょう。' }
    ],
    faq: [
      ['冷戦が終わったのに、なぜ世界から紛争がなくならないの?', '冷戦中は、米ソがそれぞれの陣営の国々をおさえこむことで、民族や宗教の対立が表に出にくくなっていた面がありました。\n冷戦が終わってそのおさえがなくなると、ユーゴスラヴィアのように、長く押しこめられていた対立が一気に噴き出した地域もあります。'],
      ['グローバル化は良いことなの?悪いことなの?', 'どちらか一方とは言えません。経済成長や交流の拡大という良い面と、格差の拡大や危機の連鎖という課題の両面があります。\n大切なのは、良い面を生かしながら、課題をどう小さくするかを考えることです。入試や授業でも、両面を挙げて論じることが求められます。'],
      ['歴史総合で学んだことは、どう役に立つの?', 'ニュースで見る国際問題や日本の課題の多くは、この科目で学んだ近代化・大衆化・グローバル化の流れの上にあります。\n「いつ、なぜ、どこで始まったのか」をたどれるようになると、ニュースの意味が深く分かるようになり、自分の意見をもつ手がかりになります。'],
      ['グローバル化は、冷戦が終わってから始まったの?', '「人・もの・お金・情報が国境をこえて動く」という意味では、もっと前から始まっていました。たとえば19世紀後半には、蒸気船・鉄道・電信によって世界の結びつきが強まり、ヨーロッパからアメリカへ大量の移民が渡りました。これを「第1のグローバル化」とよぶこともあります。\n冷戦後のグローバル化の特徴は、①東西に分かれていた市場が一つになったこと、②インターネットなどの情報技術によって、動く量と速さがけた違いに大きくなったこと、にあります。\n歴史総合で学んだように、結びつきが強まる時代と、ブロック経済のように閉ざされる時代は、くり返しやってきます。']
    ],
    terms: [['ドル・ショック', '1971年、アメリカがドルと金の交換を停止したこと'], ['石油危機', '1973年、第4次中東戦争をきっかけに原油価格が急上昇したこと。1979年にも起きた'], ['新自由主義', '民営化・規制緩和などで、市場の競争にまかせることを重視する考え方'], ['改革開放', '1978年から鄧小平の指導で中国が進めた、市場経済の導入と対外開放の政策'], ['マルタ会談', '1989年、米ソの首脳が冷戦の終結を宣言した会談'], ['グローバル化', '人・もの・お金・情報が国境をこえて地球規模で動き、世界の結びつきが強まること'], ['EU(ヨーロッパ連合)', '1993年に発足した、ヨーロッパの国々の政治・経済の統合をめざす組織'], ['パリ協定', '2015年に採択された、すべての国が温室効果ガスの削減に取り組む国際的な枠組み']],
    miss: ['ベルリンの壁の崩壊(1989年)と、ドイツ統一(1990年)、ソ連の解体(1991年)を同じ年だと思う。「壁 → 統一 → 解体」と1年ずつずれていると覚えます。', 'ドル・ショック(1971年)と石油危機(1973年)を混同する。ドル・ショックは通貨(ドルと金の交換停止)、石油危機は資源(原油価格の高騰)の問題です。', 'バブル経済をプラザ合意の「円安」の結果と考える。プラザ合意で進んだのは円高です。円高不況への対策としての低金利がバブルの背景です。', 'グローバル化を「良いこと」か「悪いこと」かの一方だけで論じる。必ず光と影の両面を、具体例を挙げて述べるようにします。'],
    sum: ['ドル・ショック(1971年)と石油危機(1973年)で戦後の経済成長は転換し、日本の高度経済成長も終わった。', '1980年代、新自由主義が広がり、アジアNIESや改革開放の中国が成長した。日本はプラザ合意後にバブル経済となった。', 'ゴルバチョフの改革から東欧革命・ベルリンの壁の崩壊(1989年)を経て、1991年にソ連が解体し、冷戦が終わった。', '冷戦後は地域紛争やテロが課題となり、日本はPKO協力法(1992年)で国際貢献の形を広げた。', 'グローバル化と地域統合が進む一方、格差・金融危機・環境・核兵器などの地球規模の課題に、歴史をふまえて向き合うことが求められている。'],
    next: '歴史総合はここで一区切りです。さらに深く学ぶなら、日本史は「日本史探究(c_h1)」、世界史は「世界史探究(c_h2)」へ進みましょう。この科目で身につけた「日本と世界をつなげて、因果でたどる」見方が、そのまま探究科目の土台になります。'
  };
})(WPS.LESSONS);
